		private async Task RefreshInterfacesAsync(bool showBusy)
		{
			if (_isCapturing)
			{
				return;
			}
			if (string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				_usbPcapInterfaces.Clear();
				RefreshDynamicTexts();
				return;
			}
			string previousInterfaceName = GetSelectedInterface()?.InterfaceName;
			try
			{
				if (showBusy)
				{
					SetBusyState(isBusy: true, L("BluetoothCaptureHelperWindow.CaptureStatus.RefreshingInterfaces", "Current status: Refreshing USBPcap interfaces..."));
				}
				List<UsbPcapInterfaceItem> list = await GetUsbPcapInterfacesAsync();
				_usbPcapInterfaces.Clear();
				foreach (UsbPcapInterfaceItem item in list)
				{
					_usbPcapInterfaces.Add(item);
				}
				UsbPcapInterfaceItem usbPcapInterfaceItem = _usbPcapInterfaces.FirstOrDefault((UsbPcapInterfaceItem item) => string.Equals(item.InterfaceName, previousInterfaceName, StringComparison.OrdinalIgnoreCase));
				UsbPcapInterfaceComboBox.SelectedItem = usbPcapInterfaceItem ?? _usbPcapInterfaces.FirstOrDefault((UsbPcapInterfaceItem item) => item.IsLikelyBluetooth) ?? _usbPcapInterfaces.FirstOrDefault();
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.InterfacesRefreshed.Template", "USBPcap interfaces refreshed: {0}", string.Join(", ", _usbPcapInterfaces.Select((UsbPcapInterfaceItem item) => item.DisplayName))));
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Failed to refresh USBPcap interfaces: " + ex.Message, "RefreshInterfacesAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 578);
				_usbPcapInterfaces.Clear();
				InterfaceStatusText.Text = LF("BluetoothCaptureHelperWindow.Interface.Status.Error.Template", "USBPcap interface refresh failed: {0}", ex.Message);
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.InterfaceRefreshError.Template", "USBPcap interface refresh failed: {0}", ex.Message));
			}
			finally
			{
				if (showBusy)
				{
					SetBusyState(isBusy: false);
				}
				RefreshDynamicTexts();
				UpdateIdleCaptureStatus();
			}
		}

		private async Task<List<UsbPcapInterfaceItem>> GetUsbPcapInterfacesAsync()
		{
			if (string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				throw new InvalidOperationException(L("BluetoothCaptureHelperWindow.Error.UsbPcapMissing", "USBPcapCmd.exe was not found."));
			}
			string input = await ExecuteReadProcessAsync(_resolvedUsbPcapPath, "--extcap-interfaces");
			List<UsbPcapInterfaceItem> interfaces = (from @group in (from usbPcapInterfaceItem in _interfaceRegex.Matches(input).Select(delegate(Match match)
					{
						string interfaceName = match.Groups[1].Value.Trim();
						string displayName = ((match.Groups.Count > 2) ? match.Groups[2].Value.Trim() : string.Empty);
						return new UsbPcapInterfaceItem(interfaceName, displayName);
					})
					where !string.IsNullOrWhiteSpace(usbPcapInterfaceItem.InterfaceName)
					select usbPcapInterfaceItem).GroupBy<UsbPcapInterfaceItem, string>((UsbPcapInterfaceItem usbPcapInterfaceItem) => usbPcapInterfaceItem.InterfaceName, StringComparer.OrdinalIgnoreCase)
				select @group.First()).ToList();
			foreach (UsbPcapInterfaceItem item in interfaces)
			{
				string configText = await TryGetInterfaceConfigAsync(item.InterfaceName);
				item.UpdateBluetoothHint(configText, BuildBluetoothHint(configText));
			}
			Logger.A($"[BluetoothCaptureHelperWindow] USBPcap interfaces enumerated: count={interfaces.Count}, interfaces={string.Join(", ", interfaces.Select((UsbPcapInterfaceItem usbPcapInterfaceItem) => usbPcapInterfaceItem.DisplayName))}", "GetUsbPcapInterfacesAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 627);
			return interfaces;
		}

		private async Task<string> TryGetInterfaceConfigAsync(string interfaceName)
		{
			try
			{
				return await ExecuteReadProcessAsync(_resolvedUsbPcapPath, "--extcap-interface " + QuoteArgument(interfaceName) + " --extcap-config");
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Failed to query USBPcap config for " + interfaceName + ": " + ex.Message, "TryGetInterfaceConfigAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 641);
				return string.Empty;
			}
		}

		private BluetoothHint BuildBluetoothHint(string configText)
		{
			if (string.IsNullOrWhiteSpace(configText))
			{
				return new BluetoothHint(IsLikelyBluetooth: false, L("BluetoothCaptureHelperWindow.InterfaceHint.Unknown", "No Bluetooth keyword detected; try manually if needed."));
			}
			string[] array = new string[14]
			{
				"Bluetooth", "Wireless Bluetooth", "Intel(R) Wireless Bluetooth", "Intel Wireless Bluetooth", "Realtek Bluetooth", "MediaTek Bluetooth", "Qualcomm Bluetooth", "CSR Bluetooth", "Broadcom Bluetooth", "RZ616 Bluetooth",
				"AX200 Bluetooth", "AX201 Bluetooth", "AX210 Bluetooth", "AX211 Bluetooth"
			};
			string[] array2 = array;
			foreach (string text in array2)
			{
				if (configText.Contains(text, StringComparison.OrdinalIgnoreCase))
				{
					return new BluetoothHint(IsLikelyBluetooth: true, LF("BluetoothCaptureHelperWindow.InterfaceHint.LikelyBluetooth.Template", "Likely Bluetooth controller: {0}", text));
				}
			}
			return new BluetoothHint(IsLikelyBluetooth: false, L("BluetoothCaptureHelperWindow.InterfaceHint.Unknown", "No Bluetooth keyword detected; try manually if needed."));
		}

		private async Task StartCaptureAsync()
		{
			if (!_environmentReady || string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				await ShowInfoDialogAsync(L("BluetoothCaptureHelperWindow.Dialog.EnvNotReady.Title", "Environment Not Ready"), L("BluetoothCaptureHelperWindow.Dialog.EnvNotReady.Content", "USBPcapCmd.exe was not found. Install USBPcap, restart Windows if required, then run the environment check again."), L("Common.OK", "OK"));
				return;
			}
			UsbPcapInterfaceItem selectedInterface = GetSelectedInterface();
			if (selectedInterface != null)
			{
				ClearCaptureArtifactReferences();
				_captureStartedAt = System.DateTimeOffset.Now;
				_currentOutputDirectory = ResolveCaptureOutputDirectory();
				_currentCapturePath = System.IO.Path.Combine(_currentOutputDirectory, $"BluetoothUsbPcap_{DateTime.Now:yyyyMMdd_HHmmss}.pcap");
				Logger.A($"[BluetoothCaptureHelperWindow] Start USBPcap Bluetooth capture requested: interface={selectedInterface.InterfaceName}, usbPcapPath={FormatLogValue(_resolvedUsbPcapPath)}, output={_currentCapturePath}", "StartCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 708);
				RefreshDynamicTexts();
				SetBusyState(isBusy: true, L("BluetoothCaptureHelperWindow.CaptureStatus.Starting", "Current status: Requesting admin permission and starting USBPcap capture..."));
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.CaptureStarting.Template", "Preparing USBPcap capture on {0}", selectedInterface.ShortName));
				try
				{
					try
					{
						b.x x = await TryCreateLiveCaptureSessionAsync();
						if (x != null)
						{
							_liveCaptureSession = x;
							_useLivePipeCapture = true;
							_useFilePollingFallback = false;
						}
						else
						{
							_useLivePipeCapture = false;
							_useFilePollingFallback = true;
						}
						StartCaptureProcess();
						_isCapturing = true;
						StartCaptureMonitor();
						if (_useLivePipeCapture && _liveCaptureSession != null)
						{
							if (!(await _liveCaptureSession.A(System.TimeSpan.FromSeconds(5.0))))
							{
								await RestartCaptureWithFilePollingFallbackAsync();
							}
							else
							{
								LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.LivePipe", "Status: reading USBPcap packets in real time...");
							}
						}
						CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.Capturing", "Current status: Capturing");
						AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.CaptureStarted", "USBPcap capture started. Trigger Steam/DS4Windows or the device battery query now."));
					}
					catch (Win32Exception ex) when (ex.NativeErrorCode == 1223)
					{
						Logger.a("[BluetoothCaptureHelperWindow] Start capture canceled by UAC.", "StartCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 754);
						StopCaptureProcess();
						await StopLiveCaptureSessionAsync();
						ClearCaptureArtifactReferences();
						_useLivePipeCapture = false;
						_useFilePollingFallback = false;
						CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.UacDenied", "Current status: Canceled (user denied admin permission)");
						AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.UacDenied", "The user canceled admin authorization, so USBPcap capture did not start."));
						await ShowInfoDialogAsync(L("BluetoothCaptureHelperWindow.Dialog.Canceled.Title", "Canceled"), L("BluetoothCaptureHelperWindow.Dialog.Canceled.Content", "You canceled the admin authorization (UAC), so USBPcap capture did not start."), L("Common.OK", "OK"));
					}
					catch (System.Exception ex2)
					{
						StopCaptureProcess();
						await StopLiveCaptureSessionAsync();
						ClearCaptureArtifactReferences();
						_useLivePipeCapture = false;
						_useFilePollingFallback = false;
						CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.StartFailed", "Current status: Failed to start capture");
						AppendLiveEvent(BuildCaptureStartFailedLiveEvent(ex2.Message));
						Logger.A("[BluetoothCaptureHelperWindow] Start USBPcap Bluetooth capture threw an exception.", ex2, "StartCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 776);
						await ShowInfoDialogAsync(L("BluetoothCaptureHelperWindow.Dialog.StartFailed.Title", "Start Failed"), BuildCaptureStartFailedDialogContent(ex2.Message), L("Common.OK", "OK"));
					}
					return;
				}
				finally
				{
					SetBusyState(isBusy: false);
					RefreshDynamicTexts();
				}
			}
			await ShowInfoDialogAsync(L("BluetoothCaptureHelperWindow.Dialog.InterfaceMissing.Title", "USBPcap interface not selected"), L("BluetoothCaptureHelperWindow.Dialog.InterfaceMissing.Content", "Select USBPcap1/2/3 before starting Bluetooth capture."), L("Common.OK", "OK"));
		}

		private async Task StopCaptureAsync()
		{
			if (!_isCapturing)
			{
				return;
			}
			Logger.A("[BluetoothCaptureHelperWindow] Stop USBPcap Bluetooth capture requested: path=" + (_currentCapturePath ?? "<none>") + ", startedAt=" + (_captureStartedAt?.ToString("O") ?? "null"), "StopCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 796);
			SetBusyState(isBusy: true, L("BluetoothCaptureHelperWindow.CaptureStatus.Stopping", "Current status: Stopping capture..."));
			try
			{
				StopCaptureMonitor();
				StopCaptureProcess();
				if (_useFilePollingFallback)
				{
					await ReadAvailableFilePacketsAsync();
				}
				await StopLiveCaptureSessionAsync();
				_isCapturing = false;
				_useLivePipeCapture = false;
				_useFilePollingFallback = false;
				if (!string.IsNullOrWhiteSpace(_currentCapturePath) && File.Exists(_currentCapturePath))
				{
					_finalKeptCapturePath = _currentCapturePath;
					CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.CompletedFullOnly", "Current status: Capture complete, keeping the .pcap file");
					AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.CaptureStopped", "Capture stopped. The .pcap file was kept."));
				}
				else
				{
					CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.StopFailed", "Current status: Capture stopped, but the .pcap file was not found");
					AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.CaptureFileMissing", "Capture stopped, but the .pcap file was not found. Check whether USBPcap started successfully."));
				}
				if (!string.IsNullOrWhiteSpace(_currentOutputDirectory))
				{
					await OpenOutputFolderAsync(_currentOutputDirectory);
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Post-stop processing failed: " + ex.Message, "StopCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 834);
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.StopPipelineError.Template", "Post-stop processing failed: {0}", ex.Message));
				CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.StopPipelineFailed", "Current status: Post-stop processing failed");
			}
			finally
			{
				_captureStartedAt = null;
				SetBusyState(isBusy: false);
				RefreshDynamicTexts();
			}
		}

		private void StartCaptureProcess()
		{
			ProcessStartInfo startInfo = new ProcessStartInfo
			{
				FileName = _resolvedUsbPcapPath,
				Arguments = BuildCaptureArguments(),
				UseShellExecute = true,
				Verb = "runas",
				WindowStyle = ProcessWindowStyle.Minimized
			};
			_captureProcess = Process.Start(startInfo) ?? throw new InvalidOperationException(L("BluetoothCaptureHelperWindow.Error.CaptureStartFailed", "Unable to start USBPcap capture process."));
		}

		private string BuildCaptureArguments()
		{
			if (string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				throw new InvalidOperationException("Capture output path is missing.");
			}
			UsbPcapInterfaceItem usbPcapInterfaceItem = GetSelectedInterface() ?? throw new InvalidOperationException(L("BluetoothCaptureHelperWindow.Error.InterfaceMissing", "USBPcap interface is not selected."));
			string value = ((_useLivePipeCapture && _liveCaptureSession != null) ? _liveCaptureSession.PipePath : _currentCapturePath);
			return "-d " + QuoteArgument(usbPcapInterfaceItem.InterfaceName) + " --capture-from-all-devices --inject-descriptors -b 4096 -o " + QuoteArgument(value);
		}

		private async Task<b.x?> TryCreateLiveCaptureSessionAsync()
		{
			if (string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				return null;
			}
			b.x session = null;
			try
			{
				session = new b.x(_currentCapturePath);
				WireLiveCaptureSession(session);
				session.A();
				if (!(await session.a(System.TimeSpan.FromSeconds(2.0))))
				{
					UnwireLiveCaptureSession(session);
					await session.DisposeAsync();
					AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.LivePipeFallbackMessage", "Live pipe is unavailable; falling back to file refresh."));
					return null;
				}
				AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.LivePipeStarted", "Live pipe reader is ready."));
				return session;
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Start live USBPcap pipe failed: " + ex.Message, "TryCreateLiveCaptureSessionAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 906);
				if (session != null)
				{
					UnwireLiveCaptureSession(session);
					await session.DisposeAsync();
				}
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.LivePipeFallback.Template", "Live pipe unavailable, falling back to file refresh: {0}", ex.Message));
				return null;
			}
		}

		private async Task RestartCaptureWithFilePollingFallbackAsync()
		{
			if (!string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.LivePipeFallbackMessage", "Live pipe did not connect; falling back to file refresh."));
				StopCaptureMonitor();
				try
				{
					StopCaptureProcess();
				}
				finally
				{
					await StopLiveCaptureSessionAsync();
				}
				_useLivePipeCapture = false;
				_useFilePollingFallback = true;
				_pcapReader = null;
				StartCaptureProcess();
				StartCaptureMonitor();
			}
		}

		private async Task StopLiveCaptureSessionAsync()
		{
			b.x session = _liveCaptureSession;
			if (session == null)
			{
				return;
			}
			_liveCaptureSession = null;
			UnwireLiveCaptureSession(session);
			try
			{
				if (await Task.WhenAny(session.Completion, Task.Delay(System.TimeSpan.FromMilliseconds(800.0))) == session.Completion)
				{
					await session.Completion.ConfigureAwait(continueOnCapturedContext: false);
				}
				await session.DisposeAsync();
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Stop live USBPcap pipe failed: " + ex.Message, "StopLiveCaptureSessionAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 967);
			}
		}

		private void WireLiveCaptureSession(b.x session)
		{
			session.PacketsRead += LiveCaptureSession_PacketsRead;
			session.StatusChanged += LiveCaptureSession_StatusChanged;
			session.Failed += LiveCaptureSession_Failed;
		}

		private void UnwireLiveCaptureSession(b.x session)
		{
			session.PacketsRead -= LiveCaptureSession_PacketsRead;
			session.StatusChanged -= LiveCaptureSession_StatusChanged;
			session.Failed -= LiveCaptureSession_Failed;
		}

		private void LiveCaptureSession_PacketsRead(IReadOnlyList<b.Y> rawPackets)
		{
			if (rawPackets.Count != 0)
			{
				int count = rawPackets.Count;
				Interlocked.Add(ref _parsedPacketCount, count);
				base.DispatcherQueue.TryEnqueue(delegate
				{
					RecordCaptureActivity(count, 0L);
				});
			}
		}

		private void LiveCaptureSession_StatusChanged(string status)
		{
			base.DispatcherQueue.TryEnqueue(delegate
			{
				if (string.Equals(status, "connected", StringComparison.OrdinalIgnoreCase))
				{
					LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.LivePipe", "Status: reading USBPcap packets in real time...");
				}
				else if (string.Equals(status, "waiting", StringComparison.OrdinalIgnoreCase))
				{
					LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.LivePipeWaiting", "Status: waiting for live pipe connection...");
				}
			});
		}

		private void LiveCaptureSession_Failed(System.Exception ex)
		{
			Logger.a("[BluetoothCaptureHelperWindow] Live USBPcap pipe failed: " + ex.Message, "LiveCaptureSession_Failed", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 1014);
			base.DispatcherQueue.TryEnqueue(delegate
			{
				LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.Error", "Status: Activity monitor error");
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.LivePipeError.Template", "Live pipe error: {0}", ex.Message));
			});
		}

		private void StopCaptureProcess()
		{
			Process captureProcess = _captureProcess;
			_captureProcess = null;
			if (captureProcess == null)
			{
				return;
			}
			try
			{
				if (!captureProcess.HasExited)
				{
					captureProcess.Kill(entireProcessTree: true);
					captureProcess.WaitForExit(3000);
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Failed to stop USBPcap process: " + ex.Message, "StopCaptureProcess", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 1042);
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.StopFailed.Template", "Failed to stop USBPcap process: {0}", ex.Message));
			}
			finally
			{
				captureProcess.Dispose();
			}
		}

		private void StartCaptureMonitor()
		{
			StopCaptureMonitor();
			if (_useFilePollingFallback && !string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				_pcapReader = new b.X(_currentCapturePath);
			}
			else
			{
				_pcapReader = null;
			}
			_lastCaptureFileSize = 0L;
			_captureActivityCount = 0;
			_lastCaptureActivityAt = null;
			_parsedPacketCount = 0;
			LiveDataCounterText.Text = LF("BluetoothCaptureHelperWindow.LiveCount.Template", "Activity count: {0}", _captureActivityCount);
			LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.Waiting", "Status: Waiting for USBPcap packets...");
			LiveDataLastText.Text = L("BluetoothCaptureHelperWindow.LiveLast.Pending", "Last activity: -");
			_captureMonitorTimer = base.DispatcherQueue.CreateTimer();
			_captureMonitorTimer.Interval = System.TimeSpan.FromMilliseconds(500.0);
			_captureMonitorTimer.IsRepeating = true;
			_captureMonitorTimer.Tick += CaptureMonitorTimer_Tick;
			_captureMonitorTimer.Start();
		}

		private void StopCaptureMonitor()
		{
			if (!(_captureMonitorTimer == null))
			{
				_captureMonitorTimer.Stop();
				_captureMonitorTimer.Tick -= CaptureMonitorTimer_Tick;
				_captureMonitorTimer = null;
			}
		}

		private async void CaptureMonitorTimer_Tick(Microsoft.UI.Dispatching.DispatcherQueueTimer sender, object args)
		{
			if (!_isCapturing || string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				return;
			}
			try
			{
				if (_captureProcess != null && _captureProcess.HasExited)
				{
					if (_useFilePollingFallback)
					{
						await ReadAvailableFilePacketsAsync();
					}
					_isCapturing = false;
					StopCaptureMonitor();
					CaptureStatusText.Text = L("BluetoothCaptureHelperWindow.CaptureStatus.ProcessExited", "Current status: Capture process exited");
					LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.ProcessExited", "Status: Capture process exited");
					AppendLiveEvent(L("BluetoothCaptureHelperWindow.LiveEvent.ProcessExited", "Capture process exited. Check the output file."));
					_captureProcess.Dispose();
					_captureProcess = null;
					UpdateCaptureButtonState();
				}
				else if (_useLivePipeCapture)
				{
					LiveDataStateText.Text = (_lastCaptureActivityAt.HasValue ? L("BluetoothCaptureHelperWindow.LiveState.LivePipe", "Status: reading USBPcap packets in real time...") : L("BluetoothCaptureHelperWindow.LiveState.LivePipeWaiting", "Status: waiting for live pipe packets..."));
				}
				else if (!File.Exists(_currentCapturePath))
				{
					LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.WaitingFile", "Status: Waiting for .pcap file to be created...");
				}
				else
				{
					long fileSize = new FileInfo(_currentCapturePath).Length;
					long delta = Math.Max(fileSize - _lastCaptureFileSize, 0L);
					int packetCount = await ReadAvailableFilePacketsAsync();
					if (fileSize > _lastCaptureFileSize)
					{
						_lastCaptureFileSize = fileSize;
						RecordCaptureActivity(packetCount, delta);
					}
					else
					{
						LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.Waiting", "Status: Waiting for USBPcap packets...");
					}
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Failed to monitor .pcap file: " + ex.Message, "CaptureMonitorTimer_Tick", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 1147);
				LiveDataStateText.Text = L("BluetoothCaptureHelperWindow.LiveState.Error", "Status: Activity monitor error");
			}
		}

		private async Task<int> ReadAvailableFilePacketsAsync()
		{
			if (_pcapReader == null)
			{
				return 0;
			}
			if (Interlocked.Exchange(ref _fileReadInProgress, 1) == 1)
			{
				return 0;
			}
			try
			{
				b.X pcapReader = _pcapReader;
				IReadOnlyList<b.Y> readOnlyList = await Task.Run((Func<IReadOnlyList<b.Y>>)pcapReader.A);
				if (readOnlyList.Count > 0)
				{
					Interlocked.Add(ref _parsedPacketCount, readOnlyList.Count);
				}
				return readOnlyList.Count;
			}
			catch (System.Exception ex)
			{
				Logger.a("[BluetoothCaptureHelperWindow] Failed to read USBPcap packets: " + ex.Message, "ReadAvailableFilePacketsAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\BluetoothCaptureHelperWindow.xaml.cs", 1177);
				AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.PacketReadFailed.Template", "Failed to read USBPcap packets: {0}", ex.Message));
				return 0;
			}
			finally
			{
				Interlocked.Exchange(ref _fileReadInProgress, 0);
			}
		}

		private void RecordCaptureActivity(int packetCount, long fileDelta)
		{
			_captureActivityCount += Math.Max(packetCount, 1);
			_lastCaptureActivityAt = System.DateTimeOffset.Now;
			LiveDataStateText.Text = ((packetCount > 0) ? L("BluetoothCaptureHelperWindow.LiveState.Active", "Status: Receiving USBPcap packets") : L("BluetoothCaptureHelperWindow.LiveState.WaitingPacket", "Status: File is growing; waiting for complete packets..."));
			LiveDataCounterText.Text = LF("BluetoothCaptureHelperWindow.LiveCount.Template", "Activity count: {0}", _captureActivityCount);
			LiveDataLastText.Text = LF("BluetoothCaptureHelperWindow.LiveLast.Template", "Last activity: {0:HH:mm:ss}", _lastCaptureActivityAt.Value.LocalDateTime);
			AppendLiveEvent(LF("BluetoothCaptureHelperWindow.LiveEvent.PacketDelta.Template", "{0:HH:mm:ss} received {1} packet(s), file delta {2} bytes", DateTime.Now, packetCount, fileDelta));
		}

		private void AppendLiveEvent(string message)
		{
			if (!string.IsNullOrWhiteSpace(message))
			{
				_liveEvents.Add(message);
				while (_liveEvents.Count > 200)
				{
					_liveEvents.RemoveAt(0);
				}
			}
		}

		private void SetBusyState(bool isBusy, string? statusText = null)
		{
			_isBusy = isBusy;
			RefreshEnvironmentButton.IsEnabled = !isBusy && !_isCapturing;
			ManualSelectUsbPcapButton.IsEnabled = !isBusy && !_isCapturing;
			RefreshInterfacesButton.IsEnabled = !isBusy && !_isCapturing && _environmentReady;
			UpdateInterfaceSelectorEnabledState();
			UpdateCaptureButtonState();
			if (!string.IsNullOrWhiteSpace(statusText))
			{
				CaptureStatusText.Text = statusText;
			}
		}

		private void UpdateInterfaceSelectorEnabledState()
		{
			UsbPcapInterfaceComboBox.IsEnabled = !_isBusy && !_isCapturing && _environmentReady && _usbPcapInterfaces.Count > 0;
		}

		private string GetCaptureButtonText(bool isCapturing)
		{
			if (!isCapturing)
			{
				return L("BluetoothCaptureHelperWindow.CaptureButton.Start", "Start capture");
			}
			return L("BluetoothCaptureHelperWindow.CaptureButton.Stop", "Stop capture and open output folder");
		}

		private void SetCaptureButtonText(string text)
		{
			if (CaptureToggleButtonText != null)
			{
				CaptureToggleButtonText.Text = text;
				CaptureToggleButtonText.UpdateLayout();
			}
			else if (CaptureToggleButton != null)
			{
				CaptureToggleButton.Content = text;
			}
			CaptureToggleButton?.UpdateLayout();
		}

		private void UpdateCaptureButtonState()
		{
			if (base.DispatcherQueue != null && !base.DispatcherQueue.HasThreadAccess)
			{
				base.DispatcherQueue.TryEnqueue(UpdateCaptureButtonState);
			}
			else if (CaptureToggleButton != null)
			{
				string captureButtonText = GetCaptureButtonText(_isCapturing);
				CaptureToggleButton.IsEnabled = (_isCapturing ? (!_isBusy) : (!_isBusy && _environmentReady && GetSelectedInterface() != null));
				SetCaptureButtonText(captureButtonText);
			}
		}

		private string BuildEnvironmentStatusText()
		{
			string text = L("BluetoothCaptureHelperWindow.Environment.Found", "Found");
			string text2 = L("BluetoothCaptureHelperWindow.Environment.Missing", "Missing");
			return string.Join(Environment.NewLine, "USBPcap: " + (_environmentReady ? text : text2), "USBPcapCmd path: " + (_resolvedUsbPcapPath ?? "-"), L("BluetoothCaptureHelperWindow.Environment.AdminNote", "Capture starts with administrator permission (UAC)."), _environmentReady ? L("BluetoothCaptureHelperWindow.Environment.Ready", "Environment summary: Ready to start USBPcap capture") : L("BluetoothCaptureHelperWindow.Environment.NotReady", "Environment summary: Not ready. Install USBPcap first."));
		}

		private bool TryResolveUsbPcapPath(out string? resolvedPath)
		{
			string usbPcapCmdPath = B.I.UsbPcapCmdPath;
			if (IsUsbPcapCmdPath(usbPcapCmdPath))
			{
				resolvedPath = usbPcapCmdPath;
				return true;
			}
			if (File.Exists("C:\\Program Files\\USBPcap\\USBPcapCmd.exe"))
			{
				resolvedPath = "C:\\Program Files\\USBPcap\\USBPcapCmd.exe";
				return true;
			}
			resolvedPath = FindExecutableInPath("USBPcapCmd.exe");
			return !string.IsNullOrWhiteSpace(resolvedPath);
		}

		private static bool IsUsbPcapCmdPath(string? path)
		{
			if (!string.IsNullOrWhiteSpace(path) && string.Equals(System.IO.Path.GetFileName(path), "USBPcapCmd.exe", StringComparison.OrdinalIgnoreCase))
			{
				return File.Exists(path);
			}
			return false;
		}

		private static string? FindExecutableInPath(string executableName)
		{
			string environmentVariable = Environment.GetEnvironmentVariable("PATH");
			if (string.IsNullOrWhiteSpace(environmentVariable))
			{
				return null;
			}
			string[] array = environmentVariable.Split(System.IO.Path.PathSeparator);
			foreach (string text in array)
			{
				if (string.IsNullOrWhiteSpace(text))
				{
					continue;
				}
				try
				{
					string text2 = System.IO.Path.Combine(text.Trim(), executableName);
					if (File.Exists(text2))
					{
						return text2;
					}
				}
				catch
				{
				}
			}
			return null;
		}

