		private static string? GetPresentableCommandMessage(string? message)
		{
			if (string.IsNullOrWhiteSpace(message))
			{
				return null;
			}
			string text = string.Join(Environment.NewLine, from line in b.p.A(message).Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n')
				select line.Trim() into line
				where !string.IsNullOrWhiteSpace(line)
				select line);
			if (string.IsNullOrWhiteSpace(text))
			{
				return null;
			}
			if (!F.g.B())
			{
				if (!text.All((char ch) => ch == '\r' || ch == '\n' || ch == '\t' || (ch >= ' ' && ch <= '~')))
				{
					return null;
				}
				return text;
			}
			if (!b.p.a(text))
			{
				return text;
			}
			return null;
		}

		private async Task<string> ExecuteReadProcessAsync(string fileName, string arguments)
		{
			ProcessStartInfo startInfo = new ProcessStartInfo
			{
				FileName = fileName,
				Arguments = arguments,
				UseShellExecute = false,
				RedirectStandardOutput = true,
				RedirectStandardError = true,
				CreateNoWindow = true
			};
			using Process process = Process.Start(startInfo) ?? throw new InvalidOperationException("Unable to start " + System.IO.Path.GetFileName(fileName) + ".");
			Task<string> outputTask = process.StandardOutput.ReadToEndAsync();
			Task<string> errorTask = process.StandardError.ReadToEndAsync();
			Task waitForExitTask = process.WaitForExitAsync();
			if (await Task.WhenAny(waitForExitTask, Task.Delay(System.TimeSpan.FromSeconds(10.0))) != waitForExitTask)
			{
				try
				{
					process.Kill(entireProcessTree: true);
				}
				catch
				{
				}
				throw new TimeoutException(System.IO.Path.GetFileName(fileName) + " timed out.");
			}
			string output = await outputTask;
			string text = await errorTask;
			if (process.ExitCode != 0)
			{
				throw new InvalidOperationException(string.IsNullOrWhiteSpace(text) ? output : text);
			}
			return string.IsNullOrWhiteSpace(output) ? text : output;
		}

