				if (input.Kind == DeviceControlInputKind.Number)
				{
					if (double.IsNaN(NumericValue) || double.IsInfinity(NumericValue))
					{
						error = string.Format(L("请输入{0}。"), L(input.Label));
						return false;
					}
					double num = Math.Round(NumericValue);
					if (Math.Abs(NumericValue - num) > 0.001)
					{
						error = string.Format(L("{0}必须是整数。"), L(input.Label));
						return false;
					}
					value = (int)num;
					return true;
				}
				if (input.Kind == DeviceControlInputKind.Option)
				{
					if (SelectedOption == null)
					{
						error = string.Format(L("请选择{0}。"), L(input.Label));
						return false;
					}
					value = SelectedOption.Value;
					return true;
				}
				return true;
			}

