				int num = state.DetailText.IndexOf(" 的“", StringComparison.Ordinal);
				if (num > 0 && state.DetailText.EndsWith("”命令暂未接入。", StringComparison.Ordinal))
				{
					string text2 = state.DetailText.Substring(0, num);
					if (string.Equals(text2, "该型号", StringComparison.Ordinal))
					{
						text2 = L("该型号");
					}
					return text2 + "'s \"" + L(state.Definition.Name) + "\" command is not connected yet.";
				}
				return text;
			}
