		public void UpdateDevice(DeviceModel device)
		{
			bool flag = string.Equals(_device.DeviceId, device.DeviceId, StringComparison.OrdinalIgnoreCase);
			_device = device;
			if (_controlWindowClosed)
			{
				return;
			}
			if (flag && _featureItems.Any((DeviceControlFeatureItem item) => item.IsAcerControl))
			{
				DeviceModelRecognitionResult recognition = _controlService.A(device).Recognition;
				if (!recognition.ManualSelectionVidPidMismatch && recognition.SelectedEntry?.ModelId == _snapshot?.Recognition.SelectedEntry?.ModelId)
				{
					return;
				}
			}
			RefreshSnapshot();
		}

		private void RefreshSnapshot()
		{
			if (_controlWindowClosed || _eqOperationRunning)
			{
				return;
			}
			_acerLifetime?.Cancel();
			_acerLifetime?.Dispose();
			_acerLifetime = null;
			_acerOperationRunning = false;
			_snapshot = _controlService.A(_device);
			base.Title = L("设备控制") + " - " + _device.DisplayName;
			DeviceNameTextBlock.Text = _device.DisplayName;
			DeviceTypeTextBlock.Text = GetDeviceTypeText(_snapshot.DeviceType);
			DeviceSourceTextBlock.Text = $"{L("来源：")}{_device.Source}";
			FeatureSectionTitleTextBlock.Text = string.Format(L("{0}控制"), GetDeviceTypeText(_snapshot.DeviceType));
			ApplyRecognition(_snapshot.Recognition);
			_featureItems.Clear();
			foreach (DeviceControlFeatureState feature in _snapshot.Features)
			{
				DeviceControlFeatureItem deviceControlFeatureItem = new DeviceControlFeatureItem(feature);
				deviceControlFeatureItem.IsAudezeEq = _device.Source == DeviceSource.Audeze && feature.Definition.FeatureId == DeviceControlFeatureId.HeadsetEqPreset && feature.Status == DeviceControlSupportStatus.Supported;
				if (deviceControlFeatureItem.IsAudezeEq)
				{
					deviceControlFeatureItem.SelectedOption = null;
				}
				int isAcerControl;
				if (_device.Source == DeviceSource.Acer && !_snapshot.Recognition.ManualSelectionVidPidMismatch)
				{
					DeviceModelCatalogEntry selectedEntry = _snapshot.Recognition.SelectedEntry;
					if (selectedEntry != null)
					{
						ushort? vendorId = selectedEntry.VendorId;
						if (vendorId.HasValue && vendorId == 43174)
						{
							ushort? productId = selectedEntry.ProductId;
							if (productId.HasValue && productId == 13139)
							{
								isAcerControl = ((feature.Status == DeviceControlSupportStatus.Supported) ? 1 : 0);
								goto IL_021f;
							}
						}
					}
				}
				isAcerControl = 0;
				goto IL_021f;
				IL_021f:
				deviceControlFeatureItem.IsAcerControl = (byte)isAcerControl != 0;
				if (deviceControlFeatureItem.IsAcerControl)
				{
					deviceControlFeatureItem.SelectedOption = null;
				}
				_featureItems.Add(deviceControlFeatureItem);
			}
			DeviceControlFeatureItem deviceControlFeatureItem2 = _featureItems.FirstOrDefault((DeviceControlFeatureItem item) => item.IsAudezeEq);
			if (deviceControlFeatureItem2 != null)
			{
				RunEqOperationAsync(deviceControlFeatureItem2, switching: false);
			}
			if (_featureItems.Any((DeviceControlFeatureItem item) => item.IsAcerControl))
			{
				_acerLifetime = new CancellationTokenSource();
				RunAcerOperationAsync(null, writing: false);
			}
			ApplyLocalizedStaticTexts();
			ConfigureCobraControlVisibility(IsRazerCobraHyperSpeed(_snapshot.Recognition.SelectedEntry));
			ConfigureViperV4ProControlVisibility(IsRazerViperV4Pro(_snapshot.Recognition.SelectedEntry));
			_themeHelper.a();
		}

		private void ApplyRecognition(DeviceModelRecognitionResult recognition)
		{
			DeviceModelCatalogEntry selectedEntry = recognition.SelectedEntry;
			ModelNameTextBlock.Text = selectedEntry?.DisplayName ?? L("未绑定设备型号");
			ModelMetaTextBlock.Text = ((selectedEntry == null) ? L("写入命令需要唯一型号绑定；当前仅展示该设备类型的可扩展控制项。") : (FormatVidPidDisplay(selectedEntry) + " · Profile: " + selectedEntry.ControlProfileId));
			RecognitionStatusTextBlock.Text = L(recognition.StatusText);
			RecognitionDetailTextBlock.Text = L(recognition.DetailText);
			bool isOpen = recognition.Status == DeviceModelRecognitionStatus.Ambiguous || recognition.Status == DeviceModelRecognitionStatus.Unknown || recognition.ManualSelectionVidPidMismatch;
			RecognitionInfoBar.IsOpen = isOpen;
			RecognitionInfoBar.Title = L(recognition.StatusText);
			RecognitionInfoBar.Message = (recognition.ManualSelectionVidPidMismatch ? L("手动选择型号与当前设备 VID/PID 证据不一致。首版不会执行真实写入，后续真实写入前会要求二次确认。") : L(recognition.DetailText));
		}

