		private void ConfigureCobraControlVisibility(bool isCobra)
		{
			CobraControlPanel.Visibility = ((!isCobra) ? Visibility.Collapsed : Visibility.Visible);
			FeatureItemsControl.Visibility = (isCobra ? Visibility.Collapsed : Visibility.Visible);
			NoFeatureTextBlock.Visibility = ((isCobra || _featureItems.Count != 0) ? Visibility.Collapsed : Visibility.Visible);
			if (!isCobra)
			{
				_cobraLoadCts?.Cancel();
				SetCobraStatus(string.Empty);
				SetCobraKeepAliveStatus(string.Empty);
				SetCobraDpiHotkeyStatus(string.Empty);
			}
			else
			{
				FeatureSectionTitleTextBlock.Text = L("Razer Cobra HyperSpeed 控制");
				LoadCobraProfilesAndStateAsync();
			}
		}

		private void ConfigureViperV4ProControlVisibility(bool isViper)
		{
			ViperV4ProControlPanel.Visibility = ((!isViper) ? Visibility.Collapsed : Visibility.Visible);
			if (isViper)
			{
				FeatureItemsControl.Visibility = Visibility.Collapsed;
				NoFeatureTextBlock.Visibility = Visibility.Collapsed;
				FeatureSectionTitleTextBlock.Text = L("Razer Viper V4 Pro 控制");
				LoadViperV4ProProfileAsync();
			}
		}

