			};
			stackPanel.Children.Add(_viperStatusTextBlock);
			ViperV4ProControlPanel.Child = stackPanel;
		}

		private async Task LoadViperV4ProProfileAsync()
		{
			_ = 1;
			try
			{
				string key = ResolveDeviceKey(_device);
				Z<D.e, D.E> set = await _profileStore.A<D.e, D.E>(key, "razer-viper-v4-pro").ConfigureAwait(continueOnCapturedContext: true);
				EnsureViperProfileSet(set);
				_viperProfileSet = set;
				_viperProfile = set.Profiles.First((D.e x) => x.Id == set.SelectedProfileId);
				RefreshViperProfileComboBox();
				ApplyViperProfileToUi(_viperProfile);
				await _profileStore.A(key, "razer-viper-v4-pro", set).ConfigureAwait(continueOnCapturedContext: true);
				SetViperStatus(L("已加载本地配置。"));
			}
			catch (System.Exception ex)
			{
				SetViperStatus(L("加载 Viper V4 Pro 配置失败：") + ex.Message);
			}
		}

		private void ApplyViperProfileToUi(D.e profile)
		{
			SelectOptionByValue(_viperCurrentStageComboBox, profile.DpiConfig.CurrentStage);
			for (int i = 0; i < 5; i++)
			{
				_viperDpiXBoxes[i].Value = profile.DpiConfig.Stages[i].X;
				_viperDpiYBoxes[i].Value = profile.DpiConfig.Stages[i].Y;
			}
			SelectOptionByValue(_viperPollingComboBox, profile.PollingRate);
			_viperSleepMinutesBox.Value = profile.SleepMinutes;
			_viperLowPowerBox.Value = profile.LowPowerThresholdPercent;
		}

		private bool TryReadViperProfileFromUi(out D.e profile, out string error)
		{
			profile = _viperProfile.A();
			error = string.Empty;
			int selectedOptionValue = GetSelectedOptionValue(_viperCurrentStageComboBox, 3);
			List<global::D.D> list = new List<global::D.D>();
			for (int i = 0; i < 5; i++)
			{
				if (!TryReadWholeNumber(_viperDpiXBoxes[i], $"DPI {i + 1} X", 100, 50000, out var value, out error) || !TryReadWholeNumber(_viperDpiYBoxes[i], $"DPI {i + 1} Y", 100, 50000, out var value2, out error))
				{
					return false;
				}
				list.Add(new global::D.D
				{
					X = value,
					Y = value2
				});
			}
			if (!TryReadWholeNumber(_viperSleepMinutesBox, L("休眠时间"), 1, 15, out var value3, out error) || !TryReadWholeNumber(_viperLowPowerBox, L("低能耗阈值"), 1, 100, out var value4, out error))
			{
				return false;
			}
			profile.DpiConfig = new D.d
			{
				CurrentStage = selectedOptionValue,
				Stages = list
			};
			profile.PollingRate = GetSelectedOptionValue(_viperPollingComboBox, D.c.B);
			profile.SleepMinutes = value3;
			profile.LowPowerThresholdPercent = value4;
			return true;
		}

		private async void ViperSaveButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (!TryReadViperProfileFromUi(out D.e profile, out string error))
			{
				SetViperStatus(error);
				return;
			}
			await SaveViperProfileAsync(profile).ConfigureAwait(continueOnCapturedContext: true);
			SetViperStatus(L("已保存本地配置。"));
		}

		private async void ViperApplyButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_snapshot?.Recognition.ManualSelectionVidPidMismatch ?? false)
			{
				SetViperStatus(L("型号与 VID/PID 不一致，已阻止写入。"));
				return;
			}
			if (!TryReadViperProfileFromUi(out D.e profile, out string error))
			{
				SetViperStatus(error);
				return;
			}
			try
			{
				SetViperStatus(L("正在写入 DPI、回报率、休眠和低能耗设置..."));
				await _viperCommandService.A((D.b client, CancellationToken token) => client.A(profile, token)).ConfigureAwait(continueOnCapturedContext: true);
				await SaveViperProfileAsync(profile).ConfigureAwait(continueOnCapturedContext: true);
				SetViperStatus(L("已应用到 Razer Viper V4 Pro。"));
			}
			catch (System.Exception ex)
			{
				SetViperStatus(L("写入失败：") + ex.Message);
			}
		}

		private async Task SaveViperProfileAsync(D.e profile)
		{
			_viperProfile = profile;
			if (_viperProfileSet == null)
			{
				_viperProfileSet = new Z<D.e, D.E>();
			}
			EnsureViperProfileSet(_viperProfileSet);
			int num = _viperProfileSet.Profiles.FindIndex((D.e x) => x.Id == profile.Id);
			if (num >= 0)
			{
				_viperProfileSet.Profiles[num] = profile;
			}
			else
			{
				_viperProfileSet.Profiles.Add(profile);
			}
			_viperProfileSet.SelectedProfileId = profile.Id;
			_viperProfileSet.LastKnownState = new D.E
			{
				DpiConfig = profile.DpiConfig.A(),
				PollingRate = profile.PollingRate,
				SleepMinutes = profile.SleepMinutes,
				LowPowerThresholdPercent = profile.LowPowerThresholdPercent
			};
			await _profileStore.A(ResolveDeviceKey(_device), "razer-viper-v4-pro", _viperProfileSet).ConfigureAwait(continueOnCapturedContext: true);
			RefreshViperProfileComboBox();
		}

		private static void EnsureViperProfileSet(Z<D.e, D.E> set)
		{
			Z<D.e, D.E> z = set;
			if (z.Profiles == null)
			{
				List<D.e> list = (z.Profiles = new List<D.e>());
			}
			if (set.Profiles.Count == 0)
			{
				set.Profiles.Add(new D.e());
			}
			foreach (D.e profile in set.Profiles)
			{
				if (string.IsNullOrWhiteSpace(profile.Id))
				{
					profile.Id = Guid.NewGuid().ToString("N");
				}
				if (string.IsNullOrWhiteSpace(profile.Name))
				{
					profile.Name = "Profile";
				}
			}
			if (!set.Profiles.Any((D.e p) => p.Id == set.SelectedProfileId))
			{
				set.SelectedProfileId = set.Profiles[0].Id;
			}
		}

		private void RefreshViperProfileComboBox()
		{
			if (!(_viperProfileComboBox == null) && _viperProfileSet != null)
			{
				List<ProfileOption> list = _viperProfileSet.Profiles.Select((D.e p) => new ProfileOption(p.Name, p.Id)).ToList();
				_viperProfileComboBox.ItemsSource = list;
				_viperProfileComboBox.SelectedItem = list.FirstOrDefault((ProfileOption p) => p.ProfileId == _viperProfileSet.SelectedProfileId);
			}
		}

		private void ViperProfileComboBox_SelectionChanged(object sender, Microsoft.UI.Xaml.Controls.SelectionChangedEventArgs e)
		{
			if (_viperProfileSet == null)
			{
				return;
			}
			object obj = _viperProfileComboBox?.SelectedItem;
			ProfileOption option = obj as ProfileOption;
			if (option != null)
			{
				_viperProfileSet.SelectedProfileId = option.ProfileId;
				_viperProfile = _viperProfileSet.Profiles.First((D.e p) => p.Id == option.ProfileId);
				ApplyViperProfileToUi(_viperProfile);
			}
		}

		private async void ViperNewProfileButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_viperProfileSet != null)
			{
				string text = await ShowCobraProfileNameDialogAsync("新建配置", $"Profile {_viperProfileSet.Profiles.Count + 1}").ConfigureAwait(continueOnCapturedContext: true);
				if (text != null)
				{
					D.e e2 = _viperProfile.A();
					e2.Id = Guid.NewGuid().ToString("N");
					e2.Name = text;
					_viperProfileSet.Profiles.Add(e2);
					_viperProfileSet.SelectedProfileId = e2.Id;
					_viperProfile = e2;
					RefreshViperProfileComboBox();
					ApplyViperProfileToUi(e2);
				}
			}
		}

		private async void ViperRenameProfileButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_viperProfileSet != null)
			{
				string text = await ShowCobraProfileNameDialogAsync("重命名配置", _viperProfile.Name).ConfigureAwait(continueOnCapturedContext: true);
				if (text != null)
				{
					_viperProfile.Name = text;
					await SaveViperProfileAsync(_viperProfile).ConfigureAwait(continueOnCapturedContext: true);
				}
			}
		}

		private async void ViperDeleteProfileButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_viperProfileSet == null || _viperProfileSet.Profiles.Count <= 1)
			{
				SetViperStatus(L("至少需要保留一个本地配置。"));
				return;
			}
			_viperProfileSet.Profiles.RemoveAll((D.e p) => p.Id == _viperProfile.Id);
			_viperProfile = _viperProfileSet.Profiles[0];
			_viperProfileSet.SelectedProfileId = _viperProfile.Id;
			await SaveViperProfileAsync(_viperProfile).ConfigureAwait(continueOnCapturedContext: true);
			ApplyViperProfileToUi(_viperProfile);
		}

		private void SetViperStatus(string text)
		{
			if (_viperStatusTextBlock != null)
			{
				_viperStatusTextBlock.Text = text;
			}
		}

		private B.W GetCurrentViperDpiHotkeyBinding()
		{
			return B.v.A(ResolveDeviceKey(_device), "razer-viper-v4-pro.dpi-next", _device.DisplayName, "Ctrl+Alt+V");
		}

		private void ViperDpiHotkeySwitch_Toggled(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (!(_viperDpiHotkeySwitch == null))
			{
				B.W currentViperDpiHotkeyBinding = GetCurrentViperDpiHotkeyBinding();
				currentViperDpiHotkeyBinding.Enabled = _viperDpiHotkeySwitch.IsOn;
				currentViperDpiHotkeyBinding.Hotkey = "Ctrl+Alt+V";
				B.v.A(currentViperDpiHotkeyBinding, "Ctrl+Alt+V");
				_deviceControlHotkeyService.A();
				SetViperStatus(_deviceControlHotkeyService.StatusText);
			}
		}

		private void CobraKeepAliveService_StatusChanged(object? sender, EventArgs e)
		{
			string statusText = _cobraKeepAliveService.StatusText;
			if (base.DispatcherQueue == null)
			{
				SetCobraKeepAliveStatus(statusText);
				return;
			}
			base.DispatcherQueue.TryEnqueue(delegate
			{
				SetCobraKeepAliveStatus(statusText);
			});
		}

		private void DeviceControlHotkeyService_StatusChanged(object? sender, EventArgs e)
		{
			string statusText = _deviceControlHotkeyService.StatusText;
			if (base.DispatcherQueue == null)
			{
				SetCobraDpiHotkeyStatus(statusText);
				return;
			}
			base.DispatcherQueue.TryEnqueue(delegate
			{
				SetCobraDpiHotkeyStatus(statusText);
			});
		}

		private void DeviceControlHotkeyService_ActionExecuted(object? sender, B.x e)
		{
			if (string.Equals(e.ActionKey, "razer-viper-v4-pro.dpi-next", StringComparison.OrdinalIgnoreCase))
			{
				base.DispatcherQueue.TryEnqueue(delegate
				{
					if (e.CurrentStage.HasValue)
					{
						_viperProfile.DpiConfig.CurrentStage = e.CurrentStage.Value;
						SelectOptionByValue(_viperCurrentStageComboBox, e.CurrentStage.Value);
					}
					SetViperStatus(e.DisplayText);
				});
			}
			else
			{
				if (!string.Equals(e.ActionKey, "razer-cobra.dpi-next", StringComparison.OrdinalIgnoreCase))
				{
					return;
				}
				if (base.DispatcherQueue == null)
				{
					ApplyCobraDpiHotkeySwitchToUi(e);
					return;
				}
				base.DispatcherQueue.TryEnqueue(delegate
				{
					ApplyCobraDpiHotkeySwitchToUi(e);
				});
			}
		}

		private static bool IsRazerCobraHyperSpeed(DeviceModelCatalogEntry? entry)
		{
			if (entry != null && string.Equals(entry.ControlProfileId, "razer-cobra-hyperspeed", StringComparison.OrdinalIgnoreCase) && entry.VendorId == 5426)
			{
				return entry.ProductId == 219;
			}
			return false;
		}

		private static bool IsRazerViperV4Pro(DeviceModelCatalogEntry? entry)
		{
			if (entry != null && string.Equals(entry.ControlProfileId, "razer-viper-v4-pro", StringComparison.OrdinalIgnoreCase) && entry.VendorId == 5426)
			{
				if (entry.ProductId != 230)
				{
					return entry.ProductId == 229;
				}
				return true;
			}
			return false;
		}

