		private void DeviceControlNumberBox_Loaded(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			Microsoft.UI.Xaml.Controls.NumberBox numberBox = sender as Microsoft.UI.Xaml.Controls.NumberBox;
			if ((object)numberBox != null)
			{
				HideNumberBoxClearButton(numberBox);
				numberBox.DispatcherQueue.TryEnqueue(delegate
				{
					HideNumberBoxClearButton(numberBox);
				});
			}
		}

		private static void HideNumberBoxClearButton(Microsoft.UI.Xaml.Controls.NumberBox numberBox)
		{
			numberBox.ApplyTemplate();
			FindDescendantByName<Microsoft.UI.Xaml.Controls.TextBox>(numberBox, "InputBox")?.ApplyTemplate();
			Microsoft.UI.Xaml.Controls.Button button = FindDescendantByName<Microsoft.UI.Xaml.Controls.Button>(numberBox, "DeleteButton");
			if ((object)button != null)
			{
				button.Width = 0.0;
				button.MinWidth = 0.0;
				button.Padding = new Microsoft.UI.Xaml.Thickness(0.0);
				button.Opacity = 0.0;
				button.IsHitTestVisible = false;
				button.IsTabStop = false;
			}
		}

		private static T? FindDescendantByName<T>(Microsoft.UI.Xaml.DependencyObject source, string name) where T : Microsoft.UI.Xaml.FrameworkElement
		{
			int childrenCount = VisualTreeHelper.GetChildrenCount(source);
			for (int i = 0; i < childrenCount; i++)
			{
				Microsoft.UI.Xaml.DependencyObject child = VisualTreeHelper.GetChild(source, i);
				if (child is T val && string.Equals(val.Name, name, StringComparison.Ordinal))
				{
					return val;
				}
				T val2 = FindDescendantByName<T>(child, name);
				if ((object)val2 != null)
				{
					return val2;
				}
			}
			return null;
		}

