		private async Task LoadCobraProfilesAndStateAsync()
		{
			_cobraLoadCts?.Cancel();
			_cobraLoadCts?.Dispose();
			_cobraLoadCts = new CancellationTokenSource();
			CancellationToken cancellationToken = _cobraLoadCts.Token;
			try
			{
				SetCobraBusy(busy: true);
				SetCobraStatus(L("正在加载本地配置..."));
				string text = (B.I.RazerCobraLastControlDeviceKey = ResolveDeviceKey(_device));
				Z<D.O, D.n> z = await _profileStore.A<D.O, D.n>(text, "razer-cobra-hyperspeed", cancellationToken).ConfigureAwait(continueOnCapturedContext: true);
				EnsureCobraProfileSet(z);
				_cobraProfileSet = z;
				_cobraSelectedProfile = ResolveSelectedCobraProfile(z);
				RefreshCobraProfileComboBox();
				ApplyCobraProfileToUi(_cobraSelectedProfile);
				await SaveCobraProfileSetAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: true);
				_cobraKeepAliveService.A(_cobraSelectedProfile);
				SetCobraKeepAliveStatus(_cobraKeepAliveService.StatusText);
				SyncCobraDpiHotkeyUiFromSettings();
				SetCobraDpiHotkeyStatus(_deviceControlHotkeyService.StatusText);
				SetCobraStatus(L("已加载本地配置。"));
			}
			catch (OperationCanceledException)
			{
			}
			catch (System.Exception ex2)
			{
				SetCobraStatus(L("加载 Cobra 控制状态失败：") + ex2.Message);
				Logger.a("[Razer Cobra][UI] Load failed: " + ex2.Message, "LoadCobraProfilesAndStateAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\DeviceControlWindow.xaml.cs", 868);
			}
			finally
			{
				SetCobraBusy(busy: false);
			}
		}

		private void EnsureCobraProfileSet(Z<D.O, D.n> profileSet)
		{
			Z<D.O, D.n> z = profileSet;
			if (z.Profiles == null)
			{
				List<D.O> list = (z.Profiles = new List<D.O>());
			}
			if (profileSet.Profiles.Count == 0)
			{
				profileSet.Profiles.Add(D.O.A());
			}
			if (string.IsNullOrWhiteSpace(profileSet.SelectedProfileId) || !profileSet.Profiles.Any((D.O p) => string.Equals(p.Id, profileSet.SelectedProfileId, StringComparison.OrdinalIgnoreCase)))
			{
				profileSet.SelectedProfileId = profileSet.Profiles[0].Id;
			}
			foreach (D.O profile in profileSet.Profiles)
			{
				if (string.IsNullOrWhiteSpace(profile.Id))
				{
					profile.Id = Guid.NewGuid().ToString("N");
				}
				if (string.IsNullOrWhiteSpace(profile.Name))
				{
					profile.Name = "Profile";
				}
				profile.DpiConfig = NormalizeCobraDpiConfig(profile.DpiConfig);
			}
		}

		private static D.M CreateDefaultCobraDpiConfig()
		{
			return new D.M
			{
				Mode = 1,
				CurrentStage = 1,
				Stages = CobraDefaultDpiStages.Select((int dpi) => new D.l
				{
					X = dpi,
					Y = dpi
				}).ToList()
			};
		}

		private static D.M NormalizeCobraDpiConfig(D.M? source)
		{
			D.M m = CreateDefaultCobraDpiConfig();
			if (source?.Stages == null || source.Stages.Count == 0)
			{
				return m;
			}
			int num = Math.Clamp(source.Stages.Count, 1, 6);
			List<D.l> list = new List<D.l>(num);
			for (int i = 0; i < num; i++)
			{
				D.l l = ((i < source.Stages.Count) ? source.Stages[i] : null);
				int index = Math.Min(i, m.Stages.Count - 1);
				list.Add(l?.A() ?? m.Stages[index].A());
			}
			return new D.M
			{
				Mode = (byte)((source.Mode == 0) ? 1 : source.Mode),
				CurrentStage = Math.Clamp(source.CurrentStage, 1, num),
				Stages = list
			};
		}

		private static D.O ResolveSelectedCobraProfile(Z<D.O, D.n> profileSet)
		{
			return profileSet.Profiles.FirstOrDefault((D.O profile) => string.Equals(profile.Id, profileSet.SelectedProfileId, StringComparison.OrdinalIgnoreCase)) ?? profileSet.Profiles[0];
		}

		private void RefreshCobraProfileComboBox()
		{
			if (_cobraProfileComboBox == null || _cobraProfileSet == null)
			{
				return;
			}
			_cobraUpdating = true;
			try
			{
				List<ProfileOption> list = _cobraProfileSet.Profiles.Select((D.O profile) => new ProfileOption(profile.Name, profile.Id)).ToList();
				_cobraProfileComboBox.ItemsSource = list;
				_cobraProfileComboBox.SelectedItem = list.FirstOrDefault((ProfileOption option) => string.Equals(option.ProfileId, _cobraProfileSet.SelectedProfileId, StringComparison.OrdinalIgnoreCase));
			}
			finally
			{
				_cobraUpdating = false;
			}
		}

		private void ApplyCobraProfileToUi(D.O? profile)
		{
			if (profile == null)
			{
				return;
			}
			_cobraUpdating = true;
			try
			{
				profile.DpiConfig = NormalizeCobraDpiConfig(profile.DpiConfig);
				int num = Math.Clamp(profile.DpiConfig.Stages.Count, 1, 6);
				int num2 = Math.Clamp(profile.DpiConfig.CurrentStage, 1, num);
				UpdateCobraDpiRows(num, num2);
				SelectOptionByValue(_cobraCurrentStageComboBox, num2);
				for (int i = 0; i < 6; i++)
				{
					D.l l;
					if (i >= profile.DpiConfig.Stages.Count)
					{
						List<D.l> stages = profile.DpiConfig.Stages;
						l = stages[stages.Count - 1];
					}
					else
					{
						l = profile.DpiConfig.Stages[i];
					}
					D.l l2 = l;
					_cobraDpiXBoxes[i].Value = l2.X;
					_cobraDpiYBoxes[i].Value = l2.Y;
				}
				SelectOptionByValue(_cobraPollingRateComboBox, profile.PollingRate);
				if (_cobraSleepSecondsNumberBox != null)
				{
					_cobraSleepSecondsNumberBox.Value = profile.SleepSeconds;
				}
				if (_cobraLightingPowerSwitch != null)
				{
					_cobraLightingPowerSwitch.IsOn = profile.LightingEnabled;
				}
				if (_cobraBrightnessSlider != null)
				{
					_cobraBrightnessSlider.Value = Math.Clamp(profile.BrightnessPercent, 0, 100);
					UpdateCobraBrightnessValueText(_cobraBrightnessSlider.Value);
				}
				if (_cobraKeepAliveSwitch != null)
				{
					_cobraKeepAliveSwitch.IsOn = profile.KeepStaticColorAlive;
				}
				UpdateCobraColor(profile.StaticColor);
			}
			finally
			{
				_cobraUpdating = false;
			}
		}

		private bool TryReadCobraProfileFromUi(out D.O profile, out string error)
		{
			profile = _cobraSelectedProfile?.a() ?? D.O.A();
			error = string.Empty;
			int num = Math.Clamp(_cobraActiveDpiStageCount, 1, 6);
			int selectedOptionValue = GetSelectedOptionValue(_cobraCurrentStageComboBox, 1);
			if (selectedOptionValue < 1 || selectedOptionValue > num)
			{
				error = string.Format(L("当前 DPI 档位必须在 1-{0} 范围内。"), num);
				return false;
			}
			List<D.l> list = new List<D.l>(num);
			for (int i = 0; i < num; i++)
			{
				if (!TryReadWholeNumber(_cobraDpiXBoxes[i], FormatCobraStageLabel(i + 1) + " X DPI", 1, 65535, out var value, out error) || !TryReadWholeNumber(_cobraDpiYBoxes[i], FormatCobraStageLabel(i + 1) + " Y DPI", 1, 65535, out var value2, out error))
				{
					return false;
				}
				list.Add(new D.l
				{
					X = value,
					Y = value2
				});
			}
			if (!TryReadWholeNumber(_cobraSleepSecondsNumberBox, L("休眠秒数"), 0, 65535, out var value3, out error) || !TryReadSliderWholeNumber(_cobraBrightnessSlider, L("亮度"), 0, 100, out var value4, out error))
			{
				return false;
			}
			if (!D.m.A(_cobraColorHexTextBlock?.Text, out var staticColor))
			{
				error = L("静态颜色必须是 #RRGGBB 格式。");
				return false;
			}
			profile.DpiConfig = new D.M
			{
				Mode = 1,
				CurrentStage = selectedOptionValue,
				Stages = list
			};
			profile.PollingRate = GetSelectedOptionValue(_cobraPollingRateComboBox, D.k.B);
			profile.SleepSeconds = value3;
			profile.LightingEnabled = _cobraLightingPowerSwitch?.IsOn ?? true;
			profile.BrightnessPercent = value4;
			profile.KeepStaticColorAlive = _cobraKeepAliveSwitch?.IsOn ?? true;
			profile.StaticColor = staticColor;
			profile.LightingEffect = D.L.A;
			return true;
		}

		private static bool TryReadWholeNumber(Microsoft.UI.Xaml.Controls.NumberBox? numberBox, string label, int min, int max, out int value, out string error)
		{
			value = 0;
			error = string.Empty;
			if (numberBox == null || double.IsNaN(numberBox.Value) || double.IsInfinity(numberBox.Value))
			{
				error = string.Format(L("请输入{0}。"), label);
				return false;
			}
			double num = Math.Round(numberBox.Value);
			if (Math.Abs(numberBox.Value - num) > 0.001)
			{
				error = string.Format(L("{0}必须是整数。"), label);
				return false;
			}
			value = (int)num;
			if (value < min || value > max)
			{
				error = string.Format(L("{0}必须在 {1}-{2}。"), label, min, max);
				return false;
			}
			return true;
		}

		private static bool TryReadSliderWholeNumber(Microsoft.UI.Xaml.Controls.Slider? slider, string label, int min, int max, out int value, out string error)
		{
			value = 0;
			error = string.Empty;
			if (slider == null || double.IsNaN(slider.Value) || double.IsInfinity(slider.Value))
			{
				error = string.Format(L("请输入{0}。"), label);
				return false;
			}
			value = (int)Math.Round(slider.Value);
			if (value < min || value > max)
			{
				error = string.Format(L("{0}必须在 {1}-{2}。"), label, min, max);
				return false;
			}
			return true;
		}

		private void UpdateCobraDpiRows(int stageCount, int currentStage)
		{
			_cobraActiveDpiStageCount = Math.Clamp(stageCount, 1, 6);
			currentStage = Math.Clamp(currentStage, 1, _cobraActiveDpiStageCount);
			for (int i = 0; i < _cobraDpiRows.Length; i++)
			{
				_cobraDpiRows[i].Visibility = ((i >= _cobraActiveDpiStageCount) ? Visibility.Collapsed : Visibility.Visible);
				if (i < _cobraDpiDeleteButtons.Length)
				{
					_cobraDpiDeleteButtons[i].Tag = i + 1;
				}
			}
			if (!(_cobraCurrentStageComboBox == null))
			{
				_cobraCurrentStageComboBox.ItemsSource = CreateCobraStageOptions(_cobraActiveDpiStageCount);
				SelectOptionByValue(_cobraCurrentStageComboBox, currentStage);
				RefreshCobraDpiButtonStates();
			}
		}

		private void RefreshCobraDpiButtonStates()
		{
			if (_cobraAddDpiStageButton != null)
			{
				_cobraAddDpiStageButton.IsEnabled = !_cobraBusy && _cobraActiveDpiStageCount < 6;
			}
			for (int i = 0; i < _cobraDpiDeleteButtons.Length; i++)
			{
				_cobraDpiDeleteButtons[i].IsEnabled = !_cobraBusy && _cobraActiveDpiStageCount > 1;
			}
		}

		private void CobraAddDpiStageButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_cobraActiveDpiStageCount >= 6)
			{
				SetCobraStatus(L("最多支持 6 个 DPI 档位。"));
				return;
			}
			int num = Math.Max(0, _cobraActiveDpiStageCount - 1);
			int cobraActiveDpiStageCount = _cobraActiveDpiStageCount;
			int num2 = ReadNumberBoxIntOrFallback(_cobraDpiXBoxes[num], CobraDefaultDpiStages[Math.Min(num, CobraDefaultDpiStages.Length - 1)]);
			int num3 = ReadNumberBoxIntOrFallback(_cobraDpiYBoxes[num], num2);
			_cobraDpiXBoxes[cobraActiveDpiStageCount].Value = num2;
			_cobraDpiYBoxes[cobraActiveDpiStageCount].Value = num3;
			UpdateCobraDpiRows(_cobraActiveDpiStageCount + 1, cobraActiveDpiStageCount + 1);
			SetCobraStatus(L("已添加 DPI 档位，点击保存或应用写入配置。"));
		}

		private void CobraDeleteDpiStageButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_cobraActiveDpiStageCount <= 1)
			{
				SetCobraStatus(L("至少需要保留一个 DPI 档位。"));
			}
			else if (sender is Microsoft.UI.Xaml.Controls.Button { Tag: var tag } && tag is int value)
			{
				int num = Math.Clamp(value, 1, _cobraActiveDpiStageCount) - 1;
				for (int i = num; i < _cobraActiveDpiStageCount - 1; i++)
				{
					_cobraDpiXBoxes[i].Value = _cobraDpiXBoxes[i + 1].Value;
					_cobraDpiYBoxes[i].Value = _cobraDpiYBoxes[i + 1].Value;
				}
				int num2 = GetSelectedOptionValue(_cobraCurrentStageComboBox, 1);
				if (num2 > num + 1)
				{
					num2--;
				}
				int num3 = _cobraActiveDpiStageCount - 1;
				num2 = Math.Clamp(num2, 1, num3);
				UpdateCobraDpiRows(num3, num2);
				SetCobraStatus(L("已删除 DPI 档位，点击保存或应用写入配置。"));
			}
		}

		private static int ReadNumberBoxIntOrFallback(Microsoft.UI.Xaml.Controls.NumberBox numberBox, int fallback)
		{
			if (double.IsNaN(numberBox.Value) || double.IsInfinity(numberBox.Value))
			{
				return fallback;
			}
			return Math.Clamp((int)Math.Round(numberBox.Value), 1, 65535);
		}

		private async void CobraDpiHotkeySwitch_Toggled(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (_cobraUpdating || _cobraDpiHotkeySwitch == null)
			{
				return;
			}
			B.W currentCobraDpiHotkeyBinding = GetCurrentCobraDpiHotkeyBinding();
			if (_cobraDpiHotkeySwitch.IsOn)
			{
				B.w w = FindCobraDpiHotkeyConflict(currentCobraDpiHotkeyBinding.Hotkey);
				if (w != null)
				{
					_cobraUpdating = true;
					try
					{
						_cobraDpiHotkeySwitch.IsOn = false;
					}
					finally
					{
						_cobraUpdating = false;
					}
					await ShowCobraDpiHotkeyConflictAsync(w).ConfigureAwait(continueOnCapturedContext: true);
					return;
				}
			}
			currentCobraDpiHotkeyBinding.Enabled = _cobraDpiHotkeySwitch.IsOn;
			SaveCurrentCobraDpiHotkeyBinding(currentCobraDpiHotkeyBinding);
			_deviceControlHotkeyService.A();
			SetCobraDpiHotkeyStatus(_deviceControlHotkeyService.StatusText);
		}

		private async void CobraDpiHotkeyButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			B.W binding = GetCurrentCobraDpiHotkeyBinding();
			var (selectedKey, selectedModifiers) = F.v.A(binding.Hotkey, "Ctrl+Alt+D");
			while (true)
			{
				Microsoft.UI.Xaml.Controls.StackPanel stackPanel = new Microsoft.UI.Xaml.Controls.StackPanel
				{
					Spacing = 12.0
				};
				CobraHotkeySelectorRow row = CreateCobraHotkeySelectorRow("循环下一档", selectedModifiers, selectedKey);
				stackPanel.Children.Add(row.Container);
				Microsoft.UI.Xaml.Controls.ContentDialog contentDialog = new Microsoft.UI.Xaml.Controls.ContentDialog
				{
					Title = L("设置设备控制快捷键"),
					Content = stackPanel,
					PrimaryButtonText = L("保存"),
					SecondaryButtonText = L("恢复默认"),
					CloseButtonText = L("取消"),
					DefaultButton = ContentDialogButton.Primary,
					XamlRoot = RootGrid.XamlRoot
				};
				switch (await F.V.A(contentDialog).ConfigureAwait(continueOnCapturedContext: true))
				{
				case ContentDialogResult.None:
					return;
				case ContentDialogResult.Secondary:
				{
					string hotkey = "Ctrl+Alt+D";
					if (binding.Enabled)
					{
						B.w w = FindCobraDpiHotkeyConflict(hotkey);
						if (w != null)
						{
							await ShowCobraDpiHotkeyConflictAsync(w).ConfigureAwait(continueOnCapturedContext: true);
							continue;
						}
					}
					binding.Hotkey = hotkey;
					SaveCurrentCobraDpiHotkeyBinding(binding);
					SyncCobraDpiHotkeyUiFromSettings();
					_deviceControlHotkeyService.A();
					SetCobraDpiHotkeyStatus(_deviceControlHotkeyService.StatusText);
					return;
				}
				}
				(VirtualKey, VirtualKeyModifiers) selectedCobraHotkey = GetSelectedCobraHotkey(row.ModifierComboBox, row.KeyComboBox);
				string hotkey2 = F.v.A(selectedCobraHotkey.Item1, selectedCobraHotkey.Item2);
				if (binding.Enabled)
				{
					B.w w2 = FindCobraDpiHotkeyConflict(hotkey2);
					if (w2 != null)
					{
						await ShowCobraDpiHotkeyConflictAsync(w2).ConfigureAwait(continueOnCapturedContext: true);
						continue;
					}
				}
				binding.Hotkey = hotkey2;
				SaveCurrentCobraDpiHotkeyBinding(binding);
				SyncCobraDpiHotkeyUiFromSettings();
				_deviceControlHotkeyService.A();
				SetCobraDpiHotkeyStatus(_deviceControlHotkeyService.StatusText);
				return;
			}
		}

		private B.W GetCurrentCobraDpiHotkeyBinding()
		{
			return B.v.A(ResolveDeviceKey(_device), "razer-cobra.dpi-next", _device.DisplayName, "Ctrl+Alt+D");
		}

		private void SaveCurrentCobraDpiHotkeyBinding(B.W binding)
		{
