			Microsoft.UI.Xaml.Controls.Grid grid = new Microsoft.UI.Xaml.Controls.Grid
			{
				ColumnSpacing = 8.0
			};
			grid.ColumnDefinitions.Add(new Microsoft.UI.Xaml.Controls.ColumnDefinition
			{
				Width = new Microsoft.UI.Xaml.GridLength(1.0, Microsoft.UI.Xaml.GridUnitType.Star)
			});
			grid.ColumnDefinitions.Add(new Microsoft.UI.Xaml.Controls.ColumnDefinition
			{
				Width = new Microsoft.UI.Xaml.GridLength(1.0, Microsoft.UI.Xaml.GridUnitType.Star)
			});
			Microsoft.UI.Xaml.Controls.ComboBox comboBox = new Microsoft.UI.Xaml.Controls.ComboBox
			{
				ItemsSource = F.v.ModifierOptions,
				DisplayMemberPath = "Display",
				HorizontalAlignment = HorizontalAlignment.Stretch
			};
			Microsoft.UI.Xaml.Controls.ComboBox comboBox2 = new Microsoft.UI.Xaml.Controls.ComboBox
			{
				ItemsSource = F.v.KeyOptions,
				DisplayMemberPath = "Display",
				HorizontalAlignment = HorizontalAlignment.Stretch
			};
			comboBox.SelectedItem = F.v.ModifierOptions.FirstOrDefault((F.W item) => item.Modifiers == selectedModifiers) ?? F.v.ModifierOptions[0];
			comboBox2.SelectedItem = F.v.KeyOptions.FirstOrDefault((F.w item) => item.Key == selectedKey) ?? F.v.KeyOptions[0];
			Microsoft.UI.Xaml.Controls.Grid.SetColumn(comboBox, 0);
			Microsoft.UI.Xaml.Controls.Grid.SetColumn(comboBox2, 1);
			grid.Children.Add(comboBox);
			grid.Children.Add(comboBox2);
