		private void ApplyCobraDpiHotkeySwitchToUi(B.x e)
		{
			if (!string.Equals(e.DeviceKey, ResolveDeviceKey(_device), StringComparison.OrdinalIgnoreCase) || !e.CurrentStage.HasValue)
			{
				return;
			}
			if (_cobraProfileSet != null)
			{
				D.O o = _cobraProfileSet.Profiles.FirstOrDefault((D.O item) => string.Equals(item.Id, e.ProfileId, StringComparison.OrdinalIgnoreCase));
				if (o != null)
				{
					o.DpiConfig.CurrentStage = e.CurrentStage.Value;
					Z<D.O, D.n> cobraProfileSet = _cobraProfileSet;
					if (cobraProfileSet.LastKnownState == null)
					{
						D.n n = (cobraProfileSet.LastKnownState = new D.n());
					}
					_cobraProfileSet.LastKnownState.DpiConfig = o.DpiConfig.A();
				}
			}
			if (_cobraSelectedProfile != null && string.Equals(_cobraSelectedProfile.Id, e.ProfileId, StringComparison.OrdinalIgnoreCase))
			{
				_cobraSelectedProfile.DpiConfig.CurrentStage = e.CurrentStage.Value;
				SelectOptionByValue(_cobraCurrentStageComboBox, e.CurrentStage.Value);
				SetCobraStatus(string.Format(L("已快捷切换：{0}"), e.DisplayText));
			}
		}

