			if (_cobraProfileSet.Profiles.Count <= 1)
			{
				SetCobraStatus(L("至少需要保留一个本地配置。"));
				return;
			}
			_cobraProfileSet.Profiles.RemoveAll((D.O profile) => string.Equals(profile.Id, _cobraSelectedProfile.Id, StringComparison.OrdinalIgnoreCase));
			_cobraProfileSet.SelectedProfileId = _cobraProfileSet.Profiles[0].Id;
			_cobraSelectedProfile = _cobraProfileSet.Profiles[0];
			RefreshCobraProfileComboBox();
			ApplyCobraProfileToUi(_cobraSelectedProfile);
			await SaveCobraProfileSetAsync(CancellationToken.None).ConfigureAwait(continueOnCapturedContext: true);
			SetCobraStatus(L("已删除本地配置。"));
			await ShowMessageAsync("设备控制", "已删除").ConfigureAwait(continueOnCapturedContext: true);
		}

