		private async Task<bool> SaveCurrentCobraProfileFromUiAsync(CancellationToken cancellationToken, bool showSavedDialog = false)
		{
			if (_cobraProfileSet == null)
			{
				return false;
			}
			if (!TryReadCobraProfileFromUi(out D.O profile, out string error))
			{
				SetCobraStatus(error);
				return false;
			}
			int num = _cobraProfileSet.Profiles.FindIndex((D.O existing) => string.Equals(existing.Id, profile.Id, StringComparison.OrdinalIgnoreCase));
			if (num >= 0)
			{
				_cobraProfileSet.Profiles[num] = profile;
			}
			else
			{
				_cobraProfileSet.Profiles.Add(profile);
			}
			_cobraProfileSet.SelectedProfileId = profile.Id;
			_cobraSelectedProfile = profile;
			if (profile.BrightnessPercent > 0)
			{
				_cobraProfileSet.LastNonZeroBrightnessPercent = profile.BrightnessPercent;
			}
			await SaveCobraProfileSetAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: true);
			RefreshCobraProfileComboBox();
			SetCobraStatus("已保存到本地配置。");
			if (showSavedDialog)
			{
				await ShowMessageAsync("设备控制", "已保存").ConfigureAwait(continueOnCapturedContext: true);
			}
			return true;
		}

