		private static void SelectOptionByValue<T>(Microsoft.UI.Xaml.Controls.ComboBox? comboBox, T value)
		{
			if (comboBox == null)
			{
				return;
			}
			foreach (object item in comboBox.Items)
			{
				if (item is OptionItem optionItem && optionItem.Value is T x && EqualityComparer<T>.Default.Equals(x, value))
				{
					comboBox.SelectedItem = item;
					break;
				}
			}
		}

		private static T GetSelectedOptionValue<T>(Microsoft.UI.Xaml.Controls.ComboBox? comboBox, T fallback)
		{
			if (comboBox?.SelectedItem is OptionItem optionItem)
			{
				object value = optionItem.Value;
				if (value is T)
				{
					return (T)value;
				}
			}
			return fallback;
		}

