			}
			return false;
		}

		private static bool IsUsbCaptureDevice(DeviceSource source)
		{
			if (source != DeviceSource.Unknown)
			{
				return !IsBluetoothCaptureDevice(source);
			}
			return false;
		}

		private static string LocalizeDeviceControlMessage(string value)
		{
			string text = L(value);
			if (IsChineseUi() || !string.Equals(text, value, StringComparison.Ordinal))
			{
				return text;
			}
			if (value.EndsWith(" 已发送。", StringComparison.Ordinal))
			{
				string text2 = value;
				int length = " 已发送。".Length;
				return text2.Substring(0, text2.Length - length) + " sent.";
			}
			if (value.StartsWith("写入 ", StringComparison.Ordinal) && value.Contains(" 失败：", StringComparison.Ordinal))
			{
				int num = value.IndexOf(" 失败：", StringComparison.Ordinal);
				int length = "写入 ".Length;
				string text3 = value.Substring(length, num - length);
				string text2 = value;
				length = num + " 失败：".Length;
				string text4 = text2.Substring(length, text2.Length - length);
				return "Failed to write " + text3 + ": " + text4;
			}
			if (value.StartsWith("写入 ", StringComparison.Ordinal) && value.EndsWith(" 前置响应超时，未收到 08 03。", StringComparison.Ordinal))
			{
				string text2 = value;
				int length = "写入 ".Length;
				int length2 = " 前置响应超时，未收到 08 03。".Length;
				string text5 = text2.Substring(length, text2.Length - length2 - length);
				return "Preamble timed out before writing " + text5 + "; did not receive 08 03.";
			}
			return text;
		}

