		private void ApplyRequestedThemeForCurrentSkin()
		{
			try
			{
				if (base.Content is Microsoft.UI.Xaml.FrameworkElement frameworkElement)
				{
					ElementTheme elementTheme = ThemeService.CurrentSkin switch
					{
						ThemeService.A.C => ElementTheme.Light, 
						ThemeService.A.b => ElementTheme.Dark, 
						ThemeService.A.c => ElementTheme.Light, 
						_ => ElementTheme.Default, 
					};
					if (frameworkElement.RequestedTheme == elementTheme)
					{
						frameworkElement.RequestedTheme = elementTheme switch
						{
							ElementTheme.Dark => ElementTheme.Light, 
							ElementTheme.Light => ElementTheme.Dark, 
							_ => (frameworkElement.ActualTheme == ElementTheme.Dark) ? ElementTheme.Light : ElementTheme.Dark, 
						};
						frameworkElement.UpdateLayout();
					}
					frameworkElement.RequestedTheme = elementTheme;
					frameworkElement.UpdateLayout();
				}
			}
			catch
			{
			}
		}

