		private void OnTimeRangeChecked(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			if (!(sender is Microsoft.UI.Xaml.Controls.RadioButton { Tag: var tag } radioButton))
			{
				return;
			}
			string text = tag?.ToString();
			if (Range1Hour != null)
			{
				Range1Hour.FontSize = 13.0;
			}
			if (Range6Hours != null)
			{
				Range6Hours.FontSize = 13.0;
			}
			if (Range24Hours != null)
			{
				Range24Hours.FontSize = 13.0;
			}
			if (Range7Days != null)
			{
				Range7Days.FontSize = 13.0;
			}
			if (RangeCustom != null)
			{
				RangeCustom.FontSize = 13.0;
			}
			radioButton.FontSize = 14.0;
			switch (text)
			{
			case "1":
				_viewModel.SelectedRangeIndex = 0;
				break;
			case "6":
				_viewModel.SelectedRangeIndex = 1;
				break;
			case "24":
				_viewModel.SelectedRangeIndex = 2;
				break;
			case "7d":
				if (!B.i.IsVip)
				{
					ShowVipUpgradeDialogAsync(F.g.A("DeviceDetailsWindow.Range7Days.Content"));
					RestoreRangeTo24Hours();
				}
				else
				{
					_viewModel.SelectedRangeIndex = 3;
				}
				break;
			case "custom":
				if (!B.i.IsVip)
				{
					ShowVipUpgradeDialogAsync(F.g.A("DeviceDetailsWindow.RangeCustom.Content"));
					RestoreRangeTo24Hours();
				}
				else
				{
					HandleCustomRangeAsync();
				}
				break;
			}
		}

