		private async Task HandleCustomRangeAsync()
		{
			System.DateTimeOffset now = System.DateTimeOffset.Now;
			System.DateTimeOffset thirtyDaysAgo = now.AddDays(-30.0);
			Microsoft.UI.Xaml.Controls.DatePicker startDatePicker = new Microsoft.UI.Xaml.Controls.DatePicker
			{
				Header = F.g.A("DeviceDetailsWindow.Dialog.CustomRange.StartDate"),
				Date = now,
				MaxYear = now,
				MinYear = thirtyDaysAgo
			};
			Microsoft.UI.Xaml.Controls.TimePicker startTimePicker = new Microsoft.UI.Xaml.Controls.TimePicker
			{
				Header = F.g.A("DeviceDetailsWindow.Dialog.CustomRange.StartTime"),
				Time = new System.TimeSpan(now.Hour, 0, 0)
			};
			Microsoft.UI.Xaml.Controls.DatePicker endDatePicker = new Microsoft.UI.Xaml.Controls.DatePicker
			{
				Header = F.g.A("DeviceDetailsWindow.Dialog.CustomRange.EndDate"),
				Date = now,
				MaxYear = now,
				MinYear = thirtyDaysAgo
			};
			Microsoft.UI.Xaml.Controls.TimePicker endTimePicker = new Microsoft.UI.Xaml.Controls.TimePicker
			{
				Header = F.g.A("DeviceDetailsWindow.Dialog.CustomRange.EndTime"),
				Time = new System.TimeSpan(now.Hour, now.Minute, 0)
			};
			Microsoft.UI.Xaml.Controls.StackPanel stackPanel = new Microsoft.UI.Xaml.Controls.StackPanel
			{
				Spacing = 12.0
			};
			stackPanel.Children.Add(startDatePicker);
			stackPanel.Children.Add(startTimePicker);
			stackPanel.Children.Add(new Microsoft.UI.Xaml.Controls.Border
			{
				Height = 1.0,
				Background = new SolidColorBrush(Colors.Gray),
				Opacity = 0.3,
				Margin = new Microsoft.UI.Xaml.Thickness(0.0, 8.0, 0.0, 8.0)
			});
			stackPanel.Children.Add(endDatePicker);
			stackPanel.Children.Add(endTimePicker);
			Microsoft.UI.Xaml.Controls.ContentDialog contentDialog = new Microsoft.UI.Xaml.Controls.ContentDialog
			{
				Title = F.g.A("DeviceDetailsWindow.Dialog.CustomRange.Title"),
				Content = stackPanel,
				PrimaryButtonText = F.g.A("Common.OK"),
				CloseButtonText = F.g.A("Common.Cancel"),
				DefaultButton = ContentDialogButton.Primary,
				XamlRoot = RootLayout.XamlRoot
			};
			if (await F.V.A(contentDialog) != ContentDialogResult.Primary)
			{
				RestoreRangeTo24Hours();
				return;
			}
			DateTime date = startDatePicker.Date.Date;
			System.TimeSpan time = startTimePicker.Time;
			System.DateTimeOffset startLocal = new System.DateTimeOffset(date.Year, date.Month, date.Day, time.Hours, time.Minutes, 0, now.Offset);
			DateTime date2 = endDatePicker.Date.Date;
			System.TimeSpan time2 = endTimePicker.Time;
			System.DateTimeOffset endLocal = new System.DateTimeOffset(date2.Year, date2.Month, date2.Day, time2.Hours, time2.Minutes, 0, now.Offset);
			if (startLocal < thirtyDaysAgo)
			{
				Microsoft.UI.Xaml.Controls.ContentDialog contentDialog2 = new Microsoft.UI.Xaml.Controls.ContentDialog
				{
					Title = F.g.A("DeviceDetailsWindow.Dialog.OutOfRange.Title"),
					Content = string.Format(F.g.A("DeviceDetailsWindow.Dialog.OutOfRange.Content"), thirtyDaysAgo.ToLocalTime().ToString("MM-dd HH:mm")),
					CloseButtonText = F.g.A("Common.OK"),
					DefaultButton = ContentDialogButton.Close,
					XamlRoot = RootLayout.XamlRoot
				};
				await F.V.A(contentDialog2);
				startLocal = thirtyDaysAgo;
			}
			if (endLocal <= startLocal)
			{
				Microsoft.UI.Xaml.Controls.ContentDialog contentDialog3 = new Microsoft.UI.Xaml.Controls.ContentDialog
				{
					Title = F.g.A("DeviceDetailsWindow.Dialog.InvalidEndTime.Title"),
					Content = F.g.A("DeviceDetailsWindow.Dialog.InvalidEndTime.Content"),
					CloseButtonText = F.g.A("Common.OK"),
					DefaultButton = ContentDialogButton.Close,
					XamlRoot = RootLayout.XamlRoot
				};
				await F.V.A(contentDialog3);
				endLocal = startLocal.AddHours(24.0);
			}
			if (endLocal > now)
			{
				endLocal = now;
			}
			_viewModel.CustomFromTicks = startLocal.DateTime.ToBinary();
			_viewModel.CustomToTicks = endLocal.DateTime.ToBinary();
			_viewModel.SelectedRangeIndex = 4;
			await _viewModel.RefreshAsync();
		}

