			{
			case DeviceIconType.Preset:
				if (!string.IsNullOrEmpty(_selectedPresetIconId))
				{
					newIconConfig = DeviceIconModel.CreatePreset(_selectedPresetIconId);
					DeviceType detectedDeviceType = PresetIconLibrary.GetIconById(_selectedPresetIconId)?.Category ?? DeviceType.General;
					newIconConfig.DetectedDeviceType = detectedDeviceType;
				}
				break;
			case DeviceIconType.Custom:
				if (string.IsNullOrEmpty(_uploadedCustomIconFileName))
				{
					break;
				}
				if (!string.IsNullOrEmpty(_previewTempFilePath))
				{
					string text = await b.h.A(await StorageFile.GetFileFromPathAsync(_previewTempFilePath), GetConfigKey());
					if (!string.IsNullOrEmpty(text))
					{
						newIconConfig = DeviceIconModel.CreateCustom(text);
					}
				}
				else if (_device.IconConfig?.CustomIconFileName == _uploadedCustomIconFileName)
				{
					newIconConfig = DeviceIconModel.CreateCustom(_uploadedCustomIconFileName);
				}
				break;
			}
			_device.IconConfig = newIconConfig;
			_device.UserConfigKey = GetConfigKey();
			B.I.A(_device.UserConfigKey, newIconConfig);
			b.h.c();
			Logger.A("[DeviceIconSelectorWindow] 设备 " + _device.Name + " 图标配置已更新", "SaveAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\DeviceIconSelectorWindow.xaml.cs", 607);
			Close();
		}

