				if (ReferralCenterButton != null)
				{
					ReferralCenterButton.Visibility = Visibility.Collapsed;
				}
				return;
			}
			bool flag = B.i.IsLoggedIn || B.i.IsSessionRecoverable;
			string text = F.g.A("SettingsWindow.AccountLabel");
			if (AccountUserIdText != null)
			{
				AccountUserIdText.Text = (flag ? (text + ": " + MaskUserId(B.i.UserId)) : (text + ": -"));
				AccountUserIdText.Visibility = Visibility.Visible;
			}
			if (AccountLogoutButton != null)
			{
				AccountLogoutButton.Content = F.g.A("SettingsWindow.AccountLogoutButton.Content");
