		private static string MaskUserId(string? userId)
		{
			if (string.IsNullOrWhiteSpace(userId))
			{
				return "-";
			}
			string text = userId.Trim();
			if (text.Length <= 4)
			{
				return text;
			}
			if (text.Length <= 8)
			{
				return text.Substring(0, 2) + "****" + text.Substring(text.Length - 2, 2);
			}
			return text.Substring(0, 3) + "****" + text.Substring(text.Length - 4, 4);
		}

