							}
							else
							{
								if (comboBox.Header is string value)
								{
									comboBox.Header = F.g.B(value);
								}
								foreach (Microsoft.UI.Xaml.Controls.ComboBoxItem item in comboBox.Items.OfType<Microsoft.UI.Xaml.Controls.ComboBoxItem>())
								{
									if (item.Content is string value2)
									{
