		private static int ApplyCardBackgroundRecursive(Microsoft.UI.Xaml.DependencyObject node, Microsoft.UI.Xaml.Style? targetStyle, Microsoft.UI.Xaml.Media.Brush brush)
		{
			int num = 0;
			if (node is Microsoft.UI.Xaml.Controls.Border border && targetStyle != null && (object)border.Style == targetStyle)
			{
				border.Background = brush;
				num++;
			}
			int childrenCount = VisualTreeHelper.GetChildrenCount(node);
			for (int i = 0; i < childrenCount; i++)
			{
				Microsoft.UI.Xaml.DependencyObject child = VisualTreeHelper.GetChild(node, i);
				num += ApplyCardBackgroundRecursive(child, targetStyle, brush);
			}
			return num;
		}

		private static int RestoreCardBackgroundRecursive(Microsoft.UI.Xaml.DependencyObject node, Microsoft.UI.Xaml.Style? targetStyle)
		{
			int num = 0;
			if (node is Microsoft.UI.Xaml.Controls.Border border && targetStyle != null && (object)border.Style == targetStyle)
			{
				border.ClearValue(Microsoft.UI.Xaml.Controls.Border.BackgroundProperty);
				num++;
			}
			int childrenCount = VisualTreeHelper.GetChildrenCount(node);
			for (int i = 0; i < childrenCount; i++)
			{
				Microsoft.UI.Xaml.DependencyObject child = VisualTreeHelper.GetChild(node, i);
				num += RestoreCardBackgroundRecursive(child, targetStyle);
			}
			return num;
		}

