		private void CenterSettingsWindow(int width, int height)
		{
			try
			{
				if (!(_appWindow == null))
				{
					nint windowHandle = WindowNative.GetWindowHandle(this);
					WindowId windowIdFromWindow = Win32Interop.GetWindowIdFromWindow(windowHandle);
					DisplayArea fromWindowId = DisplayArea.GetFromWindowId(windowIdFromWindow, DisplayAreaFallback.Primary);
					if (fromWindowId != null)
					{
						RectInt32 workArea = fromWindowId.WorkArea;
						int x = workArea.X + (workArea.Width - width) / 2;
						int y = workArea.Y + (workArea.Height - height) / 2;
						_appWindow.Move(new PointInt32(x, y));
					}
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[SettingsWindow] 居中窗口失败: " + ex.Message, "CenterSettingsWindow", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\SettingsWindow.xaml.cs", 2308);
