		private static string ResolveDeviceKey(DeviceModel device)
		{
			string? text;
			if (string.IsNullOrWhiteSpace(device.UserConfigKey))
			{
				text = device.DeviceId;
				if (text == null)
				{
					text = device.Name;
					if (text == null)
					{
						return string.Empty;
					}
				}
			}
			else
			{
				text = device.UserConfigKey;
			}
			return text;
		}

