			{
				using MemoryStream stream = new MemoryStream();
				previewBitmap.Save(stream, ImageFormat.Png);
				stream.Position = 0L;
				using InMemoryRandomAccessStream randomAccessStream = new InMemoryRandomAccessStream();
				await randomAccessStream.WriteAsync(stream.GetWindowsRuntimeBuffer());
				randomAccessStream.Seek(0uL);
				WriteableBitmap writeableBitmap = new WriteableBitmap(48, 48);
				await writeableBitmap.SetSourceAsync(randomAccessStream);
				return writeableBitmap;
			}
		}

