		private async void TestLanReachabilityButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			int unifiedApiPort = B.I.UnifiedApiPort;
			string localhostUrl = $"http://127.0.0.1:{unifiedApiPort}/api/v1/status";
			string dnsLocalhostUrl = $"http://localhost:{unifiedApiPort}/api/v1/status";
			string firstLanIPv = GetFirstLanIPv4();
			string lanUrl = (string.IsNullOrWhiteSpace(firstLanIPv) ? null : $"http://{firstLanIPv}:{unifiedApiPort}/api/v1/status");
			using HttpClient httpClient = b.d.A(System.TimeSpan.FromSeconds(5.0));
			if (B.I.UnifiedApiAuthEnabled)
			{
				string value = (B.I.UnifiedApiToken ?? string.Empty).Trim();
				if (!string.IsNullOrWhiteSpace(value))
				{
					httpClient.DefaultRequestHeaders.Remove("X-Api-Token");
					httpClient.DefaultRequestHeaders.Add("X-Api-Token", value);
				}
			}
			string loopbackResult = await ProbeUrlAsync(httpClient, localhostUrl);
			string localhostNameResult = await ProbeUrlAsync(httpClient, dnsLocalhostUrl);
			string text = ((lanUrl != null) ? (await ProbeUrlAsync(httpClient, lanUrl)) : L("UnifiedApiSettingsWindow.LanResult.NoAddress"));
			string text2 = text;
			string text3 = ((!loopbackResult.Contains("HTTP 200", StringComparison.OrdinalIgnoreCase) && !localhostNameResult.Contains("HTTP 200", StringComparison.OrdinalIgnoreCase)) ? L("UnifiedApiSettingsWindow.LanSuggestion.LoopbackFailed") : ((lanUrl == null || text2.Contains("HTTP 200", StringComparison.OrdinalIgnoreCase)) ? L("UnifiedApiSettingsWindow.LanSuggestion.Passed") : L("UnifiedApiSettingsWindow.LanSuggestion.LanFailed")));
			Microsoft.UI.Xaml.Controls.ContentDialog contentDialog = new Microsoft.UI.Xaml.Controls.ContentDialog();
			contentDialog.Title = L("UnifiedApiSettingsWindow.LanTestResultDialog.Title");
			contentDialog.Content = LF("UnifiedApiSettingsWindow.LanTestResultDialog.Content", localhostUrl, loopbackResult, dnsLocalhostUrl, localhostNameResult, lanUrl ?? L("UnifiedApiSettingsWindow.LanAddressLabel"), text2, text3);
			contentDialog.CloseButtonText = L("Common.OK");
			contentDialog.XamlRoot = base.Content.XamlRoot;
			Microsoft.UI.Xaml.Controls.ContentDialog contentDialog2 = contentDialog;
			await F.V.A(contentDialog2);
		}

		private static async Task<string> ProbeUrlAsync(HttpClient client, string url)
		{
			_ = 1;
			try
			{
				using HttpResponseMessage response = await client.GetAsync(url);
				string server = response.Headers.Server?.ToString() ?? "-";
				string contentType = response.Content.Headers.ContentType?.ToString() ?? "-";
				string bodyHint = string.Empty;
				if (response.StatusCode >= HttpStatusCode.BadRequest)
				{
					string text = await response.Content.ReadAsStringAsync();
					if (!string.IsNullOrWhiteSpace(text))
					{
						text = text.Trim();
						if (text.Length > 120)
						{
							text = text.Substring(0, 120) + "...";
						}
						bodyHint = "; Body=" + text.Replace("\r", " ").Replace("\n", " ");
					}
				}
				return $"HTTP {response.StatusCode} {response.ReasonPhrase}; Server={server}; Content-Type={contentType}{bodyHint}";
			}
			catch (System.Exception ex)
			{
				return LF("UnifiedApiSettingsWindow.ProbeRequestFailed", ex.Message);
			}
		}

		private static string? GetFirstLanIPv4()
		{
			return (from addr in (from nic in NetworkInterface.GetAllNetworkInterfaces()
					where nic.OperationalStatus == OperationalStatus.Up
					where nic.NetworkInterfaceType != NetworkInterfaceType.Loopback
					select nic).SelectMany((NetworkInterface nic) => nic.GetIPProperties().UnicastAddresses)
				select addr.Address).FirstOrDefault((IPAddress ip) => ip.AddressFamily == AddressFamily.InterNetwork && !IPAddress.IsLoopback(ip))?.ToString();
		}

