		private void RestoreWindowState()
		{
			bool flag = B.I.UsbCaptureHelperWindowWidth.HasValue && B.I.UsbCaptureHelperWindowHeight.HasValue;
			int width = (flag ? B.I.UsbCaptureHelperWindowWidth.Value : 1320);
			int height = (flag ? B.I.UsbCaptureHelperWindowHeight.Value : 792);
			_minSizeGuard?.A(ref width, ref height);
			try
			{
				_appWindow.Resize(new SizeInt32(width, height));
				WindowId windowIdFromWindow = Win32Interop.GetWindowIdFromWindow(_windowHandle);
				if (B.I.UsbCaptureHelperWindowX.HasValue && B.I.UsbCaptureHelperWindowY.HasValue)
				{
					DisplayArea fromWindowId = DisplayArea.GetFromWindowId(windowIdFromWindow, DisplayAreaFallback.Primary);
					if (fromWindowId != null)
					{
						RectInt32 workArea = fromWindowId.WorkArea;
						int value = B.I.UsbCaptureHelperWindowX.Value;
						int value2 = B.I.UsbCaptureHelperWindowY.Value;
						if (value >= workArea.X && value < workArea.X + workArea.Width - 100 && value2 >= workArea.Y && value2 < workArea.Y + workArea.Height - 100)
						{
							_appWindow.Move(new PointInt32(value, value2));
							return;
						}
					}
				}
				CenterWindow(width, height);
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 恢复窗口状态失败: " + ex.Message, "RestoreWindowState", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 290);
			}
		}

		private void CenterWindow(int width, int height)
		{
			try
			{
				WindowId windowIdFromWindow = Win32Interop.GetWindowIdFromWindow(_windowHandle);
				DisplayArea fromWindowId = DisplayArea.GetFromWindowId(windowIdFromWindow, DisplayAreaFallback.Primary);
				if (fromWindowId != null)
				{
					RectInt32 workArea = fromWindowId.WorkArea;
					int x = workArea.X + (workArea.Width - width) / 2;
					int y = workArea.Y + (workArea.Height - height) / 2;
					_appWindow.Move(new PointInt32(x, y));
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 居中窗口失败: " + ex.Message, "CenterWindow", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 310);
			}
		}

