		private void ApplyConfiguredHotkeys()
		{
			ConfigureAccelerator(ScanSnapshotAHotkeyAccelerator, _scanAHotkeyText, "Ctrl+Alt+1");
			ConfigureAccelerator(ScanSnapshotBHotkeyAccelerator, _scanBHotkeyText, "Ctrl+Alt+2");
			ConfigureAccelerator(CaptureToggleHotkeyAccelerator, _captureToggleHotkeyText, "Ctrl+Alt+3");
			UpdateHotkeySummaryText();
