		private void ConfigureAccelerator(KeyboardAccelerator accelerator, string configuredValue, string fallback)
		{
			if (!TryParseHotkey(configuredValue, out var key, out var modifiers))
			{
				TryParseHotkey(fallback, out key, out modifiers);
			}
			accelerator.Key = key;
			accelerator.Modifiers = modifiers;
		}

		private void UpdateHotkeySummaryText()
		{
			CaptureHotkeySummaryText.Text = LF("UsbCaptureHelperWindow.Hotkey.Summary.Template", "快捷键：快照A {0} / 快照B {1} / 抓包 {2}", _scanAHotkeyText, _scanBHotkeyText, _captureToggleHotkeyText);
		}

		private static bool TryParseHotkey(string? value, out VirtualKey key, out VirtualKeyModifiers modifiers)
		{
			key = VirtualKey.None;
			modifiers = VirtualKeyModifiers.None;
			if (string.IsNullOrWhiteSpace(value))
			{
				return false;
			}
			string[] array = value.Split('+', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
			if (array.Length < 2)
			{
				return false;
			}
			for (int i = 0; i < array.Length - 1; i++)
			{
				string text = array[i];
				if (text.Equals("Ctrl", StringComparison.OrdinalIgnoreCase) || text.Equals("Control", StringComparison.OrdinalIgnoreCase))
				{
					modifiers |= VirtualKeyModifiers.Control;
				}
				else if (text.Equals("Alt", StringComparison.OrdinalIgnoreCase) || text.Equals("Menu", StringComparison.OrdinalIgnoreCase))
				{
					modifiers |= VirtualKeyModifiers.Menu;
				}
				else if (text.Equals("Shift", StringComparison.OrdinalIgnoreCase))
				{
					modifiers |= VirtualKeyModifiers.Shift;
				}
			}
			string text2 = array[^1];
			VirtualKey result3;
			if (text2.Length == 1)
			{
				char c = char.ToUpperInvariant(text2[0]);
				VirtualKey result2;
				if (char.IsLetter(c) && Enum.TryParse<VirtualKey>(c.ToString(), out var result))
				{
					key = result;
				}
				else if (char.IsDigit(c) && Enum.TryParse<VirtualKey>($"Number{c}", out result2))
				{
					key = result2;
				}
			}
			else if (Enum.TryParse<VirtualKey>(text2, ignoreCase: true, out result3))
			{
				key = result3;
			}
			if (key != VirtualKey.None)
			{
				return modifiers != VirtualKeyModifiers.None;
			}
			return false;
		}

		private static string FormatHotkey(VirtualKey key, VirtualKeyModifiers modifiers)
		{
			List<string> list = new List<string>();
			if ((modifiers & VirtualKeyModifiers.Control) == VirtualKeyModifiers.Control)
			{
				list.Add("Ctrl");
			}
			if ((modifiers & VirtualKeyModifiers.Menu) == VirtualKeyModifiers.Menu)
			{
				list.Add("Alt");
			}
			if ((modifiers & VirtualKeyModifiers.Shift) == VirtualKeyModifiers.Shift)
			{
				list.Add("Shift");
			}
			string text = ((key >= VirtualKey.Number0 && key <= VirtualKey.Number9) ? ((int)(key - 48)).ToString() : key.ToString().Replace("Number", string.Empty, StringComparison.OrdinalIgnoreCase));
			list.Add(text.ToUpperInvariant());
			return string.Join('+', list);
		}

		private static IReadOnlyList<HotkeyKeyOption> BuildHotkeyKeyOptions()
		{
			List<HotkeyKeyOption> list = new List<HotkeyKeyOption>();
			for (char c = 'A'; c <= 'Z'; c = (char)(c + 1))
			{
				if (Enum.TryParse<VirtualKey>(c.ToString(), out var result))
				{
					list.Add(new HotkeyKeyOption(c.ToString(), result));
				}
			}
			for (int i = 0; i <= 9; i++)
			{
				if (Enum.TryParse<VirtualKey>($"Number{i}", out var result2))
				{
					list.Add(new HotkeyKeyOption(i.ToString(), result2));
				}
			}
			for (int j = 1; j <= 12; j++)
			{
				if (Enum.TryParse<VirtualKey>($"F{j}", out var result3))
				{
					list.Add(new HotkeyKeyOption($"F{j}", result3));
				}
			}
			return list;
		}

		private async void CaptureHotkeySettingButton_Click(object sender, Microsoft.UI.Xaml.RoutedEventArgs e)
		{
			var (scanAKey, scanAModifiers) = GetOrDefaultHotkey(_scanAHotkeyText, "Ctrl+Alt+1");
			var (scanBKey, scanBModifiers) = GetOrDefaultHotkey(_scanBHotkeyText, "Ctrl+Alt+2");
			var (captureKey, captureModifiers) = GetOrDefaultHotkey(_captureToggleHotkeyText, "Ctrl+Alt+3");
			while (true)
			{
				Microsoft.UI.Xaml.Controls.StackPanel stackPanel = new Microsoft.UI.Xaml.Controls.StackPanel
				{
					Spacing = 12.0
				};
				HotkeySelectorRow scanARow = CreateHotkeyRow(L("UsbCaptureHelperWindow.Hotkey.ScanA.Label", "快照A"), scanAModifiers, scanAKey);
				stackPanel.Children.Add(scanARow.Container);
				HotkeySelectorRow scanBRow = CreateHotkeyRow(L("UsbCaptureHelperWindow.Hotkey.ScanB.Label", "快照B"), scanBModifiers, scanBKey);
				stackPanel.Children.Add(scanBRow.Container);
				HotkeySelectorRow captureRow = CreateHotkeyRow(L("UsbCaptureHelperWindow.Hotkey.Capture.Label", "抓包开始/停止"), captureModifiers, captureKey);
				stackPanel.Children.Add(captureRow.Container);
				Microsoft.UI.Xaml.Controls.ContentDialog contentDialog = new Microsoft.UI.Xaml.Controls.ContentDialog
				{
					Title = L("UsbCaptureHelperWindow.Hotkey.Dialog.Title", "设置快捷键"),
					Content = stackPanel,
					PrimaryButtonText = L("Common.Save", "保存"),
					SecondaryButtonText = L("UsbCaptureHelperWindow.Hotkey.Dialog.Reset", "恢复默认"),
					CloseButtonText = L("Common.Cancel", "取消"),
					DefaultButton = ContentDialogButton.Primary,
					XamlRoot = base.Content.XamlRoot
				};
				switch (await F.V.A(contentDialog))
				{
				case ContentDialogResult.None:
					return;
				case ContentDialogResult.Secondary:
					_scanAHotkeyText = "Ctrl+Alt+1";
					_scanBHotkeyText = "Ctrl+Alt+2";
					_captureToggleHotkeyText = "Ctrl+Alt+3";
					SaveHotkeySettings();
					ApplyConfiguredHotkeys();
					AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.HotkeyReset", "快捷键已恢复默认。"));
					return;
				}
				(VirtualKey, VirtualKeyModifiers) selectedHotkey = GetSelectedHotkey(scanARow.ModifierComboBox, scanARow.KeyComboBox);
				(VirtualKey, VirtualKeyModifiers) selectedHotkey2 = GetSelectedHotkey(scanBRow.ModifierComboBox, scanBRow.KeyComboBox);
				(VirtualKey, VirtualKeyModifiers) selectedHotkey3 = GetSelectedHotkey(captureRow.ModifierComboBox, captureRow.KeyComboBox);
				string text = FormatHotkey(selectedHotkey.Item1, selectedHotkey.Item2);
				string text2 = FormatHotkey(selectedHotkey2.Item1, selectedHotkey2.Item2);
				string text3 = FormatHotkey(selectedHotkey3.Item1, selectedHotkey3.Item2);
				if (!string.Equals(text, text2, StringComparison.OrdinalIgnoreCase) && !string.Equals(text, text3, StringComparison.OrdinalIgnoreCase) && !string.Equals(text2, text3, StringComparison.OrdinalIgnoreCase))
				{
					_scanAHotkeyText = text;
					_scanBHotkeyText = text2;
					_captureToggleHotkeyText = text3;
					SaveHotkeySettings();
					ApplyConfiguredHotkeys();
					AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.HotkeySaved", "快捷键设置已保存。"));
					return;
				}
				await ShowInfoDialogAsync(L("UsbCaptureHelperWindow.Hotkey.Dialog.Duplicate.Title", "快捷键冲突"), L("UsbCaptureHelperWindow.Hotkey.Dialog.Duplicate.Content", "三个操作不能使用相同快捷键，请重新设置。"), L("Common.OK", "确定"));
			}
		}

		private static (VirtualKey Key, VirtualKeyModifiers Modifiers) GetOrDefaultHotkey(string value, string fallback)
		{
			if (TryParseHotkey(value, out var key, out var modifiers))
			{
				return (Key: key, Modifiers: modifiers);
			}
			if (TryParseHotkey(fallback, out key, out modifiers))
			{
				return (Key: key, Modifiers: modifiers);
			}
			return (Key: VirtualKey.Number1, Modifiers: VirtualKeyModifiers.Control | VirtualKeyModifiers.Menu);
		}

		private void SaveHotkeySettings()
		{
			B.I.UsbCaptureScanAHotkey = _scanAHotkeyText;
			B.I.UsbCaptureScanBHotkey = _scanBHotkeyText;
			B.I.UsbCaptureToggleHotkey = _captureToggleHotkeyText;
		}

		private static (VirtualKey Key, VirtualKeyModifiers Modifiers) GetSelectedHotkey(Microsoft.UI.Xaml.Controls.ComboBox modifierBox, Microsoft.UI.Xaml.Controls.ComboBox keyBox)
		{
			HotkeyModifierOption hotkeyModifierOption = modifierBox.SelectedItem as HotkeyModifierOption;
			HotkeyKeyOption hotkeyKeyOption = keyBox.SelectedItem as HotkeyKeyOption;
			VirtualKeyModifiers item = hotkeyModifierOption?.Modifiers ?? (VirtualKeyModifiers.Control | VirtualKeyModifiers.Menu);
			VirtualKey item2 = hotkeyKeyOption?.Key ?? VirtualKey.Number1;
			return (Key: item2, Modifiers: item);
		}

		private static HotkeySelectorRow CreateHotkeyRow(string title, VirtualKeyModifiers selectedModifiers, VirtualKey selectedKey)
		{
			Microsoft.UI.Xaml.Controls.StackPanel stackPanel = new Microsoft.UI.Xaml.Controls.StackPanel
			{
				Spacing = 4.0
			};
			stackPanel.Children.Add(new Microsoft.UI.Xaml.Controls.TextBlock
			{
				Text = title,
				FontWeight = FontWeights.SemiBold
			});
			Microsoft.UI.Xaml.Controls.Grid grid = new Microsoft.UI.Xaml.Controls.Grid
			{
				ColumnSpacing = 8.0
			};
			grid.ColumnDefinitions.Add(new Microsoft.UI.Xaml.Controls.ColumnDefinition
			{
				Width = new Microsoft.UI.Xaml.GridLength(1.0, Microsoft.UI.Xaml.GridUnitType.Star)
			});
			grid.ColumnDefinitions.Add(new Microsoft.UI.Xaml.Controls.ColumnDefinition
			{
				Width = new Microsoft.UI.Xaml.GridLength(1.0, Microsoft.UI.Xaml.GridUnitType.Star)
			});
			Microsoft.UI.Xaml.Controls.ComboBox comboBox = new Microsoft.UI.Xaml.Controls.ComboBox
			{
				ItemsSource = HotkeyModifierOptions,
				DisplayMemberPath = "Display",
				HorizontalAlignment = HorizontalAlignment.Stretch
			};
			Microsoft.UI.Xaml.Controls.ComboBox comboBox2 = new Microsoft.UI.Xaml.Controls.ComboBox
			{
				ItemsSource = HotkeyKeyOptions,
				DisplayMemberPath = "Display",
				HorizontalAlignment = HorizontalAlignment.Stretch
			};
			comboBox.SelectedItem = HotkeyModifierOptions.FirstOrDefault((HotkeyModifierOption item) => item.Modifiers == selectedModifiers) ?? HotkeyModifierOptions[0];
			comboBox2.SelectedItem = HotkeyKeyOptions.FirstOrDefault((HotkeyKeyOption item) => item.Key == selectedKey) ?? HotkeyKeyOptions[0];
			Microsoft.UI.Xaml.Controls.Grid.SetColumn(comboBox, 0);
			Microsoft.UI.Xaml.Controls.Grid.SetColumn(comboBox2, 1);
			grid.Children.Add(comboBox);
			grid.Children.Add(comboBox2);
			stackPanel.Children.Add(grid);
			return new HotkeySelectorRow(stackPanel, comboBox, comboBox2);
		}

