		private void ApplyCaptureModeUi(bool refreshStatus)
		{
			bool flag = _captureMode == UsbCaptureMode.FullInterface;
			SnapshotModeRadioButton.IsChecked = !flag;
			FullInterfaceModeRadioButton.IsChecked = flag;
			SnapshotCard.Visibility = (flag ? Visibility.Collapsed : Visibility.Visible);
			FullInterfaceCard.Visibility = ((!flag) ? Visibility.Collapsed : Visibility.Visible);
			CaptureModeHintText.Text = (flag ? L("UsbCaptureHelperWindow.CaptureMode.FullInterface.Hint", "Full mode captures all traffic on the selected USBPcap interface. Exit the official driver first, start capture, then open the driver to trigger battery detection.") : L("UsbCaptureHelperWindow.CaptureMode.Snapshot.Hint", "A/B snapshot mode locates the receiver by unplugging and plugging it, then captures only that USB address."));
			CaptureHintFlowText.Text = (flag ? L("UsbCaptureHelperWindow.CaptureHintFlow.FullInterface.Text", "1) Fully exit the official driver  2) Select USBPcap1/2/3 and start capture  3) Open the official driver until battery level is detected  4) Stop capture") : L("UsbCaptureHelperWindow.CaptureHintFlow.Text", "1) Fully exit the official driver  2) Start capture  3) Open the official driver until battery level is detected  4) Stop capture"));
			RefreshModeTargetText(refreshStatus);
			UpdateCaptureButtonState();
		}

		private void RefreshModeTargetText(bool refreshStatus)
		{
			if (_captureMode == UsbCaptureMode.FullInterface)
			{
				UsbPcapInterfaceItem selectedFullInterface = GetSelectedFullInterface();
				if (selectedFullInterface != null)
				{
					FullInterfaceStatusText.Text = LF("UsbCaptureHelperWindow.FullInterface.Status.Selected.Template", "Selected interface: {0}", selectedFullInterface.DisplayName);
					CaptureTargetText.Text = LF("UsbCaptureHelperWindow.CaptureTarget.FullInterface.Template", "Capture target: full interface {0}", selectedFullInterface.DisplayName);
					if (refreshStatus && !_isCapturing)
					{
						CaptureStatusText.Text = L("UsbCaptureHelperWindow.CaptureStatus.FullInterfaceReady", "Status: ready for full interface capture");
					}
				}
				else
				{
					FullInterfaceStatusText.Text = ((_usbPcapInterfaces.Count == 0) ? L("UsbCaptureHelperWindow.FullInterface.Status.Empty", "USBPcap interfaces: none found. Click refresh after USBPcap is ready.") : L("UsbCaptureHelperWindow.FullInterface.Status.Select", "USBPcap interfaces: please select one interface."));
					CaptureTargetText.Text = L("UsbCaptureHelperWindow.CaptureTarget.FullInterfacePending", "Capture target: select a USBPcap interface");
					if (refreshStatus && !_isCapturing)
					{
						CaptureStatusText.Text = L("UsbCaptureHelperWindow.CaptureStatus.FullInterfaceSelect", "Status: select a USBPcap interface");
					}
				}
			}
			else if (!string.IsNullOrWhiteSpace(_selectedInterface) && _selectedAddresses.Count > 0)
			{
				CaptureTargetText.Text = LF("UsbCaptureHelperWindow.CaptureTarget.Locked.Template", "Capture target: {0} / Addresses {1} / VID {2} / PID {3}", _selectedInterface, FormatAddressList(_selectedAddresses), string.IsNullOrWhiteSpace(_selectedVid) ? "Unknown" : _selectedVid, string.IsNullOrWhiteSpace(_selectedPid) ? "Unknown" : _selectedPid);
				if (refreshStatus && !_isCapturing)
				{
					CaptureStatusText.Text = L("UsbCaptureHelperWindow.CaptureStatus.Ready", "Status: ready to capture");
				}
			}
			else if (refreshStatus && !_isCapturing)
			{
				CaptureTargetText.Text = L("UsbCaptureHelperWindow.CaptureTarget.Pending", "Capture target: not locked");
			}
		}

		private async Task CheckEnvironmentAsync()
		{
			try
			{
				if (!TryResolveUsbPcapPath(out string resolvedPath))
				{
					EnvironmentStatusText.Text = L("UsbCaptureHelperWindow.Env.NotFound", "环境检测：未找到 USBPcapCmd.exe，请先安装 USBPcap。");
					UsbPcapDownloadHintText.Visibility = Visibility.Visible;
					return;
				}
				_resolvedUsbPcapPath = resolvedPath;
				EnvironmentStatusText.Text = LF("UsbCaptureHelperWindow.Env.Ready.Template", "环境检测：✅ 已找到 USBPcapCmd ({0})", resolvedPath);
				ScanSnapshotAButton.IsEnabled = true;
				ScanSnapshotBButton.IsEnabled = true;
				UsbPcapDownloadHintText.Visibility = Visibility.Collapsed;
				AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.EnvReady", "环境检测通过，可开始拔插对比。"));
				await RefreshFullInterfacesAsync(showBusy: false);
				UpdateCaptureButtonState();
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 环境检测异常: " + ex.Message, "CheckEnvironmentAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1025);
				EnvironmentStatusText.Text = LF("UsbCaptureHelperWindow.Env.Error.Template", "环境检测失败：{0}", ex.Message);
				UsbPcapDownloadHintText.Visibility = Visibility.Visible;
			}
			await Task.CompletedTask;
		}

		private bool TryResolveUsbPcapPath(out string? resolvedPath)
		{
			string usbPcapCmdPath = B.I.UsbPcapCmdPath;
			if (IsUsbPcapCmdPath(usbPcapCmdPath))
			{
				resolvedPath = usbPcapCmdPath;
				return true;
			}
			if (File.Exists("C:\\Program Files\\USBPcap\\USBPcapCmd.exe"))
			{
				resolvedPath = "C:\\Program Files\\USBPcap\\USBPcapCmd.exe";
				return true;
			}
			string environmentVariable = Environment.GetEnvironmentVariable("PATH");
			if (!string.IsNullOrWhiteSpace(environmentVariable))
			{
				string[] array = environmentVariable.Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
				foreach (string path in array)
				{
					string text = System.IO.Path.Combine(path, "USBPcapCmd.exe");
					if (File.Exists(text))
					{
						resolvedPath = text;
						return true;
					}
				}
			}
			resolvedPath = null;
			return false;
		}

