					_resolvedUsbPcapPath = storageFile.Path;
					EnvironmentStatusText.Text = LF("UsbCaptureHelperWindow.Env.Ready.Template", "环境检测：✅ 已找到 USBPcapCmd ({0})", storageFile.Path);
					UsbPcapDownloadHintText.Visibility = Visibility.Collapsed;
					AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.EnvReady", "环境检测通过，可开始拔插对比。"));
					await RefreshFullInterfacesAsync(showBusy: false);
					UpdateCaptureButtonState();
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 手动选择 USBPcapCmd 失败: " + ex.Message, "ManualSelectUsbPcapButton_Click", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1101);
				EnvironmentStatusText.Text = LF("UsbCaptureHelperWindow.Env.Error.Template", "环境检测失败：{0}", ex.Message);
				UsbPcapDownloadHintText.Visibility = Visibility.Visible;
			}
		}

		private static bool IsUsbPcapCmdPath(string? path)
		{
			if (!string.IsNullOrWhiteSpace(path) && string.Equals(System.IO.Path.GetFileName(path), "USBPcapCmd.exe", StringComparison.OrdinalIgnoreCase))
			{
				return File.Exists(path);
			}
			return false;
		}

