		private async Task RefreshFullInterfacesAsync(bool showBusy)
		{
			if (string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				_usbPcapInterfaces.Clear();
				FullInterfaceStatusText.Text = L("UsbCaptureHelperWindow.FullInterface.Status.EnvMissing", "USBPcap interfaces: USBPcapCmd.exe is not ready.");
				RefreshModeTargetText(refreshStatus: true);
				return;
			}
			string previousInterfaceName = GetSelectedFullInterface()?.InterfaceName;
			try
			{
				if (showBusy)
				{
					SetBusyState(isBusy: true, L("UsbCaptureHelperWindow.CaptureStatus.RefreshingInterfaces", "Status: refreshing USBPcap interfaces..."));
				}
				List<UsbPcapInterfaceItem> list = await GetUsbPcapInterfacesAsync();
				_usbPcapInterfaces.Clear();
				foreach (UsbPcapInterfaceItem item in list)
				{
					_usbPcapInterfaces.Add(item);
				}
				UsbPcapInterfaceItem usbPcapInterfaceItem = _usbPcapInterfaces.FirstOrDefault((UsbPcapInterfaceItem item) => string.Equals(item.InterfaceName, previousInterfaceName, StringComparison.OrdinalIgnoreCase));
				FullInterfaceComboBox.SelectedItem = usbPcapInterfaceItem ?? _usbPcapInterfaces.FirstOrDefault();
				FullInterfaceStatusText.Text = LF("UsbCaptureHelperWindow.FullInterface.Status.Refreshed.Template", "USBPcap interfaces refreshed: {0}", _usbPcapInterfaces.Count);
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.InterfacesRefreshed.Template", "USBPcap interfaces refreshed: {0}", string.Join(", ", _usbPcapInterfaces.Select((UsbPcapInterfaceItem item) => item.DisplayName))));
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] Refresh USBPcap interfaces failed: " + ex.Message, "RefreshFullInterfacesAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1165);
				_usbPcapInterfaces.Clear();
				FullInterfaceStatusText.Text = LF("UsbCaptureHelperWindow.FullInterface.Status.Error.Template", "USBPcap interface refresh failed: {0}", ex.Message);
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.InterfaceRefreshFail.Template", "USBPcap interface refresh failed: {0}", ex.Message));
			}
			finally
			{
				if (showBusy)
				{
					SetBusyState(isBusy: false, string.Empty);
				}
				RefreshModeTargetText(refreshStatus: true);
				UpdateCaptureButtonState();
			}
		}

		private async Task<List<UsbPcapInterfaceItem>> GetUsbPcapInterfacesAsync()
		{
			if (string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				throw new InvalidOperationException(L("UsbCaptureHelperWindow.Error.UsbPcapMissing", "USBPcapCmd.exe was not found"));
			}
			string input = await ExecuteReadProcessAsync(_resolvedUsbPcapPath, "--extcap-interfaces");
			List<UsbPcapInterfaceItem> list = (from @group in (from item in _interfaceRegex.Matches(input).Select(delegate(Match match)
					{
						string interfaceName = match.Groups[1].Value.Trim();
						string displayName = ((match.Groups.Count > 2) ? match.Groups[2].Value.Trim() : string.Empty);
						return new UsbPcapInterfaceItem(interfaceName, displayName);
					})
					where !string.IsNullOrWhiteSpace(item.InterfaceName)
					select item).GroupBy<UsbPcapInterfaceItem, string>((UsbPcapInterfaceItem item) => item.InterfaceName, StringComparer.OrdinalIgnoreCase)
				select @group.First()).ToList();
			Logger.A($"[UsbCaptureHelperWindow] USBPcap interfaces enumerated: count={list.Count}, interfaces={string.Join(", ", list.Select((UsbPcapInterfaceItem item) => item.DisplayName))}", "GetUsbPcapInterfacesAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1208);
			return list;
		}

