				}
				await StopLiveCaptureSessionAsync();
				await WaitForFileReadIdleAsync();
				_isCapturing = false;
				_useLivePipeCapture = false;
				_useFilePollingFallback = false;
				_pcapReader = null;
				ClearCapturedPacketViewerData();
				TryClearCaptureOutputFile(capturePath);
				_currentCapturePath = capturePath;
				CaptureOutputText.Text = LF("UsbCaptureHelperWindow.CaptureOutput.Template", "输出文件：{0}", _currentCapturePath);
				Interlocked.Exchange(ref _suppressPacketQueueing, 0);
				await StartCaptureProcessForCurrentPathAsync();
				AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.RestartCaptureDone", "Capture restarted with a cleared pcap file."));
			}
			catch (Win32Exception ex2) when (ex2.NativeErrorCode == 1223)
			{
