			catch (System.Exception ex3)
			{
				_isCapturing = false;
				_useLivePipeCapture = false;
				_useFilePollingFallback = false;
				CaptureStatusText.Text = L("UsbCaptureHelperWindow.CaptureStatus.StartFailed", "当前状态：启动失败");
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.CaptureStartFail.Template", "抓包启动失败：{0}", ex3.Message));
				UpdateCaptureButtonState();
			}
			finally
			{
				Interlocked.Exchange(ref _suppressPacketQueueing, 0);
				ClearCapturedPacketsButton.IsEnabled = true;
			}
		}

