		private List<DeviceSnapshotItem> ParseInterfaceSnapshot(string interfaceName, string configOutput)
		{
			List<DeviceSnapshotItem> list = new List<DeviceSnapshotItem>();
			if (string.IsNullOrWhiteSpace(configOutput))
			{
				return list;
			}
			string[] array = configOutput.Split(new string[2] { "\r\n", "\n" }, StringSplitOptions.None);
			for (int i = 0; i < array.Length; i++)
			{
				Match match = _addressRegex.Match(array[i]);
				if (match.Success && int.TryParse(match.Groups[1].Value, out var result))
				{
					DeviceSnapshotItem deviceSnapshotItem = new DeviceSnapshotItem
					{
						InterfaceName = interfaceName,
						Address = result
					};
					if (TryExtractVidPidFromContext(array, i, out string vid, out string pid))
					{
						deviceSnapshotItem.Vid = vid;
						deviceSnapshotItem.Pid = pid;
					}
					list.Add(deviceSnapshotItem);
				}
			}
			return list;
		}

		private bool TryExtractVidPidFromContext(string[] lines, int centerIndex, out string? vid, out string? pid)
		{
			vid = null;
			pid = null;
			int num = Math.Max(0, centerIndex - 6);
			int num2 = Math.Min(lines.Length - 1, centerIndex + 6);
			for (int i = num; i <= num2; i++)
			{
				string text = lines[i] ?? string.Empty;
				if (string.IsNullOrWhiteSpace(text))
				{
					continue;
				}
				Match match = _vidPidPairRegex.Match(text);
				if (match.Success)
				{
					vid = NormalizeUsbIdToken(match.Groups[1].Value);
					pid = NormalizeUsbIdToken(match.Groups[2].Value);
					if (!string.IsNullOrWhiteSpace(vid) && !string.IsNullOrWhiteSpace(pid))
					{
						return true;
					}
				}
				Match match2 = _vidRegex.Match(text);
				Match match3 = _pidRegex.Match(text);
				if (match2.Success)
				{
					vid = NormalizeUsbIdToken(match2.Groups[1].Value);
				}
				if (match3.Success)
				{
					pid = NormalizeUsbIdToken(match3.Groups[1].Value);
				}
				if (!string.IsNullOrWhiteSpace(vid) && !string.IsNullOrWhiteSpace(pid))
				{
					return true;
				}
			}
			return false;
		}

		private static string? NormalizeUsbIdToken(string? value)
		{
			if (string.IsNullOrWhiteSpace(value))
			{
				return null;
			}
			string text = value.Trim();
			if (text.Length > 4)
			{
				text = text.Substring(text.Length - 4, 4);
			}
			return text.ToUpperInvariant();
		}

		private async Task<HashSet<string>> GetConnectedHidVidPidTokensAsync()
		{
			try
			{
				string input = await ExecuteReadProcessAsync("pnputil.exe", "/enum-devices /connected /class HIDClass");
				IEnumerable<string> collection = (from match in _vidPidPairRegex.Matches(input)
					select (Vid: NormalizeUsbIdToken(match.Groups[1].Value), Pid: NormalizeUsbIdToken(match.Groups[2].Value)) into pair
					where !string.IsNullOrWhiteSpace(pair.Vid) && !string.IsNullOrWhiteSpace(pair.Pid)
					select pair.Vid + "|" + pair.Pid).Distinct<string>(StringComparer.OrdinalIgnoreCase);
				HashSet<string> hashSet = new HashSet<string>(collection, StringComparer.OrdinalIgnoreCase);
				Logger.A($"[UsbCaptureHelperWindow] HIDClass VID/PID 枚举完成: tokenCount={hashSet.Count}, tokens={SummarizeTokens(hashSet)}", "GetConnectedHidVidPidTokensAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1801);
				return hashSet;
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 读取 HID VID/PID 失败: " + ex.Message, "GetConnectedHidVidPidTokensAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1806);
				return new HashSet<string>();
			}
		}

		private async Task<string> ExecuteReadProcessAsync(string fileName, string arguments)
		{
			ProcessStartInfo startInfo = new ProcessStartInfo
			{
				FileName = fileName,
				Arguments = arguments,
				UseShellExecute = false,
				RedirectStandardOutput = true,
				RedirectStandardError = true,
				CreateNoWindow = true,
				WindowStyle = ProcessWindowStyle.Hidden,
				StandardOutputEncoding = Encoding.UTF8,
				StandardErrorEncoding = Encoding.UTF8
			};
			Process process = Process.Start(startInfo);
			try
			{
				if (process == null)
				{
					throw new InvalidOperationException(L("UsbCaptureHelperWindow.Error.ProcessStartFailed", "无法启动命令进程"));
				}
				string stdout = await process.StandardOutput.ReadToEndAsync();
				string stderr = await process.StandardError.ReadToEndAsync();
				await Task.Run(delegate
				{
					process.WaitForExit();
				});
				string text = (string.IsNullOrWhiteSpace(stdout) ? stderr : stdout);
				if (process.ExitCode != 0 && string.IsNullOrWhiteSpace(text))
				{
					throw new InvalidOperationException(LF("UsbCaptureHelperWindow.Error.ProcessExitCode.Template", "命令执行失败，退出码：{0}", process.ExitCode));
				}
				return text;
			}
			finally
			{
				if (process != null)
				{
					((IDisposable)process).Dispose();
				}
			}
		}

