		private bool TryResolveCaptureTarget(List<DeviceSnapshotItem> added, string? preferredVid, string? preferredPid, out string? interfaceName, out List<int> addresses, out string? vid, out string? pid)
		{
			interfaceName = null;
			addresses = new List<int>();
			vid = null;
			pid = null;
			if (added.Count == 0)
			{
				return false;
			}
			if (added.Count == 1)
			{
				DeviceSnapshotItem deviceSnapshotItem = added[0];
				interfaceName = deviceSnapshotItem.InterfaceName;
				int num = 1;
				List<int> list = new List<int>(num);
				CollectionsMarshal.SetCount(list, num);
				Span<int> span = CollectionsMarshal.AsSpan(list);
				int index = 0;
				span[index] = deviceSnapshotItem.Address;
				addresses = list;
				vid = preferredVid ?? deviceSnapshotItem.Vid;
				pid = preferredPid ?? deviceSnapshotItem.Pid;
				return true;
			}
			List<IGrouping<string, DeviceSnapshotItem>> list2 = added.GroupBy<DeviceSnapshotItem, string>((DeviceSnapshotItem item) => item.InterfaceName, StringComparer.OrdinalIgnoreCase).ToList();
			if (list2.Count != 1)
			{
				return false;
			}
			List<DeviceSnapshotItem> source = list2[0].OrderBy((DeviceSnapshotItem item) => item.Address).ToList();
			string text = ResolveSingleKnownValue(source.Select((DeviceSnapshotItem item) => item.Vid));
			string text2 = ResolveSingleKnownValue(source.Select((DeviceSnapshotItem item) => item.Pid));
			string text3 = preferredVid ?? text;
			string text4 = preferredPid ?? text2;
			if (string.IsNullOrWhiteSpace(text3) || string.IsNullOrWhiteSpace(text4))
			{
				return false;
			}
			interfaceName = list2[0].Key;
			addresses = source.Select((DeviceSnapshotItem item) => item.Address).Distinct().ToList();
			vid = text3;
			pid = text4;
			Logger.A($"[UsbCaptureHelperWindow] 复合目标识别成功: interface={interfaceName}, addresses={FormatAddressList(addresses)}, vid={vid}, pid={pid}", "TryResolveCaptureTarget", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 1970);
			return true;
		}

		private (string? Vid, string? Pid) ResolveVidPidFromHidDiff()
		{
			if (_hidVidPidB.Count == 0)
