		private static string SummarizeSnapshotItems(IEnumerable<DeviceSnapshotItem> items, int maxItems = 8)
		{
			List<DeviceSnapshotItem> list = items.Take(maxItems + 1).ToList();
			if (list.Count == 0)
			{
				return "<empty>";
			}
			bool flag = list.Count > maxItems;
			IEnumerable<DeviceSnapshotItem> enumerable2;
			if (!flag)
			{
				IEnumerable<DeviceSnapshotItem> enumerable = list;
				enumerable2 = enumerable;
			}
			else
			{
				enumerable2 = list.Take(maxItems);
			}
			IEnumerable<DeviceSnapshotItem> source = enumerable2;
			string text = string.Join("; ", source.Select((DeviceSnapshotItem item) => $"{item.InterfaceName}@{item.Address}[VID={item.Vid ?? "?"},PID={item.Pid ?? "?"}]"));
			if (!flag)
			{
				return text;
			}
			return text + "; ...";
		}

		private static string SummarizeTokens(IEnumerable<string> tokens, int maxItems = 8)
		{
			List<string> list = tokens.Take(maxItems + 1).ToList();
			if (list.Count == 0)
			{
				return "<empty>";
			}
			bool flag = list.Count > maxItems;
			IEnumerable<string> enumerable2;
			if (!flag)
			{
				IEnumerable<string> enumerable = list;
				enumerable2 = enumerable;
			}
			else
			{
				enumerable2 = list.Take(maxItems);
			}
			IEnumerable<string> values = enumerable2;
			string text = string.Join(", ", values);
			if (!flag)
			{
				return text;
			}
			return text + ", ...";
		}

