		private string BuildCaptureArguments()
		{
			if (string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				throw new InvalidOperationException("Capture output path is missing.");
			}
			string value = ((_useLivePipeCapture && _liveCaptureSession != null) ? _liveCaptureSession.PipePath : _currentCapturePath);
			string value2 = ((_useLivePipeCapture || _useFilePollingFallback) ? " -b 4096" : string.Empty);
			if (_captureMode == UsbCaptureMode.FullInterface)
			{
				UsbPcapInterfaceItem usbPcapInterfaceItem = GetSelectedFullInterface() ?? throw new InvalidOperationException(L("UsbCaptureHelperWindow.Error.FullInterfaceMissing", "USBPcap interface is not selected"));
				return $"-d \"{usbPcapInterfaceItem.InterfaceName}\" --capture-from-all-devices --inject-descriptors{value2} -o \"{value}\"";
			}
			string value3 = FormatAddressList(_selectedAddresses);
			return $"-d \"{_selectedInterface}\" --devices {value3}{value2} -o \"{value}\"";
		}

		private string BuildCaptureFileName()
		{
			if (_captureMode == UsbCaptureMode.FullInterface)
			{
				string token = GetSelectedFullInterface()?.ShortName ?? "USBPcap";
				return $"{SanitizeFileToken(token)}_FULL_{DateTime.Now:yyyyMMdd_HHmmss}.pcap";
			}
			string token2 = (string.IsNullOrWhiteSpace(_selectedVid) ? "Unknown" : _selectedVid.ToUpperInvariant());
			string token3 = (string.IsNullOrWhiteSpace(_selectedPid) ? "Unknown" : _selectedPid.ToUpperInvariant());
			return $"VID_{SanitizeFileToken(token2)}_PID_{SanitizeFileToken(token3)}_{DateTime.Now:yyyyMMdd_HHmmss}.pcap";
		}

		private static string SanitizeFileToken(string token)
		{
			char[] invalid = System.IO.Path.GetInvalidFileNameChars();
			char[] value = token.Where((char ch) => !invalid.Contains(ch)).ToArray();
			string text = new string(value);
			if (!string.IsNullOrWhiteSpace(text))
			{
				return text;
			}
			return "Unknown";
		}

		private static void TryClearCaptureOutputFile(string path)
		{
			if (string.IsNullOrWhiteSpace(path))
			{
