				{
					File.Delete(path);
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] Clear capture output file failed: " + ex.Message, "TryClearCaptureOutputFile", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2295);
			}
		}

		private async Task WaitForFileReadIdleAsync()
		{
			for (int i = 0; i < 40; i++)
			{
				if (Volatile.Read(in _fileReadInProgress) == 0)
				{
					break;
				}
				await Task.Delay(50);
			}
		}

		private async Task StopCaptureAsync()
		{
			try
			{
				if (_captureProcess != null && !_captureProcess.HasExited)
				{
					Logger.A("[UsbCaptureHelperWindow] Stopping USBPcap capture process: pid=" + GetCaptureProcessIdForLog() + ", output=" + _currentCapturePath, "StopCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2318);
					_captureProcess.Kill();
					await Task.Run(() => _captureProcess.WaitForExit(3000));
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 停止抓包失败: " + ex.Message, "StopCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2325);
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.StopFail.Template", "停止抓包时发生异常：{0}", ex.Message));
			}
			finally
			{
				if (_useFilePollingFallback)
				{
					await ReadAvailableFilePacketsToQueueAsync();
				}
				await StopLiveCaptureSessionAsync();
				FlushPendingPacketRows(forceAll: true);
				StopPacketUiFlushTimer();
				StopCaptureMonitor();
				_captureProcess?.Dispose();
				_captureProcess = null;
				_isCapturing = false;
				_useLivePipeCapture = false;
				_useFilePollingFallback = false;
				CaptureStatusText.Text = L("UsbCaptureHelperWindow.CaptureStatus.Stopped", "当前状态：抓包已停止");
				AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.Stopped", "抓包已停止。"));
				UpdateCaptureButtonState();
			}
			try
			{
				string desktopPath = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
				if (!(await Launcher.LaunchFolderPathAsync(desktopPath)))
				{
					Process.Start(new ProcessStartInfo("explorer.exe", "\"" + desktopPath + "\"")
					{
						UseShellExecute = true
					});
				}
			}
			catch (System.Exception ex2)
			{
				Logger.a("[UsbCaptureHelperWindow] 打开桌面目录失败: " + ex2.Message, "StopCaptureAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2360);
			}
		}

		private async Task<b.x?> TryCreateLiveCaptureSessionAsync()
		{
			if (string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				return null;
			}
			b.x session = null;
			try
			{
				session = new b.x(_currentCapturePath);
				WireLiveCaptureSession(session);
				session.A();
				if (!(await session.a(System.TimeSpan.FromSeconds(2.0))))
				{
					UnwireLiveCaptureSession(session);
					await session.DisposeAsync();
					AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.LivePipeFallbackMessage", "Live pipe is unavailable; falling back to file refresh."));
					return null;
				}
				AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.LivePipeStarted", "Live pipe reader is ready."));
				return session;
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] Start live USBPcap pipe failed: " + ex.Message, "TryCreateLiveCaptureSessionAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2392);
				if (session != null)
				{
					UnwireLiveCaptureSession(session);
					await session.DisposeAsync();
				}
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.LivePipeFallback.Template", "Live pipe unavailable, falling back to file refresh: {0}", ex.Message));
				return null;
			}
		}

		private async Task RestartCaptureWithFilePollingFallbackAsync()
		{
			if (string.IsNullOrWhiteSpace(_currentCapturePath))
			{
				return;
			}
			Logger.a("[UsbCaptureHelperWindow] Live-pipe fallback started: previousPid=" + GetCaptureProcessIdForLog() + ", output=" + _currentCapturePath, "RestartCaptureWithFilePollingFallbackAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2411);
			AppendLiveEvent(L("UsbCaptureHelperWindow.LiveEvent.LivePipeFallbackMessage", "Live pipe did not connect; falling back to file refresh."));
			await StopLiveCaptureSessionAsync();
			try
			{
				if (_captureProcess != null && !_captureProcess.HasExited)
				{
					Logger.A("[UsbCaptureHelperWindow] Stopping live-pipe USBPcap process before file-polling restart: pid=" + GetCaptureProcessIdForLog(), "RestartCaptureWithFilePollingFallbackAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2421);
					_captureProcess.Kill();
					await Task.Run(() => _captureProcess.WaitForExit(2000));
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] Stop pipe capture before fallback failed: " + ex.Message, "RestartCaptureWithFilePollingFallbackAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2428);
			}
			finally
			{
				_captureProcess?.Dispose();
				_captureProcess = null;
			}
			_useLivePipeCapture = false;
			_useFilePollingFallback = true;
			LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.Fallback", "State: live reading fell back to file refresh...");
			string text = BuildCaptureArguments();
			Logger.A($"[UsbCaptureHelperWindow] Starting USBPcap file-polling fallback: exe={_resolvedUsbPcapPath}, output={_currentCapturePath}, arguments={text}", "RestartCaptureWithFilePollingFallbackAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2441);
			ProcessStartInfo startInfo = new ProcessStartInfo
			{
				FileName = _resolvedUsbPcapPath,
				Arguments = text,
				UseShellExecute = true,
				Verb = "runas",
				WindowStyle = ProcessWindowStyle.Minimized
			};
			_captureProcess = Process.Start(startInfo) ?? throw new InvalidOperationException(L("UsbCaptureHelperWindow.Error.CaptureStartFailed", "Unable to start capture process"));
			Logger.A("[UsbCaptureHelperWindow] USBPcap file-polling fallback process started: pid=" + GetCaptureProcessIdForLog() + ", output=" + _currentCapturePath, "RestartCaptureWithFilePollingFallbackAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2453);
			StartCaptureMonitor();
		}

		private async Task StopLiveCaptureSessionAsync()
		{
			b.x session = _liveCaptureSession;
			if (session == null)
			{
				return;
			}
			_liveCaptureSession = null;
			UnwireLiveCaptureSession(session);
			try
			{
				if (await Task.WhenAny(session.Completion, Task.Delay(System.TimeSpan.FromMilliseconds(800.0))) == session.Completion)
				{
					await session.Completion.ConfigureAwait(continueOnCapturedContext: false);
				}
				await session.DisposeAsync();
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] Stop live USBPcap pipe failed: " + ex.Message, "StopLiveCaptureSessionAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2480);
			}
		}

		private void WireLiveCaptureSession(b.x session)
		{
			session.PacketsRead += LiveCaptureSession_PacketsRead;
			session.StatusChanged += LiveCaptureSession_StatusChanged;
			session.Failed += LiveCaptureSession_Failed;
		}

		private void UnwireLiveCaptureSession(b.x session)
		{
			session.PacketsRead -= LiveCaptureSession_PacketsRead;
			session.StatusChanged -= LiveCaptureSession_StatusChanged;
			session.Failed -= LiveCaptureSession_Failed;
		}

		private void LiveCaptureSession_PacketsRead(IReadOnlyList<b.Y> rawPackets)
		{
			if (rawPackets.Count != 0)
			{
				QueueRawPacketsForDisplay(rawPackets);
			}
		}

		private void LiveCaptureSession_StatusChanged(string status)
		{
			base.DispatcherQueue.TryEnqueue(delegate
			{
				if (string.Equals(status, "connected", StringComparison.OrdinalIgnoreCase))
				{
					LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.LivePipe", "State: reading packets in real time...");
				}
				else if (string.Equals(status, "waiting", StringComparison.OrdinalIgnoreCase))
				{
					LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.LivePipeWaiting", "State: waiting for live pipe connection...");
