		private async Task<int> ReadAvailableFilePacketsToQueueAsync()
		{
			if (_pcapReader == null)
			{
				return 0;
			}
			if (Interlocked.Exchange(ref _fileReadInProgress, 1) == 1)
			{
				return 0;
			}
			try
			{
				b.X reader = _pcapReader;
				return await Task.Run(delegate
				{
					IReadOnlyList<b.Y> rawPackets = reader.A();
					return QueueRawPacketsForDisplay(rawPackets);
				});
			}
			catch (b.w w)
			{
				SetPacketReaderError(w.Message);
				return 0;
			}
			catch (System.Exception ex)
			{
				Logger.a("[UsbCaptureHelperWindow] 读取 USBPcap 数据包失败: " + ex.Message, "ReadAvailableFilePacketsToQueueAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2710);
				SetPacketReaderError(ex.Message);
				return 0;
			}
			finally
			{
				Interlocked.Exchange(ref _fileReadInProgress, 0);
			}
		}

		private int QueueRawPacketsForDisplay(IReadOnlyList<b.Y> rawPackets)
		{
			if (rawPackets.Count == 0 || Volatile.Read(in _suppressPacketQueueing) != 0)
			{
				return 0;
			}
			int num = Volatile.Read(in _packetDisplayGeneration);
			int num2 = 0;
			foreach (b.Y rawPacket in rawPackets)
			{
				try
				{
					b.y row = C.A.A(rawPacket);
					if (num == Volatile.Read(in _packetDisplayGeneration) && Volatile.Read(in _suppressPacketQueueing) == 0)
					{
						EnqueuePendingPacketRow(row);
						num2++;
					}
				}
				catch (System.Exception ex)
				{
					Logger.a("[UsbCaptureHelperWindow] Parse USBPcap packet failed: " + ex.Message, "QueueRawPacketsForDisplay", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\Views\\UsbCaptureHelperWindow.xaml.cs", 2745);
				}
			}
			if (num2 > 0)
			{
				Interlocked.Add(ref _totalParsedPacketCount, num2);
				_lastPacketReaderError = null;
			}
			return num2;
		}

		private void EnqueuePendingPacketRow(b.y row)
		{
			_pendingPacketRows.Enqueue(row);
			Interlocked.Increment(ref _pendingPacketRowCount);
			b.y result;
			while (Volatile.Read(in _pendingPacketRowCount) > 10000 && _pendingPacketRows.TryDequeue(out result))
			{
				Interlocked.Decrement(ref _pendingPacketRowCount);
			}
		}

		private void StartPacketUiFlushTimer()
		{
			if (!(_packetUiFlushTimer != null))
			{
				_packetUiFlushTimer = base.DispatcherQueue.CreateTimer();
				_packetUiFlushTimer.Interval = PacketUiFlushInterval;
				_packetUiFlushTimer.IsRepeating = true;
				_packetUiFlushTimer.Tick += PacketUiFlushTimer_Tick;
				_packetUiFlushTimer.Start();
