			{
				_packetUiFlushTimer.Stop();
				_packetUiFlushTimer.Tick -= PacketUiFlushTimer_Tick;
				_packetUiFlushTimer = null;
			}
		}

		private void PacketUiFlushTimer_Tick(Microsoft.UI.Dispatching.DispatcherQueueTimer sender, object args)
		{
			FlushPendingPacketRows(forceAll: false);
			if (!_isCapturing && Volatile.Read(in _pendingPacketRowCount) <= 0)
			{
				StopPacketUiFlushTimer();
			}
		}

		private int FlushPendingPacketRows(bool forceAll)
		{
			int num = (forceAll ? 10000 : 200);
			int num2 = 0;
			bool flag = PacketListView.SelectedItem == null;
			b.y result;
			while (num2 < num && _pendingPacketRows.TryDequeue(out result))
			{
				Interlocked.Decrement(ref _pendingPacketRowCount);
				_allPackets.Add(result);
				num2++;
				if (_packetFilter(result))
				{
					_visiblePackets.Add(result);
				}
			}
			if (num2 <= 0)
			{
				UpdatePacketUiStatus(force: false, 0);
				return 0;
			}
			TrimPacketBuffers();
			_captureActivityCount = Math.Max(Volatile.Read(in _totalParsedPacketCount), _allPackets.Count);
			_lastCaptureActivityAt = System.DateTimeOffset.Now;
			UpdatePacketUiStatus(forceAll, num2);
			if (flag && PacketListView.SelectedItem == null && _visiblePackets.Count > 0)
			{
				Microsoft.UI.Xaml.Controls.ListView packetListView = PacketListView;
				ObservableCollection<b.y> visiblePackets = _visiblePackets;
				packetListView.SelectedItem = visiblePackets[visiblePackets.Count - 1];
			}
			return num2;
		}

		private void UpdatePacketUiStatus(bool force, int flushedCount)
		{
			System.DateTimeOffset now = System.DateTimeOffset.Now;
			if (force || !(now - _lastPacketStatusUiUpdateAt < PacketStatusUpdateInterval))
			{
				_lastPacketStatusUiUpdateAt = now;
				_captureActivityCount = Math.Max(Volatile.Read(in _totalParsedPacketCount), _allPackets.Count);
				int num = Math.Max(Volatile.Read(in _pendingPacketRowCount), 0);
				LiveDataCounterText.Text = LF("UsbCaptureHelperWindow.LiveCount.Template", "Activity count: {0}", _captureActivityCount);
				if (_lastCaptureActivityAt.HasValue)
				{
					LiveDataLastText.Text = LF("UsbCaptureHelperWindow.LiveLast.Template", "Last activity: {0:HH:mm:ss}", _lastCaptureActivityAt.Value.LocalDateTime);
				}
				if (num >= 1000)
				{
					LiveDataStateText.Text = LF("UsbCaptureHelperWindow.LiveState.Backlog.Template", "State: display is catching up... pending {0}", num);
				}
				else if (_useLivePipeCapture && _isCapturing)
				{
					LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.LivePipe", "State: reading packets in real time...");
				}
				else if (_isCapturing)
				{
					LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.Active", "State: receiving packets...");
				}
				RefreshPacketViewerStatus();
				if (flushedCount > 0 && now - _lastPacketEventAt >= PacketEventUpdateInterval)
				{
					_lastPacketEventAt = now;
					AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.UiFlush.Template", "{0:HH:mm:ss} displayed {1} packet(s), pending {2}", now.LocalDateTime, flushedCount, num));
				}
			}
		}

		private void ClearPendingPacketRows()
		{
			b.y result;
			while (_pendingPacketRows.TryDequeue(out result))
			{
			}
			Interlocked.Exchange(ref _pendingPacketRowCount, 0);
		}

		private void SetPacketReaderError(string message)
		{
			if (!string.Equals(_lastPacketReaderError, message, StringComparison.Ordinal))
			{
				_lastPacketReaderError = message;
				LiveDataStateText.Text = L("UsbCaptureHelperWindow.LiveState.Error", "状态：活动监控异常");
				PacketFilterStatusText.Text = LF("UsbCaptureHelperWindow.PacketReader.Error.Template", "抓包解析提示：{0}", message);
				AppendLiveEvent(LF("UsbCaptureHelperWindow.LiveEvent.PacketReadFail.Template", "抓包解析提示：{0}", message));
			}
		}

		private void TrimPacketBuffers()
		{
			while (_allPackets.Count > 10000)
			{
				b.y item = _allPackets[0];
				_allPackets.RemoveAt(0);
				_visiblePackets.Remove(item);
			}
		}

		private void AppendLiveEvent(string message)
		{
			if (!string.IsNullOrWhiteSpace(message))
			{
				_liveEvents.Add(message);
				while (_liveEvents.Count > 200)
				{
					_liveEvents.RemoveAt(0);
				}
			}
		}

		private void SetBusyState(bool isBusy, string statusText)
		{
			bool flag = !string.IsNullOrWhiteSpace(_resolvedUsbPcapPath);
			bool flag2 = _captureMode == UsbCaptureMode.SnapshotDiff;
			bool flag3 = _captureMode == UsbCaptureMode.FullInterface;
			SnapshotModeRadioButton.IsEnabled = !isBusy && !_isCapturing;
			FullInterfaceModeRadioButton.IsEnabled = !isBusy && !_isCapturing;
			ScanSnapshotAButton.IsEnabled = !isBusy && flag && flag2;
			ScanSnapshotBButton.IsEnabled = !isBusy && flag && flag2;
			FullInterfaceComboBox.IsEnabled = !isBusy && !_isCapturing && flag && flag3 && _usbPcapInterfaces.Count > 0;
			RefreshFullInterfacesButton.IsEnabled = !isBusy && !_isCapturing && flag && flag3;
			if (!isBusy)
			{
				UpdateCaptureButtonState();
			}
			else
			{
				CaptureToggleButton.IsEnabled = false;
			}
			if (!string.IsNullOrWhiteSpace(statusText))
			{
				CaptureStatusText.Text = statusText;
			}
		}

		private void UpdateCaptureButtonState()
		{
			if (base.DispatcherQueue != null && !base.DispatcherQueue.HasThreadAccess)
			{
				base.DispatcherQueue.TryEnqueue(UpdateCaptureButtonState);
				return;
			}
			bool flag = !string.IsNullOrWhiteSpace(_resolvedUsbPcapPath);
			bool flag2 = _captureMode == UsbCaptureMode.SnapshotDiff;
			bool flag3 = _captureMode == UsbCaptureMode.FullInterface;
			SnapshotModeRadioButton.IsEnabled = !_isCapturing;
			FullInterfaceModeRadioButton.IsEnabled = !_isCapturing;
			ScanSnapshotAButton.IsEnabled = !_isCapturing && flag && flag2;
			ScanSnapshotBButton.IsEnabled = !_isCapturing && flag && flag2;
			FullInterfaceComboBox.IsEnabled = !_isCapturing && flag && flag3 && _usbPcapInterfaces.Count > 0;
			RefreshFullInterfacesButton.IsEnabled = !_isCapturing && flag && flag3;
			if (_isCapturing)
			{
				CaptureToggleButton.IsEnabled = true;
				SetCaptureButtonText(L("UsbCaptureHelperWindow.CaptureButton.Stop", "Stop capture and open desktop"));
			}
			else
			{
				bool isEnabled = flag && ((_captureMode == UsbCaptureMode.FullInterface) ? (GetSelectedFullInterface() != null) : (!string.IsNullOrWhiteSpace(_selectedInterface) && _selectedAddresses.Count > 0));
				CaptureToggleButton.IsEnabled = isEnabled;
				SetCaptureButtonText(L("UsbCaptureHelperWindow.CaptureButton.Start", "Start capture"));
			}
		}

		private void SetCaptureButtonText(string text)
		{
			CaptureToggleButtonText.Text = text;
			CaptureToggleButtonText.UpdateLayout();
			CaptureToggleButton.UpdateLayout();
		}

		private bool EnsureUsbPcapReady()
		{
			if (!string.IsNullOrWhiteSpace(_resolvedUsbPcapPath))
			{
				return true;
			}
			ShowInfoDialogAsync(L("UsbCaptureHelperWindow.Dialog.EnvNotReady.Title", "环境未就绪"), L("UsbCaptureHelperWindow.Dialog.EnvNotReady.Content", "未检测到 USBPcapCmd.exe，请先安装 USBPcap。\n\n你可以点击“下载并安装 USBPcap”。"));
			return false;
		}

