		public async Task RefreshAsync()
		{
			int requestId = Interlocked.Increment(ref _refreshRequestId);
			DeviceModel deviceSnapshot = Device;
			int selectedRangeIndex = SelectedRangeIndex;
			System.DateTimeOffset? customFrom = ((CustomFromTicks > 0) ? new System.DateTimeOffset?(new System.DateTimeOffset(DateTime.FromBinary(CustomFromTicks))) : ((System.DateTimeOffset?)null));
			System.DateTimeOffset? customTo = ((CustomToTicks > 0) ? new System.DateTimeOffset?(new System.DateTimeOffset(DateTime.FromBinary(CustomToTicks))) : ((System.DateTimeOffset?)null));
