					DischargeRateDisplay = L("DeviceDetailsWindow.Value.Restricted");
					RateArrow = "";
					RateArrowBrush = new SolidColorBrush(Colors.Transparent);
					StatusDisplay = L("DeviceDetailsWindow.Value.Restricted");
					LastFullDisplay = L("DeviceDetailsWindow.Value.Restricted");
					AverageTrendDisplay = L("DeviceDetailsWindow.Value.Restricted");
					CurrentStateDisplay = L("DeviceDetailsWindow.Value.Restricted");
					LastChangeDisplay = L("DeviceDetailsWindow.Value.Restricted");
