		private static (System.DateTimeOffset from, System.DateTimeOffset? to) GetRangeByIndex(int index, System.DateTimeOffset? customFrom, System.DateTimeOffset? customTo)
		{
			System.DateTimeOffset now = System.DateTimeOffset.Now;
			return index switch
			{
				0 => (from: now.AddHours(-1.0), to: now), 
				1 => (from: now.AddHours(-6.0), to: now), 
				2 => (from: now.AddHours(-24.0), to: now), 
				3 => (from: now.AddDays(-7.0), to: now), 
				4 => (from: customFrom ?? now.AddHours(-24.0), to: customTo), 
				_ => (from: now.AddHours(-24.0), to: now), 
			};
		}

		private void UpdateCards(IReadOnlyList<BatteryHistorySample> samples)
		{
			System.DateTimeOffset now = System.DateTimeOffset.Now;
			System.DateTimeOffset from = now - PredictionWindow;
			List<BatteryHistorySample> windowSamples = (from s in samples
				where s.Timestamp >= @from && s.Timestamp <= now
				orderby s.Timestamp
				select s).ToList();
			if (B.i.IsVip)
			{
				UpdateStatusCard(samples);
				UpdateRateCard(windowSamples);
				UpdateEstimatedRemaining(windowSamples);
				UpdateTrendInfo(windowSamples);
			}
			else
			{
				UpdateStatusCardForNonVip();
				UpdateRateCardForNonVip();
				UpdateEstimatedRemainingForNonVip();
				UpdateTrendInfoForNonVip();
			}
		}

		private void UpdateStatusCard(IReadOnlyList<BatteryHistorySample> allSamples)
		{
			bool flag = (Device.ConnectionStatus ?? string.Empty).Contains("CONNECTED", StringComparison.OrdinalIgnoreCase);
			if (allSamples.Count > 0)
			{
				int num;
				if (flag)
				{
					num = (allSamples[allSamples.Count - 1].IsConnected ? 1 : 0);
				}
				else
				{
					num = 0;
				}
				flag = (byte)num != 0;
			}
			if (!flag)
			{
				StatusDisplay = L("DeviceDetailsWindow.Status.NotConnected");
			}
			else
			{
				List<BatteryHistorySample> list = allSamples.OrderBy((BatteryHistorySample s) => s.Timestamp).ToList();
				if (list.Count >= 2)
				{
					int batteryLevel = list[list.Count - 2].BatteryLevel;
					int batteryLevel2 = list[list.Count - 1].BatteryLevel;
					StatusDisplay = ((batteryLevel2 > batteryLevel) ? L("DeviceDetailsWindow.Status.Charging") : L("DeviceDetailsWindow.Status.Discharging"));
				}
				else
				{
					StatusDisplay = L("DeviceDetailsWindow.Status.Unknown");
				}
			}
			System.DateTimeOffset? dateTimeOffset = null;
			List<BatteryHistorySample> list2 = allSamples.OrderBy((BatteryHistorySample s) => s.Timestamp).ToList();
			for (int num2 = 0; num2 < list2.Count; num2++)
			{
				if (list2[num2].BatteryLevel >= 99 && (num2 == 0 || list2[num2 - 1].BatteryLevel < 99))
				{
					dateTimeOffset = list2[num2].Timestamp;
				}
			}
			LastFullDisplay = (dateTimeOffset.HasValue ? F("DeviceDetailsWindow.LastFull.Template", dateTimeOffset.Value.ToLocalTime().ToString("MM-dd HH:mm")) : L("DeviceDetailsWindow.LastFull.Unknown"));
		}

		private void UpdateRateCard(IReadOnlyList<BatteryHistorySample> windowSamples)
		{
			if (windowSamples.Count < 2)
			{
				DischargeRateDisplay = L("DeviceDetailsWindow.DischargeRate.Unknown");
				RateArrow = "";
				RateArrowBrush = new SolidColorBrush(Colors.Transparent);
				return;
			}
			double num = 0.0;
			double num2 = 0.0;
			for (int i = 1; i < windowSamples.Count; i++)
			{
				BatteryHistorySample batteryHistorySample = windowSamples[i - 1];
				BatteryHistorySample batteryHistorySample2 = windowSamples[i];
				if (!batteryHistorySample.IsConnected || !batteryHistorySample2.IsConnected)
				{
					continue;
				}
				System.TimeSpan timeSpan = batteryHistorySample2.Timestamp - batteryHistorySample.Timestamp;
				if (!(timeSpan <= System.TimeSpan.Zero))
				{
					int num3 = batteryHistorySample2.BatteryLevel - batteryHistorySample.BatteryLevel;
					if (num3 < 0)
					{
						num += (double)(-num3);
						num2 += timeSpan.TotalHours;
					}
				}
			}
			if (num2 <= 1E-06 || num <= 0.0)
			{
				DischargeRateDisplay = L("DeviceDetailsWindow.DischargeRate.Unknown");
			}
			else
			{
				double num4 = num / num2;
				DischargeRateDisplay = F("DeviceDetailsWindow.DischargeRate.Template", num4.ToString("F2"));
			}
			int num5 = windowSamples[windowSamples.Count - 1].BatteryLevel - windowSamples[windowSamples.Count - 2].BatteryLevel;
			if (num5 > 0)
			{
				RateArrow = "▲";
				RateArrowBrush = new SolidColorBrush(Colors.LimeGreen);
			}
			else
			{
				RateArrow = "▼";
				RateArrowBrush = new SolidColorBrush(Colors.IndianRed);
			}
		}

		private void UpdateEstimatedRemaining(IReadOnlyList<BatteryHistorySample> windowSamples)
		{
			if (windowSamples.Count < 2)
			{
				EstimatedRemainingDisplay = "--";
				return;
			}
			string text = _device.Name ?? "Unknown";
			B.U result = _predictionService.A(text, _device.DeviceId, System.TimeSpan.FromHours(6.0)).GetAwaiter().GetResult();
			if (!result.IsAvailable)
			{
				EstimatedRemainingDisplay = "--";
				return;
			}
			double totalHours = result.RemainingTime.TotalHours;
			bool isHistorical = result.Status == "基于历史";
			EstimatedRemainingDisplay = FormatRemainingTime(totalHours, isHistorical);
		}

		private static string FormatRemainingTime(double totalHours, bool isHistorical = false)
		{
			string text;
			if (totalHours < 1.0)
			{
				int num = Math.Max(1, (int)Math.Round(totalHours * 60.0));
				text = F("DeviceDetailsWindow.RemainingTime.Minutes", num);
			}
			else if (totalHours < 24.0)
			{
				int num2 = (int)totalHours;
				int num3 = (int)((totalHours - (double)num2) * 60.0);
				text = ((num3 > 0) ? F("DeviceDetailsWindow.RemainingTime.HoursMinutes", num2, num3) : F("DeviceDetailsWindow.RemainingTime.Hours", num2));
			}
			else
			{
				int num4 = (int)(totalHours / 24.0);
				double num5 = totalHours - (double)(num4 * 24);
				text = ((num5 > 0.1) ? F("DeviceDetailsWindow.RemainingTime.DaysHours", num4, num5.ToString("F1")) : F("DeviceDetailsWindow.RemainingTime.Days", num4));
			}
			if (!isHistorical)
			{
				return text;
			}
			return F("DeviceDetailsWindow.RemainingTime.Historical", text);
		}

		private void UpdateTrendInfo(IReadOnlyList<BatteryHistorySample> windowSamples)
		{
			if (windowSamples.Count < 2)
			{
				AverageTrendDisplay = "-";
				CurrentStateDisplay = "-";
				LastChangeDisplay = "-";
				return;
			}
			string text = _device.Name ?? "Unknown";
			B.U result = _predictionService.A(text, _device.DeviceId, System.TimeSpan.FromHours(6.0)).GetAwaiter().GetResult();
			if (result.IsAvailable)
			{
				double totalHours = result.RemainingTime.TotalHours;
				bool isHistorical = result.Status == "基于历史";
				AverageTrendDisplay = FormatRemainingTime(totalHours, isHistorical);
			}
			else
			{
				AverageTrendDisplay = "--";
			}
			CurrentStateDisplay = "-";
			System.DateTimeOffset? dateTimeOffset = null;
			for (int num = windowSamples.Count - 2; num > 0; num--)
			{
				int num2 = windowSamples[num].BatteryLevel - windowSamples[num - 1].BatteryLevel;
				int num3 = windowSamples[num + 1].BatteryLevel - windowSamples[num].BatteryLevel;
				if ((num2 > 0 && num3 <= 0) || (num2 <= 0 && num3 > 0))
				{
					dateTimeOffset = windowSamples[num].Timestamp;
					break;
				}
			}
			if (dateTimeOffset.HasValue)
			{
				System.TimeSpan timeSpan = System.DateTimeOffset.Now - dateTimeOffset.Value;
				if (timeSpan.TotalMinutes < 60.0)
				{
					LastChangeDisplay = F("DeviceDetailsWindow.LastChange.MinutesAgo", timeSpan.TotalMinutes.ToString("F0"));
				}
				else if (timeSpan.TotalHours < 24.0)
				{
					LastChangeDisplay = F("DeviceDetailsWindow.LastChange.HoursAgo", timeSpan.TotalHours.ToString("F1"));
				}
				else
				{
					LastChangeDisplay = F("DeviceDetailsWindow.LastChange.DaysAgo", timeSpan.TotalDays.ToString("F0"));
				}
			}
			else
			{
				LastChangeDisplay = L("DeviceDetailsWindow.LastChange.None");
			}
		}

		private void UpdateStatusCardForNonVip()
		{
			StatusDisplay = L("DeviceDetailsWindow.Value.MemberOnly");
			LastFullDisplay = "-";
		}

		private void UpdateRateCardForNonVip()
		{
			DischargeRateDisplay = L("DeviceDetailsWindow.Value.MemberOnly");
			RateArrow = "";
			RateArrowBrush = new SolidColorBrush(Colors.Transparent);
		}

		private void UpdateEstimatedRemainingForNonVip()
		{
			EstimatedRemainingDisplay = L("DeviceDetailsWindow.Value.MemberOnly");
		}

		private void UpdateTrendInfoForNonVip()
		{
			AverageTrendDisplay = L("DeviceDetailsWindow.Value.MemberOnly");
			CurrentStateDisplay = L("DeviceDetailsWindow.Value.MemberOnly");
			LastChangeDisplay = "-";
		}
	}
