				{
					return null;
				}
				IReadOnlyList<BluetoothAnnouncement> effectiveAnnouncements = FilterAnnouncementsForCurrentChannel(_announcementService.A());
				HashSet<long> effectiveReadIds = _announcementService.a();
				ApplyAnnouncementsOnUiThread(effectiveAnnouncements, effectiveReadIds);
				IReadOnlyList<BluetoothAnnouncement> readOnlyList = await _announcementService.A(cancellationToken).ConfigureAwait(continueOnCapturedContext: true);
				if (readOnlyList != null)
				{
					effectiveAnnouncements = FilterAnnouncementsForCurrentChannel(readOnlyList);
					effectiveReadIds = _announcementService.a();
					ApplyAnnouncementsOnUiThread(effectiveAnnouncements, effectiveReadIds);
				}
				return new AnnouncementRefreshSnapshot(effectiveAnnouncements, effectiveReadIds);
			}
			catch (System.Exception ex)
			{
				Logger.a("刷新公告失败（已忽略）：" + ex.Message, "RefreshAnnouncementsCoreAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 312);
