		private void ApplyAnnouncementsOnUiThread(IReadOnlyList<BluetoothAnnouncement> list, HashSet<long> readIds)
		{
			Microsoft.UI.Dispatching.DispatcherQueue dispatcherQueue = App.MainWindow?.DispatcherQueue ?? _uiQueue;
			if (dispatcherQueue != null && Microsoft.UI.Dispatching.DispatcherQueue.GetForCurrentThread() != dispatcherQueue)
			{
				dispatcherQueue.TryEnqueue(delegate
				{
					ApplyAnnouncements(list, readIds);
				});
			}
			else
			{
				ApplyAnnouncements(list, readIds);
			}
		}

		private void ApplyAnnouncements(IReadOnlyList<BluetoothAnnouncement> list, HashSet<long> readIds)
		{
			bool preferChinese = F.g.B();
			List<AnnouncementItemViewModel> list2 = (from a in list ?? Array.Empty<BluetoothAnnouncement>()
				where a != null && a.Id > 0
				orderby a.PublishTime ?? System.DateTimeOffset.MinValue descending, a.Id descending
				select new AnnouncementItemViewModel
				{
					Id = a.Id,
					Title = a.GetDisplayTitle(preferChinese),
					Content = a.GetDisplayContent(preferChinese),
					LinkUrl = a.GetDisplayLinkUrl(preferChinese),
					PublishTimeText = (a.PublishTime.HasValue ? a.PublishTime.Value.ToLocalTime().ToString("yyyy-MM-dd HH:mm") : string.Empty),
					LevelTagText = (a.IsImportant ? F.g.a("重要") : string.Empty),
					IsImportant = a.IsImportant,
					IsRead = readIds.Contains(a.Id)
				}).ToList();
			Announcements = new ObservableCollection<AnnouncementItemViewModel>(list2);
			HasUnreadAnnouncements = list2.Any((AnnouncementItemViewModel x) => !x.IsRead);
			HasUnreadImportantAnnouncements = list2.Any((AnnouncementItemViewModel x) => !x.IsRead && x.IsImportant);
		}

