		public void SyncWindowsBatteryFromSettings()
		{
			b.U instance = b.U.Instance;
			if (!B.I.ShowWindowsBattery)
			{
				instance.c();
				RemoveDeviceById("WINDOWS_BATTERY_PC");
				return;
			}
			b.U.a snapshot = instance.B();
			if (!snapshot.IsAvailable)
			{
				Logger.A("[WindowsBattery] 系统没有可用的电池，跳过添加 Windows 电池设备", "SyncWindowsBatteryFromSettings", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 507);
				instance.c();
				RemoveDeviceById("WINDOWS_BATTERY_PC");
				return;
			}
			instance.C();
			DeviceModel deviceModel = FindByDeviceId("WINDOWS_BATTERY_PC");
			if (deviceModel == null)
			{
				deviceModel = new DeviceModel
				{
					Name = "Windows",
					DeviceId = "WINDOWS_BATTERY_PC",
					ConnectionStatus = snapshot.ConnectionStatus,
					BatteryLevel = snapshot.BatteryLevel,
					LastUpdated = DateTime.Now,
					BatteryLastUpdated = DateTime.Now,
					CommunicationLastUpdated = DateTime.Now,
					IsAlternateStyle = (Devices.Count % 2 != 0),
					Source = DeviceSource.WindowsBattery,
					IsBatteryUnsupported = false,
					IsBatteryRead = true,
					ChargingState = ((!snapshot.IsCharging) ? ChargingState.NotCharging : ChargingState.Charging)
				};
				ApplyPersistedWindowsBatteryPresentation(deviceModel);
				Devices.Add(deviceModel);
				LogBatteryUpdate(deviceModel.Source, $"[WindowsBattery] 已添加 Windows 电池设备，电量: {deviceModel.BatteryLevel}%");
			}
			else
			{
				deviceModel.Source = DeviceSource.WindowsBattery;
				deviceModel.ConnectionStatus = snapshot.ConnectionStatus;
				deviceModel.LastUpdated = DateTime.Now;
				deviceModel.BatteryLastUpdated = DateTime.Now;
				deviceModel.CommunicationLastUpdated = DateTime.Now;
				deviceModel.IsBatteryUnsupported = false;
				deviceModel.IsBatteryRead = true;
				deviceModel.BatteryLevel = snapshot.BatteryLevel;
				deviceModel.ChargingState = ((!snapshot.IsCharging) ? ChargingState.NotCharging : ChargingState.Charging);
				ApplyPersistedWindowsBatteryPresentation(deviceModel);
			}
			QueueWindowsBatteryHistorySample(snapshot);
			HasDevices = Devices.Count > 0;
			EmptyStateVisibility = (HasDevices ? Visibility.Collapsed : Visibility.Visible);
			UpdateTrayToolTip();
			RefreshTrayIconFromDevices();
		}

		private void UpdateWindowsBatteryDevice(int batteryLevel)
		{
			b.U.a snapshot = b.U.Instance.B();
			if (!snapshot.IsAvailable)
			{
				Logger.A("[WindowsBattery] 当前无可用电池，已移除 Windows 电池设备", "UpdateWindowsBatteryDevice", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 567);
				RemoveDeviceById("WINDOWS_BATTERY_PC");
				return;
			}
			DeviceModel deviceModel = FindByDeviceId("WINDOWS_BATTERY_PC");
			if (deviceModel != null)
			{
				deviceModel.BatteryLevel = snapshot.BatteryLevel;
				deviceModel.ConnectionStatus = snapshot.ConnectionStatus;
				deviceModel.ChargingState = ((!snapshot.IsCharging) ? ChargingState.NotCharging : ChargingState.Charging);
				deviceModel.LastUpdated = DateTime.Now;
				deviceModel.BatteryLastUpdated = DateTime.Now;
				deviceModel.CommunicationLastUpdated = DateTime.Now;
				ApplyPersistedWindowsBatteryPresentation(deviceModel);
				QueueWindowsBatteryHistorySample(snapshot);
				Logger.A($"[WindowsBattery] 电量已更新: {snapshot.BatteryLevel}%", "UpdateWindowsBatteryDevice", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 583);
