		public void MigrateDeviceIdentity(string? oldDeviceId, string? newDeviceId, DeviceSource source, string? confirmedName = null)
		{
			if (string.IsNullOrWhiteSpace(oldDeviceId) || string.IsNullOrWhiteSpace(newDeviceId) || string.Equals(oldDeviceId, newDeviceId, StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			DeviceModel deviceModel = FindByDeviceId(oldDeviceId) ?? FindHiddenByDeviceId(oldDeviceId);
			if (deviceModel == null)
			{
				return;
			}
			DeviceModel deviceModel2 = FindByDeviceId(newDeviceId) ?? FindHiddenByDeviceId(newDeviceId);
			if (deviceModel2 != null && deviceModel2 != deviceModel)
			{
				if (IsPrivateBluetoothSource(source))
				{
					string text = ResolveUserConfigKey(confirmedName ?? deviceModel2.Name, newDeviceId, source);
					B.I.D(text, from k in new string[2] { deviceModel.UserConfigKey, oldDeviceId }
						where !string.IsNullOrWhiteSpace(k)
						select (k));
					DeviceModel deviceModel3 = deviceModel2;
					if (deviceModel3.CustomName == null)
					{
						string text2 = (deviceModel3.CustomName = deviceModel.CustomName);
					}
					deviceModel3 = deviceModel2;
					if (deviceModel3.IconConfig == null)
					{
						DeviceIconModel deviceIconModel = (deviceModel3.IconConfig = deviceModel.IconConfig);
					}
					deviceModel2.Source = source;
					if (HiddenDevices.Contains(deviceModel) && Devices.Remove(deviceModel2))
					{
						HiddenDevices.Add(deviceModel2);
					}
				}
				Devices.Remove(deviceModel);
				HiddenDevices.Remove(deviceModel);
				Logger.A($"[Device] 身份迁移合并已有条目: OldDeviceId='{oldDeviceId}', NewDeviceId='{newDeviceId}', Source={source}", "MigrateDeviceIdentity", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 850);
			}
			else
			{
				string name = (string.IsNullOrWhiteSpace(confirmedName) ? (deviceModel.Name ?? string.Empty) : confirmedName);
				string text3 = ResolveUserConfigKey(name, newDeviceId, source);
				string[] array = ResolvePresentationMigrationKeys(text3, newDeviceId, name, source);
				if (IsPrivateBluetoothSource(source))
				{
					array = (from k in array.Concat(new string[2] { deviceModel.UserConfigKey, oldDeviceId })
						where !string.IsNullOrWhiteSpace(k)
						select (k)).Distinct<string>(StringComparer.OrdinalIgnoreCase).ToArray();
				}
				B.I.D(text3, array);
				deviceModel.Name = name;
				deviceModel.DeviceId = newDeviceId;
				deviceModel.UserConfigKey = text3;
				deviceModel.Source = source;
				deviceModel.IsPlaceholder = false;
				ApplyPersistedPresentation(deviceModel, name, newDeviceId, source);
				DeviceOrderService.a(deviceModel);
				Logger.A($"[Device] 身份原地迁移: OldDeviceId='{oldDeviceId}', NewDeviceId='{newDeviceId}', Name='{deviceModel.Name}', DisplayName='{deviceModel.DisplayName}', Source={source}", "MigrateDeviceIdentity", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 871);
			}
			Apply24GTrialBatteryRestriction();
			HasDevices = Devices.Count > 0;
			EmptyStateVisibility = (HasDevices ? Visibility.Collapsed : Visibility.Visible);
			UpdateTrayToolTip();
			RefreshTrayIconFromDevices();
		}

