				int num = Devices.Count((DeviceModel device) => !device.IsPlaceholder);
				string text = $"{B.I.TrayDisplayMode}|{traySelectionResult.Device?.DeviceKey}|{traySelectionResult.Reason}";
				DateTime utcNow = DateTime.UtcNow;
				if (_lastTrayIconValue != traySelectionResult.BatteryValue || _lastTrayIconDeviceCount != num || !string.Equals(_lastTraySelectedDeviceId, text, StringComparison.Ordinal) || !(utcNow - _lastTrayIconAppliedAtUtc < TrayIconSameStateThrottle))
				{
					_lastTrayIconAppliedAtUtc = utcNow;
					_lastTrayIconValue = traySelectionResult.BatteryValue;
					_lastTrayIconDeviceCount = num;
					_lastTraySelectedDeviceId = text;
					this.RequestTrayIconUpdate?.Invoke(traySelectionResult.BatteryValue);
					Logger.b($"[托盘] 图标更新触发：mode={B.I.TrayDisplayMode}, reason={traySelectionResult.Reason}, device={traySelectionResult.Device?.DisplayName ?? "<none>"}, trayValue={traySelectionResult.BatteryValue}", "RefreshTrayIconFromDevices", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 918);
				}
			}
			catch (System.Exception ex)
			{
