		private IEnumerable<TraySelectionCandidate> BuildTraySelectionCandidates()
		{
			return Devices.Select(delegate(DeviceModel device)
			{
				string userConfigKey = GetUserConfigKey(device);
				bool isHidden = B.I.c(userConfigKey) || (!string.IsNullOrWhiteSpace(device.DeviceId) && B.I.c(device.DeviceId));
				return new TraySelectionCandidate
				{
					DeviceKey = userConfigKey,
					AlternateKey = (device.DeviceId ?? string.Empty),
					DisplayName = device.DisplayName,
					BatteryLevel = device.BatteryLevel,
					IsConnected = IsTrayDeviceConnected(device),
					IsHidden = isHidden,
					IsPlaceholder = device.IsPlaceholder,
					IsBatteryRestricted = device.IsBatteryRestricted
				};
			});
		}

		private static bool IsTrayDeviceConnected(DeviceModel device)
		{
			if (device.IsSleeping)
			{
				return true;
			}
			string text = device.ConnectionStatus ?? string.Empty;
			if (!text.Contains("DISCONNECTED", StringComparison.OrdinalIgnoreCase))
			{
				return !text.Contains("OFFLINE", StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		private void UpdateTrayToolTip()
		{
			try
			{
				List<DeviceModel> list = Devices.Where((DeviceModel device) => !device.IsPlaceholder).ToList();
				if (list.Count == 0)
				{
					TrayToolTip = "EasyBluetooth\n无设备";
					return;
				}
				string themeSymbol = GetThemeSymbol();
				StringBuilder stringBuilder = new StringBuilder();
				TryAppendLineWithLimit(stringBuilder, "EasyBluetooth", 120);
				int num = 8;
				int num2 = 0;
				foreach (DeviceModel item in list)
				{
					if (num2 >= num)
					{
						break;
					}
					string text = item.BatteryDisplayText;
					if (item.ShowPercentSign)
					{
						text += "%";
					}
					string text2 = ((!string.IsNullOrEmpty(item.DisplayName)) ? item.DisplayName : "未知设备");
					string value = TruncateWithEllipsis(text2, 22);
					string line = $"{themeSymbol} {value}: {text}";
					if (!TryAppendLineWithLimit(stringBuilder, line, 120))
					{
						int num3 = list.Count - num2;
						if (num3 > 0)
						{
							string line2 = $"... 及其他 {num3} 个设备";
							TryAppendLineWithLimit(stringBuilder, line2, 120);
						}
						break;
					}
					num2++;
				}
				if (list.Count > num)
				{
					string line3 = $"... 及其他 {list.Count - num} 个设备";
					TryAppendLineWithLimit(stringBuilder, line3, 120);
				}
				TrayToolTip = stringBuilder.ToString();
			}
			catch (System.Exception ex)
			{
				Logger.a("更新托盘工具提示失败: " + ex.Message, "UpdateTrayToolTip", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 1094);
				TrayToolTip = ((Devices.Count > 0) ? $"EasyBluetooth: {Devices.Count} 个设备已连接" : "EasyBluetooth: 无设备");
			}
			static string TruncateWithEllipsis(string text3, int maxChars)
			{
				if (string.IsNullOrEmpty(text3))
				{
					return string.Empty;
				}
				if (maxChars <= 0)
				{
					return string.Empty;
				}
				if (text3.Length <= maxChars)
				{
					return text3;
				}
				if (maxChars == 1)
				{
					return "…";
				}
				return text3.Substring(0, maxChars - 1) + "…";
			}
			static bool TryAppendLineWithLimit(StringBuilder sb, string text3, int limit)
			{
				int num4 = ((sb.Length != 0) ? "\n".Length : 0) + text3.Length;
				if (sb.Length + num4 > limit)
				{
					return false;
				}
				if (sb.Length > 0)
				{
					sb.Append("\n");
				}
				sb.Append(text3);
				return true;
			}
		}

		private string GetThemeSymbol()
