		private static string? ExtractBluetoothRemoteAddress(string? deviceId)
		{
			if (string.IsNullOrWhiteSpace(deviceId))
			{
				return null;
			}
			string result = null;
			for (int i = 0; i <= deviceId.Length - 17; i++)
			{
				if (IsBluetoothAddressAt(deviceId, i))
				{
					result = NormalizeBluetoothAddress(deviceId, i);
				}
			}
			return result;
		}

		private static bool IsBluetoothAddressAt(string value, int start)
		{
			for (int i = 0; i < 17; i++)
			{
				char c = value[start + i];
				if ((i + 1) % 3 == 0)
				{
					if (c != ':')
					{
						return false;
					}
				}
				else if (!System.Uri.IsHexDigit(c))
				{
					return false;
				}
			}
			return true;
		}

		private static string NormalizeBluetoothAddress(string value, int start)
		{
			Span<char> span = stackalloc char[12];
			int num = 0;
			for (int i = 0; i < 17; i++)
			{
				char c = value[start + i];
				if (c != ':')
				{
					span[num++] = char.ToLowerInvariant(c);
				}
			}
			return new string(span);
		}

		private static bool IsClassicBlePair(DeviceSource first, DeviceSource second)
		{
			if (first != DeviceSource.Classic || second != DeviceSource.Ble)
			{
				if (first == DeviceSource.Ble)
				{
					return second == DeviceSource.Classic;
				}
				return false;
			}
			return true;
		}

