		private DeviceModel? FindEquivalentBluetoothDevice(string name, string? deviceId, DeviceSource source)
		{
			if (!IsBluetoothUiSource(source))
			{
				return null;
			}
			string incomingAddress = ExtractBluetoothRemoteAddress(deviceId);
			if (!string.IsNullOrEmpty(incomingAddress))
			{
				List<DeviceModel> list = Devices.Where((DeviceModel d) => IsBluetoothUiSource(d.Source) && !string.Equals(d.DeviceId, deviceId, StringComparison.OrdinalIgnoreCase) && string.Equals(ExtractBluetoothRemoteAddress(d.DeviceId), incomingAddress, StringComparison.OrdinalIgnoreCase)).ToList();
				if (list.Count == 1)
				{
					return list[0];
				}
				string normalizedNameForAddress = NormalizeBluetoothDuplicateName(name);
				List<DeviceModel> list2 = list.Where((DeviceModel d) => string.Equals(NormalizeBluetoothDuplicateName(d.Name), normalizedNameForAddress, StringComparison.OrdinalIgnoreCase)).ToList();
				if (list2.Count == 1)
				{
					return list2[0];
				}
				if (list.Count > 0)
				{
					return null;
				}
				if (source == DeviceSource.Ble)
				{
					DeviceModel deviceModel = FindSingleClassicBleNameMatch(name, deviceId, source);
					if (deviceModel != null)
					{
						Logger.a($"[FindOrCreateDevice][Bluetooth][PreferBle] BLE 按同名合并 Classic 条目：Name='{name}', ClassicDeviceId='{deviceModel.DeviceId}', BleDeviceId='{deviceId}'", "FindEquivalentBluetoothDevice", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 1406);
						return deviceModel;
					}
				}
				string normalizedName = NormalizeBluetoothDuplicateName(name);
				if (string.IsNullOrEmpty(normalizedName))
				{
					return null;
				}
				List<DeviceModel> list3 = Devices.Where((DeviceModel d) => IsBluetoothUiSource(d.Source) && !string.Equals(d.DeviceId, deviceId, StringComparison.OrdinalIgnoreCase) && string.Equals(NormalizeBluetoothDuplicateName(d.Name), normalizedName, StringComparison.OrdinalIgnoreCase) && string.IsNullOrEmpty(ExtractBluetoothRemoteAddress(d.DeviceId))).ToList();
				if (list3.Count != 1)
				{
					return null;
				}
				return list3[0];
			}
			return null;
		}

		private void RemoveDuplicateBluetoothEntries(DeviceModel keepDevice)
		{
			if (!IsBluetoothUiSource(keepDevice.Source))
			{
				return;
			}
			string text = NormalizeBluetoothDuplicateName(keepDevice.Name);
			string text2 = ExtractBluetoothRemoteAddress(keepDevice.DeviceId);
			int num = 0;
			for (int num2 = Devices.Count - 1; num2 >= 0; num2--)
			{
				DeviceModel deviceModel = Devices[num2];
				if (deviceModel == keepDevice || !IsBluetoothUiSource(deviceModel.Source))
				{
					continue;
				}
				bool flag = !string.IsNullOrEmpty(keepDevice.DeviceId) && string.Equals(deviceModel.DeviceId, keepDevice.DeviceId, StringComparison.OrdinalIgnoreCase);
