		private static bool IsLikelyPlayStationControllerName(string? name)
		{
			if (string.IsNullOrWhiteSpace(name))
			{
				return false;
			}
			string text = name.Trim();
			if (text.IndexOf("DualSense", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("DualShock", StringComparison.OrdinalIgnoreCase) < 0 && text.IndexOf("PlayStation", StringComparison.OrdinalIgnoreCase) < 0)
			{
				return string.Equals(text, "Wireless Controller", StringComparison.OrdinalIgnoreCase);
			}
			return true;
		}

		private DeviceModel? FindEquivalentPlayStationDevice(string name, string? deviceId)
		{
			if (!IsLikelyPlayStationControllerName(name))
			{
				return null;
			}
			string normalizedName = NormalizeDuplicateControllerName(name);
			List<DeviceModel> list = Devices.Where((DeviceModel d) => (d.Source == DeviceSource.PlayStation || d.Source == DeviceSource.Sony || d.Source == DeviceSource.Classic) && string.Equals(NormalizeDuplicateControllerName(d.Name), normalizedName, StringComparison.OrdinalIgnoreCase)).ToList();
			if (!string.IsNullOrEmpty(deviceId))
			{
				DeviceModel deviceModel = list.FirstOrDefault((DeviceModel d) => string.Equals(d.DeviceId, deviceId, StringComparison.OrdinalIgnoreCase));
				if (deviceModel != null)
				{
					return deviceModel;
				}
			}
			List<DeviceModel> list2 = list.Where((DeviceModel d) => d.Source == DeviceSource.Sony).ToList();
			if (list2.Count == 1)
			{
				return list2[0];
			}
			List<DeviceModel> list3 = list.Where((DeviceModel d) => d.Source == DeviceSource.PlayStation).ToList();
			if (list3.Count == 1)
			{
				return list3[0];
			}
			if (list.Count == 1)
			{
				return list[0];
			}
			return null;
		}

		private void RemoveLikelyPlayStationDuplicateEntries(DeviceModel keepDevice)
		{
			if (!IsLikelyPlayStationControllerName(keepDevice.Name))
			{
				return;
			}
			string b = NormalizeDuplicateControllerName(keepDevice.Name);
			for (int num = Devices.Count - 1; num >= 0; num--)
			{
				DeviceModel deviceModel = Devices[num];
				if (deviceModel != keepDevice && (deviceModel.Source == DeviceSource.PlayStation || deviceModel.Source == DeviceSource.Sony || deviceModel.Source == DeviceSource.Classic) && string.Equals(NormalizeDuplicateControllerName(deviceModel.Name), b, StringComparison.OrdinalIgnoreCase))
				{
					Logger.a($"[Dedup][PlayStation] 移除重复设备：Name='{deviceModel.Name}', DeviceId='{deviceModel.DeviceId}', Source={deviceModel.Source}", "RemoveLikelyPlayStationDuplicateEntries", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 1581);
					Devices.RemoveAt(num);
				}
			}
		}

		private void MoveVisibleToHidden(DeviceModel device)
		{
			if (Devices.Contains(device))
			{
				Devices.Remove(device);
			}
			if (!HiddenDevices.Contains(device))
			{
				HiddenDevices.Add(device);
			}
			HasDevices = Devices.Count > 0;
			EmptyStateVisibility = (HasDevices ? Visibility.Collapsed : Visibility.Visible);
			Apply24GTrialBatteryRestriction();
			RefreshTrayIconFromDevices();
			UpdateTrayToolTip();
		}

		private void MoveHiddenToVisible(DeviceModel device)
		{
			if (HiddenDevices.Contains(device))
			{
				HiddenDevices.Remove(device);
			}
			if (!Devices.Contains(device))
			{
				int index = DeviceOrderService.A(Devices, device);
				Devices.Insert(index, device);
			}
			HasDevices = Devices.Count > 0;
			EmptyStateVisibility = (HasDevices ? Visibility.Collapsed : Visibility.Visible);
			Apply24GTrialBatteryRestriction();
			RefreshTrayIconFromDevices();
			UpdateTrayToolTip();
		}

