		public void UpdateMultiBatteryDevice(string name, string? deviceId, DeviceSource source, int leftBattery, int rightBattery, int caseBattery, string connectionStatus, bool isCharging)
		{
			if (!string.IsNullOrEmpty(name))
			{
				int num = ComputeMainBattery(leftBattery, rightBattery);
				bool unsupported = num < 0;
				UpdateBattery(name, deviceId, num, connectionStatus, unsupported, source, isSleeping: false, isRazerInterruptMode: false, isCharging);
				DeviceModel deviceModel = FindTrackedDevice(name, deviceId, source);
				if (deviceModel != null)
				{
					deviceModel.AirPodsLeftBattery = leftBattery;
					deviceModel.AirPodsRightBattery = rightBattery;
