		public void UpdateAirPodsBattery(string name, string? deviceId, int leftBattery, int rightBattery, int caseBattery, string connectionStatus, bool isCharging)
		{
			if (!string.IsNullOrEmpty(name))
			{
				string key = deviceId ?? name;
				DateTime utcNow = DateTime.UtcNow;
				if (!_airPodsLastUiUpdateAt.TryGetValue(key, out var value) || !(utcNow - value < AirPodsUiUpdateThrottle))
				{
					_airPodsLastUiUpdateAt[key] = utcNow;
					UpdateMultiBatteryDevice(name, deviceId, DeviceSource.AirPods, leftBattery, rightBattery, caseBattery, connectionStatus, isCharging);
				}
			}
		}

		private static int ComputeMainBattery(int left, int right)
		{
			List<int> list = new List<int>();
			if (left >= 0)
			{
				list.Add(left);
			}
			if (right >= 0)
			{
				list.Add(right);
			}
			if (list.Count > 0)
			{
				return list.Min();
			}
			return -1;
		}

		private DeviceModel? FindTrackedDevice(string name, string? deviceId, DeviceSource source)
		{
			string userConfigKey = ResolveUserConfigKey(name, deviceId, source);
			if (!string.IsNullOrEmpty(deviceId))
			{
				return FindByDeviceId(deviceId) ?? FindHiddenByDeviceId(deviceId) ?? FindByUserConfigKey(userConfigKey) ?? FindHiddenByUserConfigKey(userConfigKey);
			}
			return FindByName(name) ?? FindHiddenByName(name) ?? FindByUserConfigKey(userConfigKey) ?? FindHiddenByUserConfigKey(userConfigKey);
		}

