		private void Apply24GTrialBatteryRestriction()
		{
			this.ExportPolicyChanged?.Invoke();
			try
			{
				bool flag = App.Current.Services.GetService(typeof(B.O)) is B.O o && !o.IsPurchased;
				if (!(App.Current.Services.GetService(typeof(C.q)) is C.q q))
				{
					return;
				}
				HashSet<DeviceSource> hashSet = new HashSet<DeviceSource>();
				foreach (DeviceModel device in Devices)
				{
					device.IsBatteryRestricted = q.A(device.Source, !flag, false, hashSet);
					if (device.IsBatteryRestricted)
					{
						device.IsLowBattery = false;
					}
				}
				foreach (DeviceModel hiddenDevice in HiddenDevices)
				{
					hiddenDevice.IsBatteryRestricted = q.A(hiddenDevice.Source, !flag, true, hashSet);
					if (hiddenDevice.IsBatteryRestricted)
					{
						hiddenDevice.IsLowBattery = false;
					}
				}
			}
			catch
			{
			}
		}

