				ApplyPersistedPresentation(deviceModel, name, deviceId, source);
				if (!string.IsNullOrEmpty(deviceId) && !string.Equals(deviceModel.DeviceId, deviceId, StringComparison.OrdinalIgnoreCase))
				{
					if (IsBluetoothUiSource(source))
					{
						Logger.a($"[FindOrCreateDevice][Bluetooth] 设备身份迁移：Name='{name}', OldDeviceId='{deviceModel.DeviceId}', NewDeviceId='{deviceId}', OldSource={deviceModel.Source}, NewSource={source}", "FindOrCreateDevice", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 2162);
					}
					deviceModel.DeviceId = deviceId;
				}
				DeviceOrderService.a(deviceModel);
				return deviceModel;
			}
			DeviceModel deviceModel2 = new DeviceModel
			{
				Name = name,
				DeviceId = deviceId,
				UserConfigKey = ResolveUserConfigKey(name, deviceId, source),
				BatteryLevel = -1,
				LastUpdated = DateTime.Now,
				IsAlternateStyle = (Devices.Count % 2 != 0),
				Source = source
			};
			deviceModel2.IsPlaceholder = DeviceIdentity.A(deviceId);
			if (!deviceModel2.IsPlaceholder)
			{
				ApplyPersistedPresentation(deviceModel2, name, deviceId, source);
			}
			DeviceOrderService.a(deviceModel2);
			int num = DeviceOrderService.A(Devices, deviceModel2);
			Devices.Insert(num, deviceModel2);
			HasDevices = Devices.Count > 0;
			EmptyStateVisibility = (HasDevices ? Visibility.Collapsed : Visibility.Visible);
			Logger.A($"[FindOrCreateDevice] 创建新设备，插入位置={num}，当前设备总数={Devices.Count}", "FindOrCreateDevice", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 2199);
			return deviceModel2;
		}

