		private Microsoft.UI.Dispatching.DispatcherQueue? GetUiQueue()
		{
			Microsoft.UI.Dispatching.DispatcherQueue dispatcherQueue = _uiQueue;
			if ((object)dispatcherQueue == null)
			{
				Microsoft.UI.Xaml.Window? mainWindow = App.MainWindow;
				if ((object)mainWindow == null)
				{
					return null;
				}
				dispatcherQueue = mainWindow.DispatcherQueue;
			}
			return dispatcherQueue;
		}

		private bool TryRunOnUiThread(Action action)
		{
			Microsoft.UI.Dispatching.DispatcherQueue uiQueue = GetUiQueue();
			if (uiQueue == null)
			{
				return false;
			}
			if (uiQueue.HasThreadAccess)
			{
				action();
				return true;
			}
			return uiQueue.TryEnqueue(delegate
			{
				try
				{
					action();
				}
				catch
				{
				}
			});
		}

