		private static bool VerifySignatureWithPem(string rawData, string signatureBase64, string publicKeyPem)
		{
			try
			{
				if (string.IsNullOrWhiteSpace(signatureBase64) || string.IsNullOrWhiteSpace(publicKeyPem))
				{
					return false;
				}
				string s = publicKeyPem.Trim().Replace("-----BEGIN PUBLIC KEY-----", "").Replace("-----END PUBLIC KEY-----", "")
					.Replace("\r", "")
					.Replace("\n", "");
				byte[] array = Convert.FromBase64String(s);
				using RSA rSA = RSA.Create();
				rSA.ImportSubjectPublicKeyInfo(array, out var _);
				byte[] bytes = Encoding.UTF8.GetBytes(rawData);
				byte[] signature = Convert.FromBase64String(signatureBase64);
				return rSA.VerifyData(bytes, signature, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
			}
			catch (System.Exception)
			{
				return false;
			}
		}

		private static string LoadPublicKeyPem()
		{
			try
			{
				string baseDirectory = AppContext.BaseDirectory;
				string path = System.IO.Path.Combine(baseDirectory, "Assets", "public_key.pem");
				if (File.Exists(path))
				{
					return File.ReadAllText(path);
				}
				string path2 = System.IO.Path.Combine(Directory.GetCurrentDirectory(), "Assets", "public_key.pem");
				if (File.Exists(path2))
				{
					return File.ReadAllText(path2);
				}
				return string.Empty;
			}
			catch (System.Exception)
			{
				return string.Empty;
			}
		}

