		private void CheckSingleDeviceAlert(DeviceModel device)
		{
			if (string.IsNullOrEmpty(device.Name))
			{
				return;
			}
			if (device.BatteryLevel < 0)
			{
				LogBatteryUpdate(device.Source, $"[Alert] 跳过未知电量设备: {device.Name}, battery={device.BatteryLevel}");
				return;
			}
			VoiceRuleModel voiceRule;
			bool flag = TryGetVoiceRule(device, out voiceRule);
			int[] array;
			int num;
			if (flag && voiceRule != null && voiceRule.Thresholds.Length != 0)
			{
				array = (from t in voiceRule.Thresholds.Where((int t) => t > 0 && t <= 100).Distinct()
					orderby t
					select t).ToArray();
				if (array.Length == 0)
				{
					array = new int[1] { B.I.LowBatteryThreshold };
				}
				int defaultValue = array.Max();
				num = array.FirstOrDefault((int t) => device.BatteryLevel <= t, defaultValue);
			}
			else
			{
				array = new int[1] { B.I.LowBatteryThreshold };
				num = B.I.LowBatteryThreshold;
			}
			bool flag2 = ((flag && voiceRule != null) ? voiceRule.Enabled : B.I.EnableLowBatteryAlert);
			bool useToastNotification = B.I.UseToastNotification;
			bool customVoiceEnabled = B.I.CustomVoiceEnabled;
			LogBatteryUpdate(device.Source, $"[Alert] 检查低电量提醒: {device.Name}, 电量={device.BatteryLevel}%, 触发阈值={num}%, 所有阈值=[{string.Join(",", array)}], 启用={flag2}, 使用新规则={flag}");
			if (device.BatteryLevel <= num)
			{
				string value = ((!string.IsNullOrEmpty(device.DeviceId)) ? device.DeviceId : device.Name);
				string text = $"{value}_T{num}";
				if (!_remindedDevices.Contains(text))
				{
					LogBatteryUpdate(device.Source, $"[Alert] 触发低电量提醒: {device.Name} 电量 {device.BatteryLevel}%，阈值 {num}%（首次提醒）");
					bool flag3 = false;
					if (flag2)
					{
						if (flag && voiceRule != null && voiceRule.VoicePackIds.Length != 0)
						{
							Logger.A($"[Alert] Phase 2: 使用新规则系统，语音包数量: {voiceRule.VoicePackIds.Length}, 播放模式: {voiceRule.PlayMode}", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3361);
							try
							{
								string text2 = SelectVoiceFromRule(voiceRule);
								if (!string.IsNullOrEmpty(text2))
								{
									VoicePackModel voicePackModel = b.S.A(text2);
									if (voicePackModel != null)
									{
										Logger.A($"[Alert] Phase 2: 找到语音包: {voicePackModel.Name} ({voicePackModel.FileName}), 时长={voicePackModel.Duration}秒", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3373);
										B.p.A(voicePackModel.FileName);
										LogBatteryUpdate(device.Source, $"[Alert] Phase 2: 已调用播放自定义语音: {device.Name} 电量 {device.BatteryLevel}%");
										flag3 = true;
									}
									else
									{
										Logger.a("[Alert] Phase 2: 语音包不存在（ID=" + text2 + "），使用系统提示音", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3380);
										flag3 = MessageBeep(48u);
									}
								}
								else
								{
									Logger.a("[Alert] Phase 2: SelectVoiceFromRule返回空ID，使用系统提示音", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3386);
									flag3 = MessageBeep(48u);
								}
							}
							catch (System.Exception ex)
							{
								Logger.A("[Alert] Phase 2: 自定义语音播放失败: " + ex.Message, ex, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3392);
								flag3 = MessageBeep(48u);
							}
						}
						else if (customVoiceEnabled)
						{
							string text3 = ((flag && voiceRule != null && voiceRule.VoicePackIds.Length != 0) ? voiceRule.VoicePackIds[0] : B.I.LowBatteryVoicePackId);
							Logger.A("[Alert] Phase 0兼容: 尝试播放自定义语音包: " + text3, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3403);
							try
							{
								VoicePackModel voicePackModel2 = b.S.A(text3);
								if (voicePackModel2 != null)
								{
									Logger.A($"[Alert] Phase 0兼容: 找到语音包: {voicePackModel2.Name} ({voicePackModel2.FileName}), 时长={voicePackModel2.Duration}秒", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3410);
									B.p.A(voicePackModel2.FileName);
									LogBatteryUpdate(device.Source, $"[Alert] Phase 0兼容: 已调用播放自定义语音: {device.Name} 电量 {device.BatteryLevel}%");
									flag3 = true;
								}
								else
								{
									Logger.a("[Alert] Phase 0兼容: 语音包不存在（ID=" + text3 + "），使用系统提示音", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3417);
									flag3 = MessageBeep(48u);
								}
							}
							catch (System.Exception ex2)
							{
								Logger.A("[Alert] Phase 0兼容: 自定义语音播放失败: " + ex2.Message, ex2, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3423);
								flag3 = MessageBeep(48u);
							}
						}
						else if (useToastNotification)
						{
							Logger.A("[Alert] 使用Toast通知", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3429);
							F.r r = _appNotificationService?.A(device.Name, device.BatteryLevel) ?? F.r.A(F.R.B, "AppNotificationService is unavailable.");
							if (r.Success)
							{
								flag3 = true;
							}
							else
							{
								B.I.UseToastNotification = false;
								Logger.a($"[Alert] Toast 发送失败，已关闭 Toast 并回退系统提示音: device={device.Name}, availability={r.Availability}, hresult={FormatHResult(r.HResult)}", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3444);
								flag3 = MessageBeep(48u);
							}
						}
						else
						{
							Logger.A("[Alert] 使用系统提示音（MessageBeep）", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3451);
							flag3 = MessageBeep(48u);
						}
					}
					else
					{
						LogBatteryUpdate(device.Source, $"[Alert] 低电量提醒已禁用: {device.Name} 电量 {device.BatteryLevel}%");
					}
					if (flag3)
					{
						_remindedDevices.Add(text);
						Logger.A("[Alert] 提醒已完成并写入标记: " + text, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3465);
					}
					else
					{
						Logger.a("[Alert] 提醒未成功，不写入标记: " + text, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3469);
					}
				}
				else
				{
					Logger.b($"[Alert] 已提醒过（阈值{num}%），跳过: {device.Name}", "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3474);
				}
				return;
			}
			int num2 = array.Max();
			if (device.BatteryLevel <= num2 + 5)
			{
				return;
			}
			string prefix = ((!string.IsNullOrEmpty(device.DeviceId)) ? device.DeviceId : device.Name) + "_";
			List<string> list = _remindedDevices.Where((string k) => k.StartsWith(prefix)).ToList();
			foreach (string item in list)
			{
				_remindedDevices.Remove(item);
				Logger.A("[Alert] 电量恢复，移除提醒标记: " + item, "CheckSingleDeviceAlert", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3489);
			}
		}

		private bool TryGetVoiceRule(DeviceModel device, out VoiceRuleModel? voiceRule)
		{
			try
			{
				string deviceId = ((!string.IsNullOrEmpty(device.DeviceId)) ? device.DeviceId : null);
				List<VoiceRuleModel> source = b.s.Instance.A(deviceId);
				voiceRule = source.FirstOrDefault((VoiceRuleModel r) => r.EventType == EventType.BatteryLow);
				if (voiceRule != null)
				{
					Logger.A($"[VoiceRule] 找到语音规则: DeviceId={voiceRule.DeviceId}, EventType={voiceRule.EventType}, Enabled={voiceRule.Enabled}", "TryGetVoiceRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3512);
					return true;
				}
				Logger.b("[VoiceRule] 未找到语音规则，将使用旧设置系统", "TryGetVoiceRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3516);
				voiceRule = null;
				return false;
			}
			catch (System.Exception ex)
			{
				Logger.A("[VoiceRule] 获取语音规则失败: " + ex.Message, ex, "TryGetVoiceRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3522);
				voiceRule = null;
				return false;
			}
		}

		private int ResolveVisualLowBatteryThreshold(string? deviceId)
		{
			try
			{
				string deviceId2 = (string.IsNullOrWhiteSpace(deviceId) ? null : deviceId);
				List<VoiceRuleModel> source = b.s.Instance.A(deviceId2);
				VoiceRuleModel voiceRuleModel = source.FirstOrDefault((VoiceRuleModel r) => r.EventType == EventType.BatteryLow);
				if (voiceRuleModel?.Thresholds != null)
				{
					int[] array = voiceRuleModel.Thresholds.Where((int t) => t > 0 && t <= 100).Distinct().ToArray();
					if (array.Length != 0)
					{
						return array.Max();
					}
				}
			}
			catch (System.Exception ex)
			{
				Logger.a("[VoiceRule] 解析低电量显示阈值失败，回退全局阈值: " + ex.Message, "ResolveVisualLowBatteryThreshold", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3551);
			}
			return B.I.LowBatteryThreshold;
		}

		private void RecalculateLowBatteryState(DeviceModel device, bool unsupported)
		{
			int num = ResolveVisualLowBatteryThreshold(device.DeviceId);
			device.IsLowBattery = !unsupported && device.BatteryLevel >= 0 && device.BatteryLevel <= num;
		}

		private string SelectVoiceFromRule(VoiceRuleModel rule)
		{
			if (rule.VoicePackIds == null || rule.VoicePackIds.Length == 0)
			{
				Logger.a("[SelectVoice] 语音包ID数组为空", "SelectVoiceFromRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3571);
				return string.Empty;
			}
			string text;
			switch (rule.PlayMode)
			{
			case VoicePlayMode.Single:
				text = rule.VoicePackIds[0];
				Logger.b("[SelectVoice] Single模式: " + text, "SelectVoiceFromRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3582);
				break;
			case VoicePlayMode.Rotate:
				rule.CurrentIndex %= rule.VoicePackIds.Length;
				text = rule.VoicePackIds[rule.CurrentIndex];
