				}
				break;
			case VoicePlayMode.Random:
			{
				Random random = new Random();
				int num = random.Next(0, rule.VoicePackIds.Length);
				text = rule.VoicePackIds[num];
				Logger.b($"[SelectVoice] Random模式: {text}, 索引: {num}", "SelectVoiceFromRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3608);
				break;
			}
			default:
				text = rule.VoicePackIds[0];
				Logger.a($"[SelectVoice] 未知的播放模式: {rule.PlayMode}，使用Single模式", "SelectVoiceFromRule", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\MainWindowViewModel.cs", 3614);
				break;
			}
