			Logger.b($"[PluginMarketplace][VM] SetPluginEnabledAsync begin pluginId={pluginId}, enabled={enabled}, purchased={_entitlement.IsPurchased}, loggedIn={B.i.IsLoggedIn}", "SetPluginEnabledAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\PluginMarketplaceViewModel.cs", 114);
			IsBusy = true;
			try
			{
				(bool, string) result = await _batteryMonitor.A(pluginId, enabled);
				Logger.b($"[PluginMarketplace][VM] SetPluginEnabledAsync serviceResult pluginId={pluginId}, enabled={enabled}, success={result.Item1}, message='{result.Item2}'", "SetPluginEnabledAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\PluginMarketplaceViewModel.cs", 119);
				RefreshPluginsSnapshot();
				Logger.b($"[PluginMarketplace][VM] SetPluginEnabledAsync afterRefresh pluginId={pluginId}, enabled={enabled}", "SetPluginEnabledAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\PluginMarketplaceViewModel.cs", 121);
				return result;
