				IsBusy = false;
				RefreshEntitlementBindings();
				Logger.b($"[PluginMarketplace][VM] SetPluginEnabledAsync end pluginId={pluginId}, enabled={enabled}", "SetPluginEnabledAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\PluginMarketplaceViewModel.cs", 128);
