		private void RefreshPluginsSnapshot()
		{
			List<C.P> list = (from p in _batteryMonitor.A()
				orderby p.Metadata.IsAddonRequired descending
				select p).ThenBy<C.P, string>((C.P p) => (!string.IsNullOrWhiteSpace(p.Metadata.BrandName)) ? p.Metadata.BrandName : p.Metadata.Id, StringComparer.OrdinalIgnoreCase).ToList();
			try
			{
				string value = string.Join(", ", list.Select((C.P p) => $"{p.Metadata.Id}={p.IsEnabled}"));
				Logger.b($"[PluginMarketplace][VM] RefreshPluginsSnapshot snapshotCount={list.Count}, snapshot=[{value}]", "RefreshPluginsSnapshot", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\PluginMarketplaceViewModel.cs", 149);
			}
			catch
			{
			}
			for (int num = Plugins.Count - 1; num >= 0; num--)
			{
				PluginMarketplaceItemViewModel existing = Plugins[num];
				if (!list.Any((C.P p) => string.Equals(p.Metadata.Id, existing.PluginId, StringComparison.OrdinalIgnoreCase)))
				{
					Plugins.RemoveAt(num);
				}
			}
			foreach (C.P plugin in list)
			{
				PluginMarketplaceItemViewModel pluginMarketplaceItemViewModel = Plugins.FirstOrDefault((PluginMarketplaceItemViewModel p) => string.Equals(p.PluginId, plugin.Metadata.Id, StringComparison.OrdinalIgnoreCase));
				if (pluginMarketplaceItemViewModel == null)
				{
					pluginMarketplaceItemViewModel = new PluginMarketplaceItemViewModel(plugin.Metadata);
					Plugins.Add(pluginMarketplaceItemViewModel);
				}
				pluginMarketplaceItemViewModel.UpdateFromPlugin(plugin);
				pluginMarketplaceItemViewModel.UpdateAddonPolicy(_batteryMonitor, _entitlement);
			}
			RefreshFilteredPlugins();
		}

		private void RefreshFilteredPlugins()
		{
			List<PluginMarketplaceItemViewModel> filtered = (from item in Plugins.Where(MatchesSearch)
				orderby item.IsEnabled descending
				select item).ToList();
			SyncFilteredPlugins(filtered);
			OnPropertyChanged("NoSearchResultsVisibility");
		}

		private bool MatchesSearch(PluginMarketplaceItemViewModel item)
		{
			string text = SearchText?.Trim() ?? string.Empty;
			if (string.IsNullOrEmpty(text))
			{
				return true;
			}
			return item.MatchesSearch(text);
		}

		private void SyncFilteredPlugins(IReadOnlyList<PluginMarketplaceItemViewModel> filtered)
		{
			for (int num = FilteredPlugins.Count - 1; num >= 0; num--)
			{
				PluginMarketplaceItemViewModel existing = FilteredPlugins[num];
				if (!filtered.Any((PluginMarketplaceItemViewModel item) => string.Equals(item.PluginId, existing.PluginId, StringComparison.OrdinalIgnoreCase)))
				{
					FilteredPlugins.RemoveAt(num);
				}
			}
			for (int num2 = 0; num2 < filtered.Count; num2++)
			{
				PluginMarketplaceItemViewModel pluginMarketplaceItemViewModel = filtered[num2];
				int num3 = IndexOfPlugin(FilteredPlugins, pluginMarketplaceItemViewModel.PluginId);
				if (num3 < 0)
				{
					FilteredPlugins.Insert(num2, pluginMarketplaceItemViewModel);
					continue;
				}
				if (FilteredPlugins[num3] != pluginMarketplaceItemViewModel)
				{
					FilteredPlugins[num3] = pluginMarketplaceItemViewModel;
				}
				if (num3 != num2)
				{
					FilteredPlugins.Move(num3, num2);
				}
			}
		}

		private static int IndexOfPlugin(ObservableCollection<PluginMarketplaceItemViewModel> items, string pluginId)
		{
			for (int i = 0; i < items.Count; i++)
			{
				if (string.Equals(items[i].PluginId, pluginId, StringComparison.OrdinalIgnoreCase))
				{
					return i;
				}
			}
			return -1;
		}

		private void RefreshEntitlementBindings()
		{
			OnPropertyChanged("AddonStatusText");
			OnPropertyChanged("IsLoggedIn");
			OnPropertyChanged("IsPurchased");
			OnPropertyChanged("BuyButtonVisibility");
			OnPropertyChanged("CanBuy");
			OnPropertyChanged("NoSearchResultsVisibility");
			foreach (PluginMarketplaceItemViewModel plugin in Plugins)
			{
				plugin.UpdateAddonPolicy(_batteryMonitor, _entitlement);
			}
		}

		private void OnEntitlementStateChanged()
		{
			RunOnUiThread(RefreshEntitlementBindings);
		}

		private void OnPluginStatesChanged()
		{
			RunOnUiThread(RefreshPluginsSnapshot);
		}

		private void RunOnUiThread(Action action)
		{
			Microsoft.UI.Dispatching.DispatcherQueue dispatcherQueue = _uiQueue ?? App.MainWindow?.DispatcherQueue;
			if (dispatcherQueue == null)
			{
				action();
			}
			else if (!dispatcherQueue.TryEnqueue(delegate
			{
				action();
			}))
			{
				action();
			}
		}

		public void Dispose()
		{
			if (!_disposed)
			{
				_disposed = true;
				_entitlement.StateChanged -= OnEntitlementStateChanged;
				_batteryMonitor.PluginStatesChanged -= OnPluginStatesChanged;
			}
		}

