		{
			Product = product ?? throw new ArgumentNullException("product");
			OfferKind = offerKind;
			Title = (string.IsNullOrWhiteSpace(title) ? product.Title : title);
			FeatureLines = featureLines ?? Array.Empty<string>();
			UnitPriceDesc = L("PurchaseWindow.Offer.UnitPriceDesc", "一次买断");
			(string, Microsoft.UI.Xaml.Media.FontFamily) tuple;
			switch (OfferKind)
			{
			case PurchaseOfferKind.ExeVip:
			case PurchaseOfferKind.StoreLegacyVip:
				tuple = ("\ud83d\udc51", new Microsoft.UI.Xaml.Media.FontFamily("Segoe UI Emoji"));
				break;
			case PurchaseOfferKind.ExeAddon24G:
			case PurchaseOfferKind.StoreLegacyAddon24G:
				tuple = ("\ue701", new Microsoft.UI.Xaml.Media.FontFamily("Segoe MDL2 Assets"));
				break;
			case PurchaseOfferKind.StorePro:
				tuple = ("✨", new Microsoft.UI.Xaml.Media.FontFamily("Segoe UI Emoji"));
				break;
			default:
				tuple = (string.Empty, new Microsoft.UI.Xaml.Media.FontFamily("Segoe UI"));
				break;
			}
			(TitleIcon, TitleIconFontFamily) = tuple;
		}

		private static string L(string key, string fallback)
		{
			string text = F.g.A(key);
			if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, key, StringComparison.Ordinal))
			{
				return text;
			}
			return fallback;
		}

		public void SetPrice(decimal price)
		{
			PriceLoaded = true;
			ListPrice = price;
			DiscountAmount = 0m;
			PriceValue = price;
			PriceText = $"¥ {price:F2}";
			PriceVersion = string.Empty;
			PromotionType = null;
			NotifyQuotePresentationChanged();
		}

		public void SetQuote(PriceQuoteDto quote)
		{
			PriceLoaded = true;
			ListPrice = quote.ListPrice;
			DiscountAmount = quote.DiscountAmount;
			PriceValue = quote.PayableAmount;
			PriceText = $"¥ {quote.PayableAmount:F2}";
			PriceVersion = quote.PriceVersion;
			PromotionType = quote.PromotionType;
			NotifyQuotePresentationChanged();
		}

		public void SetOrderSnapshot(CreateOrderV2ResponseDto order)
		{
			PriceLoaded = true;
			ListPrice = order.ListPrice;
			DiscountAmount = order.DiscountAmount;
			PriceValue = order.PayableAmount;
			PriceText = $"¥ {order.PayableAmount:F2}";
			PriceVersion = order.PriceVersion;
			NotifyQuotePresentationChanged();
		}

		public void SetStoreFormattedPrice(string formattedPrice)
		{
			PriceLoaded = true;
			ListPrice = 0m;
			DiscountAmount = 0m;
			PriceValue = 0m;
			PriceText = (string.IsNullOrWhiteSpace(formattedPrice) ? "--" : formattedPrice);
			PriceVersion = string.Empty;
			PromotionType = null;
			NotifyQuotePresentationChanged();
		}

		public void SetPriceUnavailable()
		{
			PriceLoaded = false;
			ListPrice = 0m;
			DiscountAmount = 0m;
			PriceValue = 0m;
			PriceText = "--";
			PriceVersion = string.Empty;
			PromotionType = null;
			NotifyQuotePresentationChanged();
		}

