		public PurchaseViewModel(B.o apiService, F.i entitlementService, B.O addonEntitlement)
		{
			_apiService = apiService;
			_entitlementService = entitlementService;
			_addonEntitlement = addonEntitlement;
			B.i.AuthStateChanged += OnAuthStateChanged;
		}

		public void Initialize(PurchaseEntryPoint entryPoint)
		{
			_entryPoint = entryPoint;
			PurchaseNavigationState purchaseNavigationState = PurchaseNavigation.Resolve(entryPoint);
			Product = ((purchaseNavigationState.SelectedServerType == 2) ? PurchaseProduct.Addon24G() : PurchaseProduct.Vip());
			if (F.n.a())
			{
				BuildStoreOffers(_entitlementService.CurrentSnapshot);
			}
			else
			{
				EnsureOffersInitialized();
			}
			RefreshComparisonTiers();
			_currentOrderId = null;
			IsQrCodeVisible = false;
			CurrentPage = purchaseNavigationState.Page;
			SelectedOffer = ResolveInitialSelection(purchaseNavigationState.SelectedServerType);
			StatusMessage = L("PurchaseWindow.Status.Loading", "正在加载...");
		}

		public void Initialize(PurchaseProduct product)
		{
			Initialize((product != null && product.ServerType == 2) ? PurchaseEntryPoint.Addon24G : PurchaseEntryPoint.Purchase);
		}

		[RelayCommand]
		public async Task LoadAsync()
