						purchaseOfferViewModel2.OwnershipText = (flag3 ? L("PurchaseWindow.Ownership.PurchasedPendingOnlineVerification", "已购买（待联网验证）") : L("PurchaseWindow.Ownership.PendingOnlineVerification", "待联网验证"));
