		private PurchaseOfferViewModel? GetOffer(int serverType)
		{
			return Offers.FirstOrDefault((PurchaseOfferViewModel o) => o.ServerType == serverType);
		}

		private PurchaseOfferViewModel? ResolveInitialSelection(int? requestedServerType)
		{
			if (!F.n.a())
			{
				if (!requestedServerType.HasValue)
				{
					return null;
				}
				return GetOffer(requestedServerType.Value);
			}
			PurchaseOfferViewModel purchaseOfferViewModel = Offers.FirstOrDefault((PurchaseOfferViewModel o) => o.OfferKind == PurchaseOfferKind.StorePro);
			if (purchaseOfferViewModel != null)
			{
				if (!purchaseOfferViewModel.IsOwned)
				{
					return purchaseOfferViewModel;
				}
				return null;
			}
			if (requestedServerType == 2)
			{
				PurchaseOfferViewModel purchaseOfferViewModel2 = Offers.FirstOrDefault((PurchaseOfferViewModel o) => o.OfferKind == PurchaseOfferKind.StoreLegacyAddon24G);
				if (purchaseOfferViewModel2 != null && !purchaseOfferViewModel2.IsOwned)
				{
					return purchaseOfferViewModel2;
				}
			}
			if (requestedServerType == 1)
			{
				PurchaseOfferViewModel purchaseOfferViewModel3 = Offers.FirstOrDefault((PurchaseOfferViewModel o) => o.OfferKind == PurchaseOfferKind.StoreLegacyVip);
				if (purchaseOfferViewModel3 != null && !purchaseOfferViewModel3.IsOwned)
				{
					return purchaseOfferViewModel3;
				}
			}
			return Offers.FirstOrDefault((PurchaseOfferViewModel o) => !o.IsOwned);
		}

		private IReadOnlyList<string> GetComparisonBenefits(Func<MembershipComparisonBenefit, bool> filter)
		{
			return (from benefit in MembershipComparisonCatalog.Benefits.Where(filter)
				select L("PurchaseWindow.Comparison." + benefit.Key, GetComparisonFallback(benefit.Key))).ToArray();
		}

