		private void NotifyComparisonStateChanged()
		{
			RefreshComparisonTiers();
			OnPropertyChanged("VipComparisonPriceText");
			OnPropertyChanged("Addon24GComparisonPriceText");
			OnPropertyChanged("VipComparisonOwnershipText");
			OnPropertyChanged("Addon24GComparisonOwnershipText");
			OnPropertyChanged("VipComparisonActionVisibility");
			OnPropertyChanged("Addon24GComparisonActionVisibility");
		}

		private static string DescribeOffer(PurchaseOfferViewModel? offer)
		{
			if (offer == null)
			{
				return "(none)";
			}
			return $"title={offer.Title}, offerKind={offer.OfferKind}, serverType={offer.ServerType}, storeKind={offer.StoreProductKind}, owned={offer.IsOwned}, priceLoaded={offer.PriceLoaded}, priceText={offer.PriceText}, priceValue={offer.PriceValue:F2}";
		}

		private void UpdateTotalPriceFromSelection()
		{
			if (SelectedOffer == null)
			{
				TotalPrice = 0m;
			}
			else
			{
				TotalPrice = (SelectedOffer.PriceLoaded ? SelectedOffer.PriceValue : 0m);
			}
		}

		private void EnsureOffersInitialized()
		{
			if (!F.n.a() && Offers.Count <= 0)
			{
				Offers.Add(new PurchaseOfferViewModel(PurchaseProduct.Vip(), L("PurchaseWindow.Offer.Vip.Title", "VIP"), new string[3]
				{
					L("PurchaseWindow.Offer.Vip.Feature1", "解锁全部精美主题与皮肤"),
					L("PurchaseWindow.Offer.Vip.Feature2", "解锁自定义语音和历史电量高级功能"),
					L("PurchaseWindow.Offer.Vip.Feature3", "解锁高级托盘图标定制")
				}, PurchaseOfferKind.ExeVip));
				Offers.Add(new PurchaseOfferViewModel(PurchaseProduct.Addon24G(), L("PurchaseWindow.Offer.Addon24G.Title", "2.4G 扩展包"), new string[3]
				{
					L("PurchaseWindow.Offer.Addon24G.Feature1", "解除设备数量限制（无限连接）"),
					L("PurchaseWindow.Offer.Addon24G.Feature2", "解除插件启用状态记忆限制"),
					L("PurchaseWindow.Offer.Addon24G.Feature3", "解除历史电量数据限制")
				}, PurchaseOfferKind.ExeAddon24G));
			}
		}

		private void BuildStoreOffers(F.J snapshot)
		{
			if (F.n.a())
			{
				PurchaseOfferKind? previousKind = SelectedOffer?.OfferKind;
				Offers.Clear();
				switch (F.o.A(snapshot.StoreOwnershipSchemaVersion, snapshot.LegacyVipOwned, snapshot.LegacyAddon24GOwned, snapshot.ProOwned))
				{
				case F.P.A:
					SelectedOffer = null;
					_storeOwnershipReady = false;
					RefreshComparisonTiers();
					return;
				case F.P.a:
				{
					PurchaseOfferViewModel item = new PurchaseOfferViewModel(PurchaseProduct.Pro(), L("PurchaseWindow.Offer.Pro.Title", "EasyBluetooth Pro"), new string[3]
					{
						L("PurchaseWindow.Offer.Pro.Feature1", "一次购买，永久解锁 VIP 全部功能"),
						L("PurchaseWindow.Offer.Pro.Feature2", "永久解锁 2.4G 扩展包"),
						L("PurchaseWindow.Offer.Pro.Feature3", "包含后续的 Pro 权益更新")
					}, PurchaseOfferKind.StorePro)
					{
						IsOwned = snapshot.ProOwned,
						OwnershipText = (snapshot.ProOwned ? L("PurchaseWindow.Ownership.ProPurchased", "已购买，已永久解锁 VIP 与 2.4G") : L("PurchaseWindow.Ownership.NotPurchased", "未购买"))
					};
					Offers.Add(item);
					break;
				}
				default:
					Offers.Add(CreateLegacyStoreOffer(PurchaseOfferKind.StoreLegacyVip, PurchaseProduct.Vip(), snapshot.LegacyVipOwned));
					Offers.Add(CreateLegacyStoreOffer(PurchaseOfferKind.StoreLegacyAddon24G, PurchaseProduct.Addon24G(), snapshot.LegacyAddon24GOwned));
					break;
				}
				SelectedOffer = (previousKind.HasValue ? Offers.FirstOrDefault((PurchaseOfferViewModel o) => o.OfferKind == previousKind.Value && !o.IsOwned) : null);
				if (SelectedOffer == null)
				{
					PurchaseOfferViewModel purchaseOfferViewModel = (SelectedOffer = ResolveInitialSelection(PurchaseNavigation.Resolve(_entryPoint).SelectedServerType));
				}
				RefreshComparisonTiers();
			}
		}

		private PurchaseOfferViewModel CreateLegacyStoreOffer(PurchaseOfferKind offerKind, PurchaseProduct product, bool owned)
		{
			bool flag = offerKind == PurchaseOfferKind.StoreLegacyVip;
			return new PurchaseOfferViewModel(product, flag ? L("PurchaseWindow.Offer.Vip.Title", "VIP") : L("PurchaseWindow.Offer.Addon24G.Title", "2.4G 扩展包"), (!flag) ? new string[3]
			{
				L("PurchaseWindow.Offer.Addon24G.Feature1", "解除设备数量限制（无限连接）"),
				L("PurchaseWindow.Offer.Addon24G.Feature2", "解除插件启用状态记忆限制"),
				L("PurchaseWindow.Offer.Addon24G.Feature3", "解除历史电量数据限制")
			} : new string[3]
