		private static bool TryGetStoreProduct(IReadOnlyDictionary<string, StoreProduct>? products, string productId, out StoreProduct? product)
		{
			product = null;
			if (products == null || string.IsNullOrWhiteSpace(productId))
			{
				return false;
			}
			foreach (System.Collections.Generic.KeyValuePair<string, StoreProduct> product2 in products)
			{
				if (string.Equals(Normalize(product2.Key.Trim()), Normalize(productId.Trim()), StringComparison.OrdinalIgnoreCase))
				{
					product = product2.Value;
					return true;
				}
			}
			return false;
			static string Normalize(string value)
			{
				int num = value.IndexOf('/');
				if (num <= 0)
				{
					return value;
				}
				return value.Substring(0, num);
			}
		}

		private static bool SnapshotOwnsStoreProduct(F.J snapshot, F.p productKind)
		{
