			{
				ApiOperationResult<ReferralDashboardDto> apiOperationResult = await _apiService.B();
				if (!apiOperationResult.Success || apiOperationResult.Data == null)
				{
					ShowMessage(apiOperationResult.Message, error: true);
					return;
				}
				if (!apiOperationResult.Data.ModuleEnabled || string.Equals(apiOperationResult.Data.CampaignStatus, "DRAFT", StringComparison.OrdinalIgnoreCase))
				{
					App.Current.u();
					return;
				}
				ApplyDashboard(apiOperationResult.Data);
				if (resetInvites)
				{
					Invites.Clear();
					_nextPage = 1L;
					_inviteTotal = 0L;
