			}
		}

		[RelayCommand]
		private async Task BindAsync()
		{
			if (!CanBindInviteCode || IsPaused)
			{
				return;
			}
			string text = (BindingInput ?? string.Empty).Trim().ToUpperInvariant();
			if (text.Length != 8)
			{
				ShowMessage("请输入 8 位邀请码。", error: true);
				return;
			}
			IsBusy = true;
			try
			{
				ApiOperationResult<ReferralBindingDto> apiOperationResult = await _apiService.A(text);
				if (!apiOperationResult.Success)
				{
					ShowMessage(apiOperationResult.Message, error: true);
					return;
				}
				BindingInput = string.Empty;
				ShowMessage("邀请码绑定成功，绑定关系不可更改。", error: false);
				await LoadAsync(resetInvites: false);
				await App.Current.a(true);
			}
			finally
			{
				IsBusy = false;
			}
		}

		public async Task RedeemAsync(int serverType)
		{
			ReferralRewardCardViewModel referralRewardCardViewModel = ((serverType == 1) ? VipReward : AddonReward);
			if (!referralRewardCardViewModel.IsActionEnabled || IsPaused)
			{
				return;
			}
			referralRewardCardViewModel.IsActionEnabled = false;
			IsBusy = true;
			try
			{
				ApiOperationResult<ReferralRewardDto> apiOperationResult = await _apiService.A(serverType, default(CancellationToken));
				if (!apiOperationResult.Success)
				{
					ShowMessage(apiOperationResult.Message, error: true);
					return;
				}
				await LoadAsync(resetInvites: false);
				bool refreshFailed = false;
				try
				{
					await _entitlementService.A(default(CancellationToken), false);
					_addonEntitlementService.A(_entitlementService.CurrentSnapshot);
					await App.Current.a(true);
				}
				catch (System.Exception ex)
				{
					refreshFailed = true;
					Logger.a("[Referral] Reward redeemed but entitlement refresh failed: " + ex.Message, "RedeemAsync", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\ReferralCenterViewModel.cs", 209);
				}
				ShowMessage(refreshFailed ? "兑换已成功，权益状态刷新失败，请稍后手动刷新。" : "兑换成功，权益状态已更新。", refreshFailed);
			}
			finally
			{
				IsBusy = false;
			}
		}

