		[RelayCommand]
		private void CopyInviteCode()
		{
			if (!CanCopyInviteCode || string.IsNullOrWhiteSpace(InviteCode))
			{
				return;
			}
			try
			{
				DataPackage dataPackage = new DataPackage();
				dataPackage.SetText(InviteCode);
				Clipboard.SetContent(dataPackage);
				ShowMessage("邀请码已复制。", error: false);
			}
			catch (System.Exception ex)
			{
				Logger.a("[Referral] Copy invite code failed: " + ex.Message, "CopyInviteCode", "F:\\Desktop\\项目\\蓝牙代码\\EasyBluetooth\\EasyBluetooth\\ViewModels\\ReferralCenterViewModel.cs", 260);
				ShowMessage("复制失败，请手动复制邀请码。", error: true);
			}
		}

		private async Task LoadInvitesCoreAsync()
		{
			ApiOperationResult<PagedResponse<ReferralInviteDto>> apiOperationResult = await _apiService.A(_nextPage, 20L);
			if (!apiOperationResult.Success || apiOperationResult.Data == null)
			{
				ShowMessage(apiOperationResult.Message, error: true);
				return;
			}
			_inviteTotal = apiOperationResult.Data.Total;
			foreach (ReferralInviteDto item in apiOperationResult.Data.Records.OrderByDescending((ReferralInviteDto item) => item.QualifiedAt ?? item.BoundAt).ThenByDescending<ReferralInviteDto, string>((ReferralInviteDto item) => item.MaskedPhone, StringComparer.Ordinal))
			{
				Invites.Add(new ReferralInviteItemViewModel
				{
					MaskedPhone = item.MaskedPhone,
					StatusText = BindingStatus(item.Status),
					TimeText = FormatInviteTime(item)
				});
			}
			_nextPage++;
			LoadMoreVisibility = ((Invites.Count >= _inviteTotal) ? Visibility.Collapsed : Visibility.Visible);
		}

		private void ApplyDashboard(ReferralDashboardDto dashboard)
		{
			IsPaused = string.Equals(dashboard.CampaignStatus, "PAUSED", StringComparison.OrdinalIgnoreCase);
			CampaignStatusText = (IsPaused ? "活动已暂停" : "活动进行中");
			CampaignDescription = (IsPaused ? "历史记录与进度可查看；暂停期间不能绑定、推广或兑换。" : "邀请好友注册并完成首次有效付费，可分别兑换 VIP 与 2.4G 扩展包。");
			InviteCode = dashboard.InviteCode ?? string.Empty;
			CanCopyInviteCode = !IsPaused && !string.IsNullOrWhiteSpace(InviteCode);
			BindingStatusText = (string.IsNullOrWhiteSpace(dashboard.BindingStatus) ? (dashboard.BindUnavailableMessage ?? "当前账号尚未绑定邀请码") : BindingStatus(dashboard.BindingStatus));
			CanBindInviteCode = dashboard.CanBindInviteCode && !IsPaused;
			BindingInputVisibility = ((!CanBindInviteCode) ? Visibility.Collapsed : Visibility.Visible);
			InviteSummaryText = $"有效邀请 {dashboard.EffectiveInviteCount} 人，可用名额 {dashboard.UnallocatedInviteCount} 人";
			FullOwnerVisibility = ((!dashboard.FullyOwned) ? Visibility.Collapsed : Visibility.Visible);
			FullOwnerMessage = (dashboard.FullyOwned ? "你已拥有全部权益，可继续查看邀请记录，但不再显示奖励兑换按钮。" : string.Empty);
			ApplyReward(VipReward, dashboard.VipReward, dashboard);
			ApplyReward(AddonReward, dashboard.Addon24GReward, dashboard);
		}

		private static void ApplyReward(ReferralRewardCardViewModel card, ReferralRewardStateDto? reward, ReferralDashboardDto dashboard)
		{
			int value = reward?.RequiredCount ?? ((card.ServerType == 1) ? 1 : 2);
			card.ProgressText = $"需要 {value} 位有效付费好友";
			if (dashboard.FullyOwned || (reward != null && reward.Owned))
			{
				card.StatusText = "已拥有";
			}
			else if (string.Equals(reward?.Status, "ACTIVE", StringComparison.OrdinalIgnoreCase))
			{
				card.StatusText = "已兑换，权益有效";
			}
			else if (string.Equals(reward?.Status, "REVOKED", StringComparison.OrdinalIgnoreCase))
			{
				card.StatusText = ((reward != null && reward.Redeemable) ? "此前奖励因退款撤销，现已重新满足条件" : "因相关邀请退款，当前条件不足");
			}
			else
			{
				card.StatusText = ((reward != null && reward.Redeemable) ? "已满足兑换条件" : "继续邀请即可解锁");
			}
			b.L l = b.l.A(dashboard.FullyOwned, reward?.Owned ?? false, reward?.Status, reward?.Redeemable ?? false, dashboard.CampaignStatus);
			card.ActionVisibility = ((l == b.L.A) ? Visibility.Collapsed : Visibility.Visible);
			card.ActionText = ((l == b.L.B) ? "重新兑换" : "兑换");
			card.IsActionEnabled = l != b.L.A;
		}

		private static string BindingStatus(string? status)
		{
			return status?.ToUpperInvariant() switch
			{
				"PENDING" => "已绑定，等待首次有效付费", 
				"EFFECTIVE" => "已成为有效付费邀请", 
				"INVALIDATED" => "相关付费已退款，当前不再计入；绑定关系不可更改", 
				_ => "未绑定", 
			};
		}

		private static string FormatInviteTime(ReferralInviteDto item)
		{
			DateTime? dateTime = item.QualifiedAt ?? item.BoundAt;
			if (!dateTime.HasValue)
			{
				return string.Empty;
			}
			return dateTime.Value.ToString("yyyy-MM-dd HH:mm");
		}

		private void ShowMessage(string? message, bool error)
		{
			InfoMessage = (string.IsNullOrWhiteSpace(message) ? "操作失败，请稍后重试。" : message);
			IsError = error;
			IsInfoOpen = true;
		}

		[GeneratedCode("CommunityToolkit.Mvvm.SourceGenerators.ObservablePropertyGenerator", "8.4.0.0")]
		private void OnBindingInputChanged(string value)
		{
			string text = Regex.Replace((value ?? string.Empty).Trim().ToUpperInvariant(), "[^ABCDEFGHJKMNPQRSTUVWXYZ23456789]", string.Empty);
			if (!string.Equals(value, text, StringComparison.Ordinal))
			{
				BindingInput = text;
			}
		}
	}
