	internal static class ChangelogHelpers
	{
		public static bool IsReleaseApplicableToChannel(ChangelogRelease release, UpdateChannelType channelType)
		{
			string channel = release.Channel;
			if (string.IsNullOrWhiteSpace(channel))
			{
				return true;
			}
			string[] array = channel.Split(new char[5] { '/', ',', ';', '|', ' ' }, StringSplitOptions.RemoveEmptyEntries);
			string[] array2 = array;
			foreach (string a in array2)
			{
				if (string.Equals(a, "all", StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
				if (string.Equals(a, channelType.ToString(), StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
			}
			return false;
		}

		public static ChangelogRelease? FindLatestApplicableRelease(ChangelogRoot root, UpdateChannelType channelType)
		{
			if (root.Releases == null || root.Releases.Count == 0)
			{
				return null;
			}
			ChangelogRelease result = null;
			Version version = null;
			foreach (ChangelogRelease release in root.Releases)
			{
				if (IsReleaseApplicableToChannel(release, channelType))
				{
					Version version2 = release.TryParseVersion();
					if (!(version2 == null) && (version == null || version2 > version))
					{
						version = version2;
						result = release;
					}
				}
			}
			return result;
		}

		public static string BuildReleaseNotesText(ChangelogRelease release, bool preferChinese)
		{
			IReadOnlyList<string> displayNotes = release.GetDisplayNotes(preferChinese);
			if (displayNotes.Count == 0)
			{
				return string.Empty;
			}
			return string.Join(Environment.NewLine, displayNotes.Select((string n) => "- " + n));
		}
	}
