	public sealed class ChangelogRelease
	{
		[JsonPropertyName("version")]
		public string? Version { get; set; }

		[JsonPropertyName("date")]
		public string? Date { get; set; }

		[JsonPropertyName("channel")]
		public string? Channel { get; set; }

		[JsonPropertyName("notes")]
		public List<string> Notes { get; set; } = new List<string>();

		[JsonPropertyName("notesEn")]
		public List<string> NotesEn { get; set; } = new List<string>();

		public Version? TryParseVersion()
		{
			if (string.IsNullOrWhiteSpace(Version))
			{
				return null;
			}
			return VersionHelpers.TryParseVersion(Version);
		}

		public IReadOnlyList<string> GetDisplayNotes(bool preferChinese)
		{
			if (preferChinese)
			{
				return NormalizeNotes(Notes);
			}
			List<string> list = NormalizeNotes(NotesEn);
			if (list.Count <= 0)
			{
				return NormalizeNotes(Notes);
			}
			return list;
		}

		private static List<string> NormalizeNotes(List<string>? notes)
		{
			if (notes == null || notes.Count == 0)
			{
				return new List<string>();
			}
			List<string> list = new List<string>(notes.Count);
			foreach (string note in notes)
			{
				if (!string.IsNullOrWhiteSpace(note))
				{
					list.Add(note.Trim());
				}
			}
			return list;
		}
	}
