	public static class UpdateNotesPolicy
	{
		public static string ResolveViewedVersionBaseline(string? lastViewedVersion, string? legacyAcknowledgedVersion, Version currentVersion)
		{
			if (TryParseVersion(lastViewedVersion, out Version version))
			{
				return version.ToString();
			}
			if (TryParseVersion(legacyAcknowledgedVersion, out Version version2))
			{
				return version2.ToString();
			}
			return currentVersion.ToString();
		}

		public static bool HasUnreadUpdateNotes(Version? latestVersion, string? viewedVersion)
		{
			if (latestVersion != null && TryParseVersion(viewedVersion, out Version version))
			{
				return latestVersion > version;
			}
			return false;
		}

		private static bool TryParseVersion(string? value, out Version version)
		{
			version = new Version(0, 0);
			if (string.IsNullOrWhiteSpace(value))
			{
				return false;
			}
			string input = value.Trim().TrimStart('v', 'V');
			return Version.TryParse(input, out version);
		}
	}
	public sealed class UpdateNotesStateService
	{
		private readonly UpdateConfigurationService _configuration;

		public ChangelogRoot? CurrentRoot { get; private set; }

		public ChangelogRelease? LatestApplicableRelease { get; private set; }

		public bool HasUnreadUpdateNotes { get; private set; }

		public string LatestVersionText => LatestApplicableRelease?.Version?.Trim() ?? string.Empty;

		public event EventHandler? StateChanged;

		public UpdateNotesStateService(UpdateConfigurationService configuration)
		{
			_configuration = configuration;
		}

		public void Apply(ChangelogRoot? root)
		{
			CurrentRoot = root;
			LatestApplicableRelease = ((root == null) ? null : ChangelogHelpers.FindLatestApplicableRelease(root, _configuration.GetChannelType()));
			EnsureViewedVersionBaseline();
			Version latestVersion = LatestApplicableRelease?.TryParseVersion();
			HasUnreadUpdateNotes = UpdateNotesPolicy.HasUnreadUpdateNotes(latestVersion, B.I.LastViewedChangelogVersion);
			this.StateChanged?.Invoke(this, EventArgs.Empty);
		}

		public bool MarkLatestViewed()
		{
			Version version = LatestApplicableRelease?.TryParseVersion();
			if (version == null)
			{
				return false;
			}
			B.I.LastViewedChangelogVersion = version.ToString();
			HasUnreadUpdateNotes = false;
			this.StateChanged?.Invoke(this, EventArgs.Empty);
			return true;
		}

		private static void EnsureViewedVersionBaseline()
		{
			if (string.IsNullOrWhiteSpace(B.I.LastViewedChangelogVersion))
			{
				B.I.LastViewedChangelogVersion = UpdateNotesPolicy.ResolveViewedVersionBaseline(B.I.LastViewedChangelogVersion, B.I.LastAcknowledgedStartupChangelogVersion, AppVersionProvider.GetCurrentVersion());
			}
		}
	}
	internal static class VersionHelpers
	{
		public static Version? TryParseVersion(string input)
		{
			if (string.IsNullOrWhiteSpace(input))
			{
				return null;
			}
			string text = input.Trim();
			if (text.StartsWith("v", StringComparison.OrdinalIgnoreCase))
			{
				text = text.Substring(1);
			}
			string text2 = new string(text.TakeWhile((char c) => char.IsDigit(c) || c == '.').ToArray());
			if (string.IsNullOrWhiteSpace(text2))
			{
				return null;
			}
			if (Version.TryParse(text2, out Version result))
			{
				return result;
			}
			return null;
		}

		public static int CompareVersions(string? a, string? b)
		{
			Version version = ((a == null) ? null : TryParseVersion(a));
			Version version2 = ((b == null) ? null : TryParseVersion(b));
			if (version == null && version2 == null)
			{
				return 0;
			}
			if (version == null)
			{
				return -1;
			}
			if (version2 == null)
			{
				return 1;
			}
			return version.CompareTo(version2);
		}
	}
