	public enum DeviceType
	{
		General,
		Headphones,
		Mouse,
		Keyboard,
		Speaker,
		Gamepad
	}
	public static class DeviceTypeExtensions
	{
		public static DeviceType DetectDeviceType(string? deviceName)
		{
			if (string.IsNullOrWhiteSpace(deviceName))
			{
				return DeviceType.General;
			}
			string text = deviceName.ToLowerInvariant();
			if (text.Contains("xbox") || text.Contains("ps") || text.Contains("playstation") || text.Contains("switch") || text.Contains("joycon") || text.Contains("dualsense") || text.Contains("dualshock") || text.Contains("gamepad") || text.Contains("controller") || text.Contains("手柄"))
			{
				return DeviceType.Gamepad;
			}
			if (text.Contains("airpods") || text.Contains("pod") || text.Contains("beats") || text.Contains("headphone") || text.Contains("headset") || text.Contains("earphone") || text.Contains("earbuds") || text.Contains("buds") || text.Contains("inzone") || text.Contains("wf-") || text.Contains("wh-") || text.Contains("耳机") || text.Contains("耳塞") || text.Contains("头戴"))
			{
				return DeviceType.Headphones;
			}
			if (text.Contains("speaker") || text.Contains("soundbar") || text.Contains("audio") || text.Contains("homepod") || text.Contains("echo") || text.Contains("音箱") || text.Contains("音响"))
			{
				return DeviceType.Speaker;
			}
			if (text.Contains("keyboard") || text.Contains("mechanical") || text.Contains("键盘"))
			{
				return DeviceType.Keyboard;
			}
			if (text.Contains("mouse") || text.Contains("鼠标"))
			{
				return DeviceType.Mouse;
			}
			return DeviceType.General;
		}

		public static string ToUnifiedApiValue(this DeviceType deviceType)
		{
			return deviceType switch
			{
				DeviceType.Headphones => "headphones", 
				DeviceType.Mouse => "mouse", 
				DeviceType.Keyboard => "keyboard", 
				DeviceType.Speaker => "speaker", 
				DeviceType.Gamepad => "gamepad", 
				_ => "general", 
			};
		}
	}
