		OpenPurchaseWindow,
		RequestExeLogin
	}
	public static class PurchaseNavigation
	{
		public const int VipServerType = 1;

		public const int Addon24GServerType = 2;

		public static PurchaseNavigationState Resolve(PurchaseEntryPoint entryPoint)
		{
			return entryPoint switch
			{
				PurchaseEntryPoint.GeneralComparison => new PurchaseNavigationState(PurchasePage.Comparison, null), 
				PurchaseEntryPoint.Addon24G => new PurchaseNavigationState(PurchasePage.Offers, 2), 
				PurchaseEntryPoint.VipFeature => new PurchaseNavigationState(PurchasePage.Offers, 1), 
				_ => new PurchaseNavigationState(PurchasePage.Offers, 1), 
			};
		}

		public static HeaderUpgradeAction GetHeaderUpgradeAction(bool vipOwned, bool addon24GOwned)
		{
			if (vipOwned)
			{
				if (addon24GOwned)
				{
					return HeaderUpgradeAction.Hidden;
				}
				return HeaderUpgradeAction.Addon24GOffer;
			}
			return HeaderUpgradeAction.VipComparison;
		}

		public static PurchaseAccessAction GetAccessAction(bool isPackaged, bool isLoggedIn, PurchaseEntryPoint entryPoint)
		{
			if (isPackaged || isLoggedIn || entryPoint == PurchaseEntryPoint.GeneralComparison)
			{
				return PurchaseAccessAction.OpenPurchaseWindow;
			}
			return PurchaseAccessAction.RequestExeLogin;
		}

		public static PurchaseEntryPoint? GetEntryToResumeAfterLogin(bool isLoggedIn, PurchaseEntryPoint? pendingEntryPoint)
		{
			if (!isLoggedIn)
			{
				return null;
			}
			return pendingEntryPoint;
		}
	}
